export default "{\"schema\":\"ai-brain.inert-reference.v1\",\"trust\":\"untrusted_reference_only\",\"records\":[{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/components/assistant-flow-edit-card.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6ebc229a33bf005ed5f9cdc838fc0878561a18b7608cff89d8109db5005bccc7\",\"content\":\"import { Check, ChevronLeft, ChevronRight, X } from \\\"lucide-react\\\";\\nimport { useCallback, useState } from \\\"react\\\";\\nimport type { FlowAction } from \\\"@/controllers/API/queries/agentic\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport {\\n  GHOST_PRIMARY_BUTTON,\\n  GHOST_SECONDARY_BUTTON,\\n} from \\\"../helpers/button-styles\\\";\\n\\ninterface FlowEditCarouselProps {\\n  actions: FlowAction[];\\n  onUpdateAction: (id: string, status: \\\"applied\\\" | \\\"dismissed\\\") => void;\\n}\\n\\n// Long edit descriptions (the LLM restates the entire new value, e.g. a full\\n// system_prompt) balloon the card. Above this length the description is\\n// clamped to a few lines with a Show more/less toggle so the card stays\\n// compact while the full intent is still one click away before approving.\\nconst DESCRIPTION_CLAMP_CHARS = 160;\\n\\nconst CLAMP_STYLE = {\\n  display: \\\"-webkit-box\\\",\\n  WebkitLineClamp: 3,\\n  WebkitBoxOrient: \\\"vertical\\\" as const,\\n  overflow: \\\"hidden\\\",\\n};\\n\\nfunction formatValue(value: unknown): string {\\n  if (value === null || value === undefined) return \\\"(empty)\\\";\\n  if (typeof value === \\\"string\\\")\\n    return value.length > 60 ? value.slice(0, 57) + \\\"...\\\" : value;\\n  return String(value);\\n}\\n\\nfunction FlowEditCard({\\n  action,\\n  onAccept,\\n  onDismiss,\\n}: {\\n  action: FlowAction;\\n  onAccept: () => void;\\n  onDismiss: () => void;\\n}) {\\n  const isPending = action.status === \\\"pending\\\";\\n  const [expanded, setExpanded] = useState(false);\\n  const fullNew = action.new_value == null ? \\\"\\\" : String(action.new_value);\\n  const fullOld = action.old_value == null ? \\\"\\\" : String(action.old_value);\\n  // The summary is a short clean preview, so \\\"Show more\\\" must key off the\\n  // VALUE: a long / multi-line proposed value still has to be fully\\n  // reviewable before approving (kept the description-length clause so\\n  // pre-existing long-summary behavior is preserved).\\n  const isLong =\\n    fullNew.length > 80 ||\\n    fullNew.includes(\\\"\\\\n\\\") ||\\n    (action.description?.length ?? 0) > DESCRIPTION_CLAMP_CHARS;\\n  const collapsed = isLong && !expanded;\\n\\n  return (\\n    <div className=\\\"flex flex-col gap-2\\\">\\n      <div className=\\\"flex flex-col gap-0.5\\\">\\n        <p\\n          className=\\\"text-xs text-muted-foreground\\\"\\n          style={collapsed ? CLAMP_STYLE : undefined}\\n        >\\n          {action.description}\\n        </p>\\n        {isLong && (\\n          <button\\n            type=\\\"button\\\"\\n            className=\\\"self-start text-xs font-medium text-primary hover:underline\\\"\\n            onClick={() => setExpanded((v) => !v)}\\n          >\\n            {expanded ? \\\"Show less\\\" : \\\"Show more\\\"}\\n          </button>\\n        )}\\n      </div>\\n\\n      {collapsed ? (\\n        <div className=\\\"flex items-center gap-2 rounded bg-muted/50 px-3 py-2 text-xs font-mono\\\">\\n          <span className=\\\"text-destructive line-through\\\">\\n            {formatValue(action.old_value)}\\n          </span>\\n          <span className=\\\"text-muted-foreground\\\">-&gt;</span>\\n          <span className=\\\"text-accent-emerald-foreground\\\">\\n            {formatValue(action.new_value)}\\n          </span>\\n        </div>\\n      ) : (\\n        <div className=\\\"flex max-h-72 flex-col gap-1 overflow-auto rounded bg-muted/50 px-3 py-2 text-xs font-mono\\\">\\n          <span className=\\\"whitespace-pre-wrap break-words text-destructive line-through\\\">\\n            {fullOld || \\\"(empty)\\\"}\\n          </span>\\n          <span className=\\\"text-muted-foreground\\\">-&gt;</span>\\n          <span className=\\\"whitespace-pre-wrap break-words text-accent-emerald-foreground\\\">\\n            {fullNew || \\\"(empty)\\\"}\\n          </span>\\n        </div>\\n      )}\\n\\n      {isPending && (\\n        <div className=\\\"flex items-center gap-2\\\">\\n          <button\\n            type=\\\"button\\\"\\n            className={GHOST_PRIMARY_BUTTON}\\n            onClick={onAccept}\\n          >\\n            <Check className=\\\"h-3 w-3\\\" />\\n            Accept\\n          </button>\\n          <button\\n            type=\\\"button\\\"\\n            className={GHOST_SECONDARY_BUTTON}\\n            onClick={onDismiss}\\n          >\\n            <X className=\\\"h-3 w-3\\\" />\\n            Dismiss\\n          </button>\\n        </div>\\n      )}\\n\\n      {action.status === \\\"applied\\\" && (\\n        <div className=\\\"flex h-7 items-center gap-1 text-xs font-medium text-accent-emerald-foreground\\\">\\n          <Check className=\\\"h-3 w-3\\\" />\\n          Applied\\n        </div>\\n      )}\\n\\n      {action.status === \\\"dismissed\\\" && (\\n        <div className=\\\"flex h-7 items-center gap-1 text-xs font-medium text-muted-foreground/60 line-through\\\">\\n          Dismissed\\n        </div>\\n      )}\\n    </div>\\n  );\\n}\\n\\nexport function FlowEditCarousel({\\n  actions,\\n  onUpdateAction,\\n}: FlowEditCarouselProps) {\\n  const [currentIndex, setCurrentIndex] = useState(0);\\n  const setNodes = useFlowStore((state) => state.setNodes);\\n\\n  const current = actions[currentIndex];\\n\\n  // Apply a single action's JSON Patch to the ReactFlow nodes. Shared by\\n  // single-Accept and Accept-All so the canvas is actually mutated in\\n  // both paths (Accept All previously only flagged actions applied,\\n  // persisting the unchanged canvas \u2014 silent data loss).\\n  const applyActionPatch = useCallback(\\n    (action: (typeof actions)[number]) => {\\n      if (!action?.patch) return;\\n      for (const op of action.patch) {\\n        if (op.op !== \\\"replace\\\") continue;\\n        // Parse the path: /data/nodes/{idx}/data/node/template/{field}/value\\n        const parts = op.path.split(\\\"/\\\").filter(Boolean);\\n        // parts: [\\\"data\\\", \\\"nodes\\\", idx, \\\"data\\\", \\\"node\\\", \\\"template\\\", field, \\\"value\\\"]\\n        if (parts[0] === \\\"data\\\" && parts[1] === \\\"nodes\\\" && parts.length >= 8) {\\n          const nodeIdx = parseInt(parts[2], 10);\\n          const field = parts[6];\\n          setNodes((prevNodes) =>\\n            prevNodes.map((node, i) => {\\n              if (i !== nodeIdx) return node;\\n              const template = (node.data as Record<string, unknown>)?.node as\\n                | Record<string, unknown>\\n                | undefined;\\n              if (!template?.template) return node;\\n              const tmpl = template.template as Record<\\n                string,\\n                Record<string, unknown>\\n              >;\\n              if (!tmpl[field]) return node;\\n              return {\\n                ...node,\\n                data: {\\n                  ...node.data,\\n                  node: {\\n                    ...(node.data as Record<string, unknown>).node,\\n                    template: {\\n                      ...tmpl,\\n                      [field]: { ...tmpl[field], value: op.value },\\n                    },\\n                  },\\n                },\\n              };\\n            }),\\n          );\\n        }\\n      }\\n    },\\n    [setNodes],\\n  );\\n\\n  const handleAccept = useCallback(() => {\\n    const action = actions[currentIndex];\\n    if (!action?.patch) return;\\n    applyActionPatch(action);\\n    onUpdateAction(action.id, \\\"applied\\\");\\n    // Auto-advance to next pending\\n    const nextPending = actions.findIndex(\\n      (a, i) => i > currentIndex && a.status === \\\"pending\\\",\\n    );\\n    if (nextPending >= 0) setCurrentIndex(nextPending);\\n  }, [actions, currentIndex, onUpdateAction, applyActionPatch]);\\n\\n  const handleDismiss = useCallback(() => {\\n    if (!current) return;\\n    onUpdateAction(current.id, \\\"dismissed\\\");\\n    const nextPending = actions.findIndex(\\n      (a, i) => i > currentIndex && a.status === \\\"pending\\\",\\n    );\\n    if (nextPending >= 0) setCurrentIndex(nextPending);\\n  }, [actions, current, currentIndex, onUpdateAction]);\\n\\n  const handleAcceptAll = useCallback(() => {\\n    for (const action of actions) {\\n      if (action.status === \\\"pending\\\") {\\n        applyActionPatch(action);\\n        onUpdateAction(action.id, \\\"applied\\\");\\n      }\\n    }\\n  }, [actions, onUpdateAction, applyActionPatch]);\\n\\n  const pendingCount = actions.filter((a) => a.status === \\\"pending\\\").length;\\n\\n  // Guard AFTER all hooks so the hook count is stable across renders\\n  // (actions grow incrementally as edit_field events arrive).\\n  if (!current) return null;\\n\\n  return (\\n    <div className=\\\"max-w-[80%] rounded-lg border border-border bg-muted/30 p-4\\\">\\n      {/* Header with pagination */}\\n      <div className=\\\"mb-3 flex items-center justify-between\\\">\\n        <span className=\\\"text-xs font-semibold text-foreground\\\">\\n          Proposed Changes\\n        </span>\\n        <div className=\\\"flex items-center gap-2\\\">\\n          {actions.length > 1 && (\\n            <>\\n              <button\\n                type=\\\"button\\\"\\n                className=\\\"rounded p-0.5 hover:bg-muted disabled:opacity-30\\\"\\n                onClick={() => setCurrentIndex((i) => Math.max(0, i - 1))}\\n                disabled={currentIndex === 0}\\n              >\\n                <ChevronLeft className=\\\"h-3.5 w-3.5\\\" />\\n              </button>\\n              <span className=\\\"text-xs text-muted-foreground\\\">\\n                {currentIndex + 1}/{actions.length}\\n              </span>\\n              <button\\n                type=\\\"button\\\"\\n                className=\\\"rounded p-0.5 hover:bg-muted disabled:opacity-30\\\"\\n                onClick={() =>\\n                  setCurrentIndex((i) => Math.min(actions.length - 1, i + 1))\\n                }\\n                disabled={currentIndex === actions.length - 1}\\n              >\\n                <ChevronRight className=\\\"h-3.5 w-3.5\\\" />\\n              </button>\\n            </>\\n          )}\\n          {pendingCount > 1 && (\\n            <button\\n              type=\\\"button\\\"\\n              className=\\\"ml-2 rounded-md bg-primary px-2 py-0.5 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary/90\\\"\\n              onClick={handleAcceptAll}\\n            >\\n              Accept All ({pendingCount})\\n            </button>\\n          )}\\n        </div>\\n      </div>\\n\\n      <FlowEditCard\\n        action={current}\\n        onAccept={handleAccept}\\n        onDismiss={handleDismiss}\\n      />\\n    </div>\\n  );\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/components/assistant-flow-preview.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e061a274a1e86870aad40e313f13d303700736652e35f020c1fd266d53065a3c\",\"content\":\"import {\\n  Background,\\n  type Edge,\\n  type Node,\\n  ReactFlow,\\n  ReactFlowProvider,\\n} from \\\"@xyflow/react\\\";\\nimport { ArrowRight, Check, GitBranch, Undo2, X } from \\\"lucide-react\\\";\\nimport { useCallback, useMemo, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport useAssistantManagerStore from \\\"@/stores/assistantManagerStore\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport {\\n  evaluatePlacement,\\n  getPresentComponentTypes,\\n} from \\\"@/utils/componentConstraints\\\";\\nimport type { FlowProposalStatus } from \\\"../assistant-panel.types\\\";\\nimport {\\n  GHOST_PRIMARY_BUTTON,\\n  GHOST_SECONDARY_BUTTON,\\n} from \\\"../helpers/button-styles\\\";\\n\\nconst APPROVED_DISPLAY_DURATION_MS = 3000;\\n\\n/**\\n * Above this many components the thumbnail is an unreadable tangle, so the\\n * mini-canvas is skipped and a short notice is shown instead. The flow can\\n * still be added/replaced \u2014 only the visual preview is suppressed.\\n */\\nconst MAX_PREVIEW_NODES = 7;\\n\\ninterface FlowPreviewData {\\n  flow: Record<string, unknown>;\\n  name: string;\\n  nodeCount: number;\\n  edgeCount: number;\\n  graph: string;\\n}\\n\\ninterface AssistantFlowPreviewProps {\\n  flowPreview: FlowPreviewData;\\n  /**\\n   * When provided, switches the card into gated mode:\\n   *  - \\\"pending\\\"   \u2192 Continue + Dismiss buttons, canvas untouched\\n   *  - \\\"applied\\\"   \u2192 muted preview with \\\"Added to canvas\\\" label\\n   *  - \\\"dismissed\\\" \u2192 muted preview with \\\"Dismissed\\\" label\\n   *\\n   * When omitted, falls back to the legacy \\\"Add to Flow\\\" path which\\n   * pastes the flow into the existing canvas via `paste()`.\\n   */\\n  status?: FlowProposalStatus;\\n  /**\\n   * Apply handler. Receives a ``mode`` so the card can distinguish\\n   * additive vs destructive intent. Callers from older code paths that\\n   * still invoke ``onApply()`` (zero args) default to ``\\\"replace\\\"`` for\\n   * backwards compatibility with the original single-button design.\\n   */\\n  onApply?: (mode: \\\"replace\\\" | \\\"add\\\") => void;\\n  onDismiss?: () => void;\\n  /** Client-side undo: restore the pre-apply canvas snapshot. */\\n  onRevert?: () => void;\\n  /** A pre-apply snapshot exists, so Revert is offered in the applied state\\n   * AND after the card re-enables (pending) so the last apply stays undoable. */\\n  canRevert?: boolean;\\n}\\n\\nconst defaultNodeStyle = {\\n  fontSize: \\\"11px\\\",\\n  fontWeight: 500,\\n  padding: \\\"4px 10px\\\",\\n  borderRadius: \\\"8px\\\",\\n  border: \\\"1px solid var(--border)\\\",\\n  background: \\\"var(--background)\\\",\\n  color: \\\"var(--foreground)\\\",\\n};\\n\\n/** Extract ReactFlow-compatible nodes and edges from the flow data */\\nfunction extractReactFlowData(flow: Record<string, unknown>): {\\n  nodes: Node[];\\n  edges: Edge[];\\n} {\\n  const data = flow.data as\\n    | {\\n        nodes?: {\\n          id?: string;\\n          position?: { x: number; y: number };\\n          data?: { type?: string; id?: string };\\n        }[];\\n        edges?: {\\n          id?: string;\\n          source?: string;\\n          target?: string;\\n        }[];\\n      }\\n    | undefined;\\n\\n  if (!data?.nodes) return { nodes: [], edges: [] };\\n\\n  // Scale down positions to fit the mini canvas\\n  const positions = data.nodes.map((n) => n.position ?? { x: 0, y: 0 });\\n  const maxX = Math.max(...positions.map((p) => p.x), 1);\\n  const scale = 250 / maxX;\\n\\n  const nodes: Node[] = data.nodes.map((n, i) => ({\\n    id: n.id || `node-${i}`,\\n    type: \\\"default\\\",\\n    position: {\\n      x: (n.position?.x ?? 0) * scale + 20,\\n      y: (n.position?.y ?? 0) * scale + 30,\\n    },\\n    data: { label: n.data?.type || \\\"Unknown\\\" },\\n    style: defaultNodeStyle,\\n    draggable: false,\\n    selectable: false,\\n  }));\\n\\n  const edges: Edge[] = (data.edges ?? []).map((e, i) => ({\\n    id: e.id || `edge-${i}`,\\n    source: e.source || \\\"\\\",\\n    target: e.target || \\\"\\\",\\n    animated: true,\\n    style: { stroke: \\\"var(--muted-foreground)\\\", strokeWidth: 1.5 },\\n  }));\\n\\n  return { nodes, edges };\\n}\\n\\nfunction proposalConflictsWithCanvas(\\n  flow: Record<string, unknown>,\\n  canvasNodes: unknown,\\n): boolean {\\n  const proposalNodes =\\n    (flow.data as { nodes?: { data?: { type?: string } }[] } | undefined)\\n      ?.nodes ?? [];\\n  if (proposalNodes.length === 0) return false;\\n\\n  const presentTypes = getPresentComponentTypes(\\n    Array.isArray(canvasNodes)\\n      ? (canvasNodes as { data?: { type?: string } }[])\\n      : [],\\n  );\\n  return proposalNodes.some(\\n    (node) => evaluatePlacement(node.data?.type, presentTypes) !== null,\\n  );\\n}\\n\\nexport function AssistantFlowPreview({\\n  flowPreview,\\n  status,\\n  onApply,\\n  onDismiss,\\n  onRevert,\\n  canRevert = false,\\n}: AssistantFlowPreviewProps) {\\n  const { t } = useTranslation();\\n  const [showApproved, setShowApproved] = useState(false);\\n  const paste = useFlowStore((state) => state.paste);\\n  const canvasNodes = useFlowStore((state) => state.nodes);\\n\\n  const { nodes, edges } = useMemo(\\n    () => extractReactFlowData(flowPreview.flow),\\n    [flowPreview.flow],\\n  );\\n\\n  // Merging a proposal that carries its own entry point into a canvas that\\n  // already has one produces the duplicate COMPONENT_CONSTRAINTS forbids.\\n  const addWouldConflict = useMemo(\\n    () => proposalConflictsWithCanvas(flowPreview.flow, canvasNodes),\\n    [flowPreview.flow, canvasNodes],\\n  );\\n\\n  // The reported node count is authoritative; fall back to the parsed nodes.\\n  const nodeCount = flowPreview.nodeCount || nodes.length;\\n  const previewDisabled = nodeCount > MAX_PREVIEW_NODES;\\n\\n  const handleAddToFlow = useCallback(() => {\\n    const data = flowPreview.flow.data as\\n      | {\\n          nodes?: Record<string, unknown>[];\\n          edges?: Record<string, unknown>[];\\n        }\\n      | undefined;\\n    if (!data?.nodes) return;\\n\\n    paste(\\n      { nodes: data.nodes as never[], edges: (data.edges ?? []) as never[] },\\n      { x: 100, y: 100 },\\n    );\\n    // Same reveal rule as the gated apply path: once the flow lands on the canvas,\\n    // get the panel out of the way so the user can see it.\\n    useAssistantManagerStore.getState().setAssistantSidebarOpen(false);\\n    setShowApproved(true);\\n    setTimeout(() => setShowApproved(false), APPROVED_DISPLAY_DURATION_MS);\\n  }, [flowPreview.flow, paste]);\\n\\n  const revertButton = (\\n    <button\\n      type=\\\"button\\\"\\n      data-testid=\\\"assistant-flow-revert-button\\\"\\n      className={GHOST_SECONDARY_BUTTON}\\n      onClick={() => onRevert?.()}\\n      title=\\\"Restore the canvas to its state before this flow was applied\\\"\\n    >\\n      <Undo2 className=\\\"h-3.5 w-3.5\\\" />\\n      <span>Revert</span>\\n    </button>\\n  );\\n\\n  return (\\n    <div className=\\\"max-w-[80%] py-1\\\">\\n      {/* Flow header */}\\n      <div className=\\\"mb-2 flex items-center gap-2\\\">\\n        <GitBranch className=\\\"h-4 w-4 text-foreground/80\\\" />\\n        <div className=\\\"flex flex-col\\\">\\n          <span className=\\\"text-sm font-semibold text-foreground\\\">\\n            {flowPreview.name || \\\"Untitled Flow\\\"}\\n          </span>\\n          <span className=\\\"text-xs text-muted-foreground\\\">\\n            {flowPreview.nodeCount} components, {flowPreview.edgeCount}{\\\" \\\"}\\n            connections\\n          </span>\\n        </div>\\n      </div>\\n\\n      {/* Preview is skipped for large graphs \u2014 a thumbnail of that many\\n          nodes is an unreadable tangle. The flow can still be added. */}\\n      {previewDisabled && (\\n        <div className=\\\"mb-3 w-fit rounded-md border border-dashed border-border bg-muted/30 px-3 py-1.5 text-xs text-muted-foreground\\\">\\n          Preview disabled \u2014 too many components ({nodeCount}).\\n        </div>\\n      )}\\n\\n      {/* Mini flow canvas */}\\n      {!previewDisabled && nodes.length > 0 && (\\n        <div className=\\\"mb-3 h-[120px] w-full overflow-hidden rounded-md bg-muted/30\\\">\\n          <ReactFlowProvider>\\n            <ReactFlow\\n              nodes={nodes}\\n              edges={edges}\\n              fitView\\n              fitViewOptions={{ padding: 0.3 }}\\n              nodesDraggable={false}\\n              nodesConnectable={false}\\n              elementsSelectable={false}\\n              panOnDrag={false}\\n              zoomOnScroll={false}\\n              zoomOnPinch={false}\\n              zoomOnDoubleClick={false}\\n              preventScrolling={false}\\n              proOptions={{ hideAttribution: true }}\\n            >\\n              <Background id=\\\"assistant-preview-bg\\\" gap={12} size={0.5} />\\n            </ReactFlow>\\n          </ReactFlowProvider>\\n        </div>\\n      )}\\n\\n      {status === \\\"pending\\\" && addWouldConflict && (\\n        <div\\n          data-testid=\\\"assistant-flow-replace-only-notice\\\"\\n          className=\\\"mb-2 rounded-md border border-dashed border-border bg-muted/30 px-3 py-1.5 text-xs text-muted-foreground\\\"\\n        >\\n          {t(\\\"assistant.flowProposalReplaceOnly\\\")}\\n        </div>\\n      )}\\n\\n      {/* Actions */}\\n      <div className=\\\"flex items-center gap-1\\\">{renderActions()}</div>\\n    </div>\\n  );\\n\\n  function renderActions() {\\n    if (status === \\\"pending\\\") {\\n      return (\\n        <>\\n          {/* Primary action: ADD to canvas. Non-destructive, keeps existing\\n              nodes/edges intact. Keeps the legacy `assistant-flow-continue-button`\\n              alias so older E2E specs still find it. */}\\n          {!addWouldConflict && (\\n            <button\\n              type=\\\"button\\\"\\n              data-testid=\\\"assistant-flow-add-button\\\"\\n              data-add-button-alias=\\\"assistant-flow-continue-button\\\"\\n              className={GHOST_PRIMARY_BUTTON}\\n              onClick={() => onApply?.(\\\"add\\\")}\\n            >\\n              <span>Add to canvas</span>\\n              <ArrowRight className=\\\"h-3.5 w-3.5\\\" />\\n            </button>\\n          )}\\n          {/* Destructive \u2014 promoted to primary styling when it is the only\\n              way to apply the proposal. */}\\n          <button\\n            type=\\\"button\\\"\\n            data-testid=\\\"assistant-flow-replace-button\\\"\\n            className={\\n              addWouldConflict ? GHOST_PRIMARY_BUTTON : GHOST_SECONDARY_BUTTON\\n            }\\n            onClick={() => onApply?.(\\\"replace\\\")}\\n            title=\\\"Discard the current canvas and replace it with this flow\\\"\\n          >\\n            <span>Replace canvas</span>\\n            {addWouldConflict && <ArrowRight className=\\\"h-3.5 w-3.5\\\" />}\\n          </button>\\n          <button\\n            type=\\\"button\\\"\\n            data-testid=\\\"assistant-flow-dismiss-button\\\"\\n            className={GHOST_SECONDARY_BUTTON}\\n            onClick={() => onDismiss?.()}\\n          >\\n            <X className=\\\"h-3.5 w-3.5\\\" />\\n            <span>Dismiss</span>\\n          </button>\\n          {/* After an apply the card re-enables but the last apply stays\\n              undoable until the user reverts or applies again. */}\\n          {canRevert && revertButton}\\n        </>\\n      );\\n    }\\n    if (status === \\\"applied\\\") {\\n      return (\\n        <>\\n          <div className=\\\"flex h-7 items-center gap-1.5 px-2 text-sm font-medium text-accent-emerald-foreground\\\">\\n            <Check className=\\\"h-3.5 w-3.5\\\" />\\n            <span>Added to canvas</span>\\n          </div>\\n          {revertButton}\\n        </>\\n      );\\n    }\\n    if (status === \\\"dismissed\\\") {\\n      return (\\n        <div className=\\\"flex h-7 items-center gap-1.5 px-2 text-sm font-medium text-muted-foreground line-through\\\">\\n          <span>Dismissed</span>\\n        </div>\\n      );\\n    }\\n    // Legacy \\\"Add to Flow\\\" path \u2014 no status prop provided\\n    if (showApproved) {\\n      return (\\n        <div className=\\\"flex h-7 items-center gap-1.5 px-2 text-sm font-medium text-accent-emerald-foreground\\\">\\n          <Check className=\\\"h-3.5 w-3.5\\\" />\\n          <span>Added to flow</span>\\n        </div>\\n      );\\n    }\\n    return (\\n      <button\\n        type=\\\"button\\\"\\n        className={GHOST_PRIMARY_BUTTON}\\n        onClick={handleAddToFlow}\\n      >\\n        <span>Add to Flow</span>\\n        <ArrowRight className=\\\"h-3.5 w-3.5\\\" />\\n      </button>\\n    );\\n  }\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/helpers/__tests__/apply-flow-proposal.test.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e0136c7234827a52b99fced77f669232433e4b82543f5097406805b5f62b840d\",\"content\":\"/**\\n * Placement-policy enforcement on the proposal-apply path.\\n *\\n * A proposal is LLM-generated and can violate canvas placement policy\\n * (e.g. two ChatInputs \u2014 a singleton). The apply path must (a) enforce\\n * the policy in BOTH modes (\\\"add\\\" already filtered; \\\"replace\\\" bypassed\\n * the filter entirely) and (b) surface the dropped nodes to the user\\n * instead of silently diverging from what the proposal card advertised.\\n *\\n * Deterministic repro from the review finding: a proposal holding two\\n * ChatInputs yields [{type:\\\"ChatInput\\\",reason:\\\"singleton\\\"}] with no\\n * model involved.\\n */\\n\\nimport type { PendingFlowProposal } from \\\"../../assistant-panel.types\\\";\\nimport { applyFlowProposalToCanvas } from \\\"../apply-flow-proposal\\\";\\n\\ntype UpdateNodeInternalsFn = Parameters<typeof applyFlowProposalToCanvas>[2];\\nconst asInternals = (v: unknown): UpdateNodeInternalsFn =>\\n  v as UpdateNodeInternalsFn;\\n\\nconst setNodesAndEdges = jest.fn();\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: {\\n    getState: () => ({\\n      nodes: [],\\n      edges: [],\\n      setNodesAndEdges,\\n      reactFlowInstance: { fitView: jest.fn() },\\n    }),\\n  },\\n}));\\n\\nconst setNoticeData = jest.fn();\\njest.mock(\\\"@/stores/alertStore\\\", () => ({\\n  __esModule: true,\\n  default: { getState: () => ({ setNoticeData }) },\\n}));\\n\\njest.mock(\\\"@/i18n\\\", () => ({\\n  __esModule: true,\\n  default: { t: (key: string) => key },\\n}));\\n\\nconst node = (id: string, type: string) => ({\\n  id,\\n  position: { x: 0, y: 0 },\\n  data: { type },\\n});\\nconst edge = (id: string, source: string, target: string) => ({\\n  id,\\n  source,\\n  target,\\n});\\n\\n/** The exact shape from the finding: 5 nodes, 4 edges, second ChatInput violates singleton. */\\nconst twoChatInputProposal = (): PendingFlowProposal => ({\\n  flow: {\\n    data: {\\n      nodes: [\\n        node(\\\"ChatInput-a\\\", \\\"ChatInput\\\"),\\n        node(\\\"ChatInput-b\\\", \\\"ChatInput\\\"),\\n        node(\\\"ConditionalRouter-c\\\", \\\"ConditionalRouter\\\"),\\n        node(\\\"ChatOutput-d\\\", \\\"ChatOutput\\\"),\\n        node(\\\"ChatOutput-e\\\", \\\"ChatOutput\\\"),\\n      ],\\n      edges: [\\n        edge(\\\"e1\\\", \\\"ChatInput-a\\\", \\\"ConditionalRouter-c\\\"),\\n        edge(\\\"e2\\\", \\\"ChatInput-b\\\", \\\"ConditionalRouter-c\\\"),\\n        edge(\\\"e3\\\", \\\"ConditionalRouter-c\\\", \\\"ChatOutput-d\\\"),\\n        edge(\\\"e4\\\", \\\"ConditionalRouter-c\\\", \\\"ChatOutput-e\\\"),\\n      ],\\n    },\\n  },\\n  nodeCount: 5,\\n  edgeCount: 4,\\n});\\n\\nconst cleanProposal = (): PendingFlowProposal => ({\\n  flow: {\\n    data: {\\n      nodes: [\\n        node(\\\"ChatInput-a\\\", \\\"ChatInput\\\"),\\n        node(\\\"ChatOutput-b\\\", \\\"ChatOutput\\\"),\\n      ],\\n      edges: [edge(\\\"e1\\\", \\\"ChatInput-a\\\", \\\"ChatOutput-b\\\")],\\n    },\\n  },\\n  nodeCount: 2,\\n  edgeCount: 1,\\n});\\n\\nconst appliedIds = () => {\\n  const [nodes, edges] = setNodesAndEdges.mock.calls[0] as [\\n    Array<{ id: string }>,\\n    Array<{ id: string }>,\\n  ];\\n  return {\\n    nodeIds: nodes.map((n) => n.id),\\n    edgeIds: edges.map((e) => e.id),\\n  };\\n};\\n\\nbeforeEach(() => {\\n  setNodesAndEdges.mockClear();\\n  setNoticeData.mockClear();\\n});\\n\\ndescribe(\\\"applyFlowProposalToCanvas \u2014 placement policy\\\", () => {\\n  describe(\\\"add mode\\\", () => {\\n    it(\\\"should_surface_a_singleton_notice_when_a_proposed_node_is_dropped\\\", () => {\\n      applyFlowProposalToCanvas(\\n        twoChatInputProposal(),\\n        \\\"add\\\",\\n        asInternals(jest.fn()),\\n      );\\n\\n      expect(setNoticeData).toHaveBeenCalledTimes(1);\\n      expect(setNoticeData).toHaveBeenCalledWith({\\n        title: \\\"assistant.duplicateComponentsNotAdded\\\",\\n      });\\n    });\\n\\n    it(\\\"should_drop_the_violating_node_and_its_edges\\\", () => {\\n      applyFlowProposalToCanvas(\\n        twoChatInputProposal(),\\n        \\\"add\\\",\\n        asInternals(jest.fn()),\\n      );\\n\\n      const { nodeIds, edgeIds } = appliedIds();\\n      expect(nodeIds).toEqual([\\n        \\\"ChatInput-a\\\",\\n        \\\"ConditionalRouter-c\\\",\\n        \\\"ChatOutput-d\\\",\\n        \\\"ChatOutput-e\\\",\\n      ]);\\n      expect(edgeIds).toEqual([\\\"e1\\\", \\\"e3\\\", \\\"e4\\\"]);\\n    });\\n\\n    it(\\\"should_not_notify_when_the_proposal_has_no_violations\\\", () => {\\n      applyFlowProposalToCanvas(cleanProposal(), \\\"add\\\", asInternals(jest.fn()));\\n\\n      expect(setNoticeData).not.toHaveBeenCalled();\\n      expect(appliedIds().nodeIds).toEqual([\\\"ChatInput-a\\\", \\\"ChatOutput-b\\\"]);\\n    });\\n  });\\n\\n  describe(\\\"replace mode\\\", () => {\\n    it(\\\"should_enforce_the_placement_policy_instead_of_bypassing_it\\\", () => {\\n      applyFlowProposalToCanvas(\\n        twoChatInputProposal(),\\n        \\\"replace\\\",\\n        asInternals(jest.fn()),\\n      );\\n\\n      const { nodeIds, edgeIds } = appliedIds();\\n      expect(nodeIds).toEqual([\\n        \\\"ChatInput-a\\\",\\n        \\\"ConditionalRouter-c\\\",\\n        \\\"ChatOutput-d\\\",\\n        \\\"ChatOutput-e\\\",\\n      ]);\\n      expect(edgeIds).toEqual([\\\"e1\\\", \\\"e3\\\", \\\"e4\\\"]);\\n      expect(setNoticeData).toHaveBeenCalledWith({\\n        title: \\\"assistant.duplicateComponentsNotAdded\\\",\\n      });\\n    });\\n\\n    it(\\\"should_not_mutate_the_stored_proposal_when_filtering\\\", () => {\\n      const proposal = twoChatInputProposal();\\n\\n      applyFlowProposalToCanvas(proposal, \\\"replace\\\", asInternals(jest.fn()));\\n\\n      // The proposal stays re-appliable from the pending card; filtering\\n      // must work on a copy, not gut the stored flow.\\n      const data = proposal.flow.data as { nodes: unknown[]; edges: unknown[] };\\n      expect(data.nodes).toHaveLength(5);\\n      expect(data.edges).toHaveLength(4);\\n    });\\n\\n    it(\\\"should_not_notify_when_the_proposal_has_no_violations\\\", () => {\\n      applyFlowProposalToCanvas(\\n        cleanProposal(),\\n        \\\"replace\\\",\\n        asInternals(jest.fn()),\\n      );\\n\\n      expect(setNoticeData).not.toHaveBeenCalled();\\n      expect(appliedIds().nodeIds).toEqual([\\\"ChatInput-a\\\", \\\"ChatOutput-b\\\"]);\\n    });\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/helpers/__tests__/apply-flow-update.test.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8743430659c30bf313678b5f54bff21fa007f574bf96f08ea06da85e83891b73\",\"content\":\"/**\\n * I6 \u2014 apply-flow-update must validate untrusted SSE payloads before\\n * mutating the live canvas. The event arrives from the assistant SSE\\n * stream (LLM-driven, potentially malformed); a blanket cast lets garbage\\n * land in `useFlowStore`, corrupting the user's canvas with no signal.\\n *\\n * These tests cover the malformed-payload paths the reviewer flagged:\\n * the dispatcher must drop the event (no store mutation) rather than\\n * cast-and-write.\\n */\\n\\nimport type { AgenticFlowUpdateEvent } from \\\"@/controllers/API/queries/agentic\\\";\\nimport { applyFlowUpdate } from \\\"../apply-flow-update\\\";\\n\\ntype UpdateNodeInternalsFn = Parameters<typeof applyFlowUpdate>[1];\\nconst asEvent = (v: unknown): AgenticFlowUpdateEvent =>\\n  v as AgenticFlowUpdateEvent;\\nconst asInternals = (v: unknown): UpdateNodeInternalsFn =>\\n  v as UpdateNodeInternalsFn;\\n\\n// Mock the canvas store BEFORE the helper imports it.\\nconst setNodes = jest.fn();\\nconst setEdges = jest.fn();\\nconst setNodesAndEdges = jest.fn();\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: {\\n    getState: () => ({\\n      setNodes,\\n      setEdges,\\n      setNodesAndEdges,\\n      reactFlowInstance: { fitView: jest.fn() },\\n    }),\\n  },\\n}));\\n\\nconst noopUpdateNodeInternals = jest.fn();\\n\\nbeforeEach(() => {\\n  setNodes.mockClear();\\n  setEdges.mockClear();\\n  setNodesAndEdges.mockClear();\\n  noopUpdateNodeInternals.mockClear();\\n});\\n\\ndescribe(\\\"applyFlowUpdate \u2014 boundary validation\\\", () => {\\n  describe(\\\"set_flow\\\", () => {\\n    it(\\\"should_skip_canvas_replace_when_flow_data_nodes_is_not_an_array\\\", () => {\\n      const malformed = {\\n        event: \\\"flow_update\\\",\\n        action: \\\"set_flow\\\",\\n        // nodes must be an array; the assistant sometimes hallucinates a\\n        // string or an object literal here.\\n        flow: { data: { nodes: \\\"<corrupted>\\\", edges: [] } },\\n      };\\n\\n      applyFlowUpdate(asEvent(malformed), asInternals(noopUpdateNodeInternals));\\n\\n      expect(setNodesAndEdges).not.toHaveBeenCalled();\\n    });\\n\\n    it(\\\"should_apply_canvas_replace_atomically_when_payload_is_well_formed\\\", () => {\\n      // Atomic setNodesAndEdges (one render) \u2014 a split setNodes+setEdges draws\\n      // edges to loop/dynamic handles a frame late, so they need a refresh.\\n      const nodes = [{ id: \\\"ChatInput-1\\\" }];\\n      const edges = [{ id: \\\"e1\\\", source: \\\"ChatInput-1\\\", target: \\\"Loop-2\\\" }];\\n      const valid = {\\n        event: \\\"flow_update\\\",\\n        action: \\\"set_flow\\\",\\n        flow: { data: { nodes, edges } },\\n      };\\n\\n      applyFlowUpdate(asEvent(valid), asInternals(noopUpdateNodeInternals));\\n\\n      expect(setNodesAndEdges).toHaveBeenCalledTimes(1);\\n      expect(setNodesAndEdges).toHaveBeenCalledWith(nodes, edges);\\n      expect(setNodes).not.toHaveBeenCalled();\\n      expect(setEdges).not.toHaveBeenCalled();\\n    });\\n\\n    it(\\\"should_notify_node_internals_for_each_new_node_after_set_flow\\\", () => {\\n      // Bug C: without this, new nodes' handles never register, so edges to\\n      // loop/dynamic handles don't draw until the user refreshes the page.\\n      const rafSpy = jest\\n        .spyOn(global, \\\"requestAnimationFrame\\\")\\n        .mockImplementation((cb: FrameRequestCallback) => {\\n          cb(0);\\n          return 0;\\n        });\\n      const valid = {\\n        event: \\\"flow_update\\\",\\n        action: \\\"set_flow\\\",\\n        flow: {\\n          data: {\\n            nodes: [{ id: \\\"ChatInput-1\\\" }, { id: \\\"Loop-2\\\" }],\\n            edges: [{ id: \\\"e1\\\", source: \\\"ChatInput-1\\\", target: \\\"Loop-2\\\" }],\\n          },\\n        },\\n      };\\n\\n      applyFlowUpdate(asEvent(valid), asInternals(noopUpdateNodeInternals));\\n\\n      expect(noopUpdateNodeInternals).toHaveBeenCalledWith(\\\"ChatInput-1\\\");\\n      expect(noopUpdateNodeInternals).toHaveBeenCalledWith(\\\"Loop-2\\\");\\n      expect(noopUpdateNodeInternals).toHaveBeenCalledTimes(2);\\n      rafSpy.mockRestore();\\n    });\\n  });\\n\\n  describe(\\\"add_component\\\", () => {\\n    it.each([\\n      [\\\"null node\\\", null],\\n      [\\\"string node\\\", \\\"Agent-1\\\"],\\n      [\\\"number node\\\", 42],\\n      [\\\"node missing id\\\", { data: {} }],\\n    ])(\\\"should_skip_add_when_payload_is_%s\\\", (_label, badNode) => {\\n      const malformed = {\\n        event: \\\"flow_update\\\",\\n        action: \\\"add_component\\\",\\n        node: badNode,\\n      };\\n\\n      applyFlowUpdate(asEvent(malformed), asInternals(noopUpdateNodeInternals));\\n\\n      expect(setNodes).not.toHaveBeenCalled();\\n    });\\n\\n    it(\\\"should_apply_add_when_node_is_a_valid_object_with_id\\\", () => {\\n      const valid = {\\n        event: \\\"flow_update\\\",\\n        action: \\\"add_component\\\",\\n        node: { id: \\\"Agent-1\\\", data: {} },\\n      };\\n\\n      applyFlowUpdate(asEvent(valid), asInternals(noopUpdateNodeInternals));\\n\\n      expect(setNodes).toHaveBeenCalledTimes(1);\\n    });\\n  });\\n\\n  describe(\\\"connect\\\", () => {\\n    it(\\\"should_skip_when_edge_lacks_source_or_target\\\", () => {\\n      const malformed = {\\n        event: \\\"flow_update\\\",\\n        action: \\\"connect\\\",\\n        edge: { id: \\\"edge-1\\\", source: \\\"A\\\" }, // target missing\\n      };\\n\\n      applyFlowUpdate(asEvent(malformed), asInternals(noopUpdateNodeInternals));\\n\\n      expect(setEdges).not.toHaveBeenCalled();\\n    });\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/helpers/__tests__/merge-flow-into-canvas.test.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"058cab0663798a514341c6f000c86ad5a45a3ee5c001ef56ec204de8f6804147\",\"content\":\"import { mergeFlowIntoCanvas } from \\\"../merge-flow-into-canvas\\\";\\n\\n/**\\n * FP1 \u2014 Pure helper that merges a proposal flow into existing canvas state.\\n *\\n * The current \\\"Continue\\\" semantic on a flow proposal is destructive: it\\n * replaces nodes/edges via setNodes / setEdges. This helper produces the\\n * additive alternative: it\\n *   1. Reassigns IDs on proposal nodes that collide with canvas IDs.\\n *   2. Rewrites proposal edges so source/target track the new IDs.\\n *   3. Offsets proposal node positions so they don't overlap the\\n *      existing canvas (placed to the right with a gap).\\n *\\n * The function is pure (no React, no @xyflow state) \u2014 easy to unit-test.\\n */\\n\\ntype Node = { id: string; position: { x: number; y: number }; data?: unknown };\\ntype Edge = {\\n  id: string;\\n  source: string;\\n  target: string;\\n  sourceHandle?: string | null;\\n  targetHandle?: string | null;\\n};\\n\\nfunction n(id: string, x = 0, y = 0): Node {\\n  return { id, position: { x, y }, data: { type: id.split(\\\"-\\\")[0] } };\\n}\\n\\nfunction e(id: string, source: string, target: string): Edge {\\n  return { id, source, target };\\n}\\n\\ndescribe(\\\"mergeFlowIntoCanvas\\\", () => {\\n  describe(\\\"empty existing canvas\\\", () => {\\n    it(\\\"should_return_proposal_nodes_unchanged_when_canvas_is_empty\\\", () => {\\n      const proposal = {\\n        nodes: [n(\\\"ChatInput-a\\\", 100, 100), n(\\\"Agent-b\\\", 300, 100)],\\n        edges: [e(\\\"xy\\\", \\\"ChatInput-a\\\", \\\"Agent-b\\\")],\\n      };\\n\\n      const result = mergeFlowIntoCanvas([], [], proposal);\\n\\n      // Empty canvas \u2192 no offset, no ID remap.\\n      expect(result.nodes).toEqual(proposal.nodes);\\n      expect(result.edges).toEqual(proposal.edges);\\n    });\\n  });\\n\\n  describe(\\\"non-empty canvas \u2014 no ID collisions\\\", () => {\\n    it(\\\"should_offset_proposal_nodes_to_the_right_of_existing_canvas\\\", () => {\\n      const existing = [n(\\\"Existing-1\\\", 0, 0), n(\\\"Existing-2\\\", 200, 50)];\\n      const proposal = {\\n        nodes: [n(\\\"New-A\\\", 0, 0), n(\\\"New-B\\\", 200, 0)],\\n        edges: [e(\\\"e1\\\", \\\"New-A\\\", \\\"New-B\\\")],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, [], proposal);\\n\\n      // Existing canvas right edge \u2248 200; proposal min_x = 0.\\n      // Offset = (200 - 0) + GAP \u21d2 proposal nodes shift right by 200+GAP.\\n      const offsetA = result.nodes[2].position.x; // New-A\\n      const offsetB = result.nodes[3].position.x; // New-B\\n      expect(offsetA).toBeGreaterThan(200); // strictly right of existing\\n      // Relative spacing preserved within the proposal.\\n      expect(offsetB - offsetA).toBe(200);\\n    });\\n\\n    it(\\\"should_concatenate_existing_then_proposal_nodes\\\", () => {\\n      const existing = [n(\\\"Existing-1\\\", 0, 0)];\\n      const proposal = {\\n        nodes: [n(\\\"New-A\\\", 0, 0)],\\n        edges: [],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, [], proposal);\\n\\n      expect(result.nodes).toHaveLength(2);\\n      expect(result.nodes[0].id).toBe(\\\"Existing-1\\\");\\n      expect(result.nodes[1].id).toBe(\\\"New-A\\\");\\n    });\\n\\n    it(\\\"should_concatenate_edges_when_no_collision\\\", () => {\\n      const existing = [n(\\\"Existing-1\\\", 0, 0)];\\n      const existingEdges = [e(\\\"ee1\\\", \\\"Existing-1\\\", \\\"Existing-1\\\")];\\n      const proposal = {\\n        nodes: [n(\\\"New-A\\\", 0, 0), n(\\\"New-B\\\", 100, 0)],\\n        edges: [e(\\\"pe1\\\", \\\"New-A\\\", \\\"New-B\\\")],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, existingEdges, proposal);\\n\\n      expect(result.edges).toHaveLength(2);\\n      expect(result.edges[0].id).toBe(\\\"ee1\\\");\\n      // The proposal edge keeps its source/target intact (no collision).\\n      const newEdge = result.edges[1];\\n      expect(newEdge.source).toBe(\\\"New-A\\\");\\n      expect(newEdge.target).toBe(\\\"New-B\\\");\\n    });\\n  });\\n\\n  describe(\\\"ID collisions\\\", () => {\\n    it(\\\"should_reassign_proposal_node_ids_when_they_collide_with_existing\\\", () => {\\n      const existing = [n(\\\"ChatInput-abc\\\", 0, 0)];\\n      const proposal = {\\n        nodes: [n(\\\"ChatInput-abc\\\", 0, 0), n(\\\"Agent-xyz\\\", 200, 0)],\\n        edges: [e(\\\"e1\\\", \\\"ChatInput-abc\\\", \\\"Agent-xyz\\\")],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, [], proposal);\\n\\n      // Existing kept as-is.\\n      expect(result.nodes[0].id).toBe(\\\"ChatInput-abc\\\");\\n      // The colliding proposal node got a new id.\\n      const remappedChatInput = result.nodes[1];\\n      expect(remappedChatInput.id).not.toBe(\\\"ChatInput-abc\\\");\\n      expect(remappedChatInput.id.startsWith(\\\"ChatInput-\\\")).toBe(true);\\n      // The non-colliding one stays.\\n      expect(result.nodes[2].id).toBe(\\\"Agent-xyz\\\");\\n    });\\n\\n    it(\\\"should_rewrite_proposal_edges_to_use_remapped_ids\\\", () => {\\n      const existing = [n(\\\"ChatInput-abc\\\", 0, 0)];\\n      const proposal = {\\n        nodes: [n(\\\"ChatInput-abc\\\", 0, 0), n(\\\"Agent-xyz\\\", 200, 0)],\\n        edges: [e(\\\"e1\\\", \\\"ChatInput-abc\\\", \\\"Agent-xyz\\\")],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, [], proposal);\\n\\n      const remappedChatInputId = result.nodes[1].id;\\n      const proposalEdge = result.edges[result.edges.length - 1];\\n      expect(proposalEdge.source).toBe(remappedChatInputId);\\n      expect(proposalEdge.target).toBe(\\\"Agent-xyz\\\");\\n    });\\n\\n    it(\\\"should_remap_edge_id_when_it_collides_with_existing_edge_id\\\", () => {\\n      const existing = [n(\\\"E1\\\", 0, 0)];\\n      const existingEdges = [e(\\\"shared-edge\\\", \\\"E1\\\", \\\"E1\\\")];\\n      const proposal = {\\n        nodes: [n(\\\"New-A\\\", 0, 0), n(\\\"New-B\\\", 100, 0)],\\n        edges: [e(\\\"shared-edge\\\", \\\"New-A\\\", \\\"New-B\\\")],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, existingEdges, proposal);\\n\\n      expect(result.edges).toHaveLength(2);\\n      const newEdgeId = result.edges[1].id;\\n      expect(newEdgeId).not.toBe(\\\"shared-edge\\\");\\n    });\\n\\n    it(\\\"should_remap_multiple_colliding_nodes_with_unique_ids_each\\\", () => {\\n      const existing = [n(\\\"ChatInput-x\\\", 0, 0), n(\\\"Agent-x\\\", 100, 0)];\\n      const proposal = {\\n        nodes: [\\n          n(\\\"ChatInput-x\\\", 0, 0),\\n          n(\\\"Agent-x\\\", 100, 0),\\n          n(\\\"ChatOutput-z\\\", 200, 0),\\n        ],\\n        edges: [\\n          e(\\\"e1\\\", \\\"ChatInput-x\\\", \\\"Agent-x\\\"),\\n          e(\\\"e2\\\", \\\"Agent-x\\\", \\\"ChatOutput-z\\\"),\\n        ],\\n      };\\n\\n      const result = mergeFlowIntoCanvas(existing, [], proposal);\\n\\n      const newIds = result.nodes.slice(2).map((nn) => nn.id);\\n      // No id from the proposal subset collides with the existing canvas.\\n      const existingIds = new Set([\\\"ChatInput-x\\\", \\\"Agent-x\\\"]);\\n      newIds.forEach((id) => expect(existingIds.has(id)).toBe(false));\\n      // And the proposal's internal references hold up.\\n      const proposalEdges = result.edges.slice(0); // all edges; existing had none\\n      const remappedChatInput = newIds[0];\\n      const remappedAgent = newIds[1];\\n      const chatOutput = newIds[2];\\n      expect(proposalEdges[0].source).toBe(remappedChatInput);\\n      expect(proposalEdges[0].target).toBe(remappedAgent);\\n      expect(proposalEdges[1].source).toBe(remappedAgent);\\n      expect(proposalEdges[1].target).toBe(chatOutput);\\n    });\\n  });\\n\\n  describe(\\\"idempotency / determinism\\\", () => {\\n    it(\\\"should_produce_unique_ids_across_two_consecutive_merges\\\", () => {\\n      // Two clicks of \\\"Add to canvas\\\" with the SAME proposal must not\\n      // produce id collisions on the second click.\\n      const proposal = {\\n        nodes: [n(\\\"ChatInput-a\\\", 0, 0), n(\\\"Agent-b\\\", 100, 0)],\\n        edges: [e(\\\"e1\\\", \\\"ChatInput-a\\\", \\\"Agent-b\\\")],\\n      };\\n\\n      const first = mergeFlowIntoCanvas([], [], proposal);\\n      const second = mergeFlowIntoCanvas(first.nodes, first.edges, proposal);\\n\\n      const allIds = [\\n        ...first.nodes.map((nn) => nn.id),\\n        ...second.nodes.slice(first.nodes.length).map((nn) => nn.id),\\n      ];\\n      expect(new Set(allIds).size).toBe(allIds.length);\\n    });\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/helpers/apply-flow-proposal.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ec37d7a8af958d5b0257a9c41e9c108cabf476f480f8921bea436212d82d96f\",\"content\":\"/**\\n * Apply a gated flow proposal onto the live canvas \u2014 the shared body behind the\\n * \\\"Add to canvas\\\" (merge) and \\\"Replace canvas\\\" (overwrite) actions. Extracted\\n * from the chat hook to keep it within the file-size budget and to isolate the\\n * canvas-mutation concern from the message/state bookkeeping.\\n */\\n\\nimport type { useUpdateNodeInternals } from \\\"@xyflow/react\\\";\\nimport i18n from \\\"@/i18n\\\";\\nimport useAlertStore from \\\"@/stores/alertStore\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport {\\n  type ConstraintViolation,\\n  filterPlaceableSelection,\\n} from \\\"@/utils/componentConstraints\\\";\\nimport type { PendingFlowProposal } from \\\"../assistant-panel.types\\\";\\nimport { applyFlowUpdate, notifyNodesUntilMounted } from \\\"./apply-flow-update\\\";\\nimport { mergeFlowIntoCanvas } from \\\"./merge-flow-into-canvas\\\";\\n\\ntype UpdateNodeInternals = ReturnType<typeof useUpdateNodeInternals>;\\n\\ninterface PositionedNode {\\n  id: string;\\n  position: { x: number; y: number };\\n}\\ninterface SimpleEdge {\\n  id: string;\\n  source: string;\\n  target: string;\\n}\\n\\n/**\\n * The proposal card advertises the full node/edge counts, so a policy drop\\n * must be surfaced \u2014 a silent drop leaves the canvas diverging from what the\\n * user accepted (and can strand required inputs whose edge was pruned).\\n */\\nfunction notifyPlacementViolations(violations: ConstraintViolation[]): void {\\n  if (violations.length === 0) return;\\n  const messages: string[] = [];\\n  if (violations.some((v) => v.reason === \\\"singleton\\\")) {\\n    messages.push(i18n.t(\\\"assistant.duplicateComponentsNotAdded\\\"));\\n  }\\n  if (violations.some((v) => v.reason === \\\"exclusivity\\\")) {\\n    messages.push(i18n.t(\\\"assistant.exclusiveComponentsNotAdded\\\"));\\n  }\\n  useAlertStore.getState().setNoticeData({ title: messages.join(\\\" \\\") });\\n}\\n\\nexport function applyFlowProposalToCanvas(\\n  proposal: PendingFlowProposal,\\n  mode: \\\"replace\\\" | \\\"add\\\",\\n  updateNodeInternals: UpdateNodeInternals,\\n): void {\\n  if (mode === \\\"add\\\") {\\n    // Additive merge: ids remapped on collision, edges rewritten, positions\\n    // offset right of the existing bounding box (no overlap).\\n    const store = useFlowStore.getState();\\n    const flow = proposal.flow as {\\n      data?: { nodes?: unknown[]; edges?: unknown[] };\\n    };\\n    const proposalNodes = (flow.data?.nodes as PositionedNode[]) ?? [];\\n    const proposalEdges = (flow.data?.edges as SimpleEdge[]) ?? [];\\n    const existingIds = new Set(\\n      (store.nodes as PositionedNode[]).map((n) => n.id),\\n    );\\n    // Writes the store directly (not via `paste`), so re-enforce placement policy.\\n    const placeable = filterPlaceableSelection(\\n      { nodes: proposalNodes as never[], edges: proposalEdges as never[] },\\n      store.nodes as Array<{ data?: { type?: string } }>,\\n    );\\n    notifyPlacementViolations(placeable.violations);\\n    const merged = mergeFlowIntoCanvas(\\n      store.nodes as PositionedNode[],\\n      store.edges as SimpleEdge[],\\n      { nodes: placeable.nodes, edges: placeable.edges },\\n    );\\n    // Atomic nodes+edges in one render so edges to loop/dynamic handles draw\\n    // without a refresh (a split setNodes+setEdges draws them a frame late).\\n    store.setNodesAndEdges(merged.nodes as never[], merged.edges as never[]);\\n    const addedIds = merged.nodes\\n      .map((n) => n.id)\\n      .filter((id) => !existingIds.has(id));\\n    notifyNodesUntilMounted(addedIds, updateNodeInternals);\\n  } else {\\n    // Replace targets an empty canvas, but the proposal can conflict with\\n    // itself (e.g. two ChatInputs); filter a copy so re-apply stays intact.\\n    const flow = proposal.flow as {\\n      data?: { nodes?: unknown[]; edges?: unknown[] };\\n    };\\n    const placeable = filterPlaceableSelection(\\n      {\\n        nodes: (flow.data?.nodes ?? []) as never[],\\n        edges: (flow.data?.edges ?? []) as never[],\\n      },\\n      [],\\n    );\\n    notifyPlacementViolations(placeable.violations);\\n    applyFlowUpdate(\\n      {\\n        event: \\\"flow_update\\\",\\n        action: \\\"set_flow\\\",\\n        flow: {\\n          ...proposal.flow,\\n          data: {\\n            ...flow.data,\\n            nodes: placeable.nodes,\\n            edges: placeable.edges,\\n          },\\n        },\\n      },\\n      updateNodeInternals,\\n    );\\n  }\\n  for (const tail of proposal.tailUpdates ?? []) {\\n    applyFlowUpdate(tail, updateNodeInternals);\\n  }\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/helpers/apply-flow-update.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"46882fde4ec6d22e22f20ae9a37ae3d47ae691460ebf2cdcb0a7cc1cf232b54c\",\"content\":\"/**\\n * Maps a single SSE `flow_update` event onto the live canvas. Reads/writes\\n * `useFlowStore.getState()` directly (bypassing React subscription) so a rapid\\n * event drain grabs the freshest state per call. `updateNodeInternals` is\\n * passed in because it is a hook return value.\\n */\\n\\nimport type { useUpdateNodeInternals } from \\\"@xyflow/react\\\";\\nimport type { AgenticFlowUpdateEvent } from \\\"@/controllers/API/queries/agentic\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\n\\ntype UpdateNodeInternals = ReturnType<typeof useUpdateNodeInternals>;\\n\\n// SSE flow_update payloads are LLM-driven (untrusted); validate before any\\n// store mutation so a malformed event can't silently corrupt the canvas.\\nconst isPlainObject = (v: unknown): v is Record<string, unknown> =>\\n  typeof v === \\\"object\\\" && v !== null && !Array.isArray(v);\\nconst isNonEmptyString = (v: unknown): v is string =>\\n  typeof v === \\\"string\\\" && v.length > 0;\\nconst isNodeShape = (v: unknown): v is Record<string, unknown> =>\\n  isPlainObject(v) && isNonEmptyString((v as Record<string, unknown>).id);\\n\\nconst warnDrop = (action: string, reason: string): void => {\\n  console.warn(`[applyFlowUpdate] dropped ${action}: ${reason}`);\\n};\\n\\n/**\\n * Notify each new node once mounted so their handles register. Kept minimal \u2014\\n * the loop-edge redraw is handled by applying nodes+edges atomically (see the\\n * `set_flow` case); this just nudges React Flow for dynamic handles.\\n */\\nexport function notifyNodesUntilMounted(\\n  nodeIds: string[],\\n  updateNodeInternals: UpdateNodeInternals,\\n  onFinalPass?: () => void,\\n): void {\\n  requestAnimationFrame(() => {\\n    requestAnimationFrame(() => {\\n      for (const id of nodeIds) updateNodeInternals(id);\\n      onFinalPass?.();\\n    });\\n  });\\n}\\n\\nexport function applyFlowUpdate(\\n  event: AgenticFlowUpdateEvent,\\n  updateNodeInternals: UpdateNodeInternals,\\n): void {\\n  switch (event.action) {\\n    case \\\"set_flow\\\": {\\n      const flow = event.flow as {\\n        data?: { nodes?: unknown[]; edges?: unknown[] };\\n      };\\n      const nodes = flow?.data?.nodes;\\n      const edges = flow?.data?.edges;\\n      if (!Array.isArray(nodes)) {\\n        warnDrop(\\\"set_flow\\\", \\\"flow.data.nodes is not an array\\\");\\n        break;\\n      }\\n      if (edges !== undefined && !Array.isArray(edges)) {\\n        warnDrop(\\\"set_flow\\\", \\\"flow.data.edges is not an array\\\");\\n        break;\\n      }\\n      {\\n        // Atomic nodes+edges in one render so React Flow resolves edges to\\n        // loop/dynamic handles immediately (a split set draws them only on refresh).\\n        useFlowStore\\n          .getState()\\n          .setNodesAndEdges(nodes as never[], (edges ?? []) as never[]);\\n        const newNodeIds = nodes\\n          .map((n) => (isPlainObject(n) ? n.id : undefined))\\n          .filter(isNonEmptyString);\\n        notifyNodesUntilMounted(newNodeIds, updateNodeInternals, () =>\\n          useFlowStore.getState().reactFlowInstance?.fitView({\\n            padding: { left: \\\"20px\\\", right: \\\"20px\\\", top: \\\"80px\\\" },\\n            minZoom: 0.25,\\n            maxZoom: 2,\\n            duration: 250,\\n          }),\\n        );\\n      }\\n      break;\\n    }\\n    case \\\"add_component\\\": {\\n      const node = event.node;\\n      if (!isNodeShape(node)) {\\n        warnDrop(\\\"add_component\\\", \\\"node is not an object with a string id\\\");\\n        break;\\n      }\\n      const setNodes = useFlowStore.getState().setNodes;\\n      setNodes((prev) => [...prev, node as never]);\\n      break;\\n    }\\n    case \\\"connect\\\": {\\n      const edge = event.edge;\\n      if (!isPlainObject(edge)) {\\n        warnDrop(\\\"connect\\\", \\\"edge is not an object\\\");\\n        break;\\n      }\\n      const src = edge.source;\\n      const tgt = edge.target;\\n      if (!isNonEmptyString(src) || !isNonEmptyString(tgt)) {\\n        warnDrop(\\\"connect\\\", \\\"edge.source/target missing or not strings\\\");\\n        break;\\n      }\\n      const setEdges = useFlowStore.getState().setEdges;\\n      setEdges((prev) => [...prev, edge as never]);\\n      // Refresh both endpoints so ReactFlow reconciles handle positions.\\n      updateNodeInternals(src);\\n      updateNodeInternals(tgt);\\n      break;\\n    }\\n    case \\\"remove_component\\\": {\\n      const nodeId = event.component_id as string;\\n      if (nodeId) {\\n        const setNodes = useFlowStore.getState().setNodes;\\n        const setEdges = useFlowStore.getState().setEdges;\\n        setNodes((prev) =>\\n          prev.filter((n) => (n as Record<string, unknown>).id !== nodeId),\\n        );\\n        setEdges((prev) =>\\n          prev.filter((e) => {\\n            const edge = e as Record<string, unknown>;\\n            return edge.source !== nodeId && edge.target !== nodeId;\\n          }),\\n        );\\n      }\\n      break;\\n    }\\n    case \\\"configure\\\": {\\n      const compId = event.component_id as string;\\n      const params = event.params as Record<string, unknown>;\\n      if (compId && params) {\\n        const setNodes = useFlowStore.getState().setNodes;\\n        setNodes((prev) =>\\n          prev.map((n) => {\\n            const node = n as Record<string, unknown>;\\n            if (node.id !== compId) return n;\\n            const data = node.data as Record<string, unknown>;\\n            const innerNode = (data?.node ?? {}) as Record<string, unknown>;\\n            const tpl = (innerNode?.template ?? {}) as Record<string, unknown>;\\n            return {\\n              ...node,\\n              data: {\\n                ...data,\\n                node: {\\n                  ...innerNode,\\n                  template: {\\n                    ...tpl,\\n                    ...Object.fromEntries(\\n                      Object.entries(params).map(([k, v]) => [\\n                        k,\\n                        {\\n                          ...(tpl[k] as Record<string, unknown>),\\n                          value: v,\\n                        },\\n                      ]),\\n                    ),\\n                  },\\n                },\\n              },\\n            } as never;\\n          }),\\n        );\\n      }\\n      break;\\n    }\\n    case \\\"select_output\\\": {\\n      // `data.selected_output` (top-level, not inside data.node) switches which\\n      // output handle renders; notify so the moved handle is reconciled.\\n      const compId = event.component_id as string;\\n      const outputName = event.output_name as string;\\n      if (compId && outputName) {\\n        const setNodes = useFlowStore.getState().setNodes;\\n        setNodes((prev) =>\\n          prev.map((n) => {\\n            const node = n as Record<string, unknown>;\\n            if (node.id !== compId) return n;\\n            const data = (node.data ?? {}) as Record<string, unknown>;\\n            return {\\n              ...node,\\n              data: {\\n                ...data,\\n                selected_output: outputName,\\n              },\\n            } as never;\\n          }),\\n        );\\n        updateNodeInternals(compId);\\n      }\\n      break;\\n    }\\n    case \\\"set_connection_mode\\\": {\\n      // `data._connectionMode` flips ModelInput to a left handle for an external\\n      // model edge; notify so the new handle position is reconciled.\\n      const compId = event.component_id as string;\\n      const enabled = event.enabled as boolean;\\n      if (compId !== undefined) {\\n        const setNodes = useFlowStore.getState().setNodes;\\n        setNodes((prev) =>\\n          prev.map((n) => {\\n            const node = n as Record<string, unknown>;\\n            if (node.id !== compId) return n;\\n            const data = (node.data ?? {}) as Record<string, unknown>;\\n            return {\\n              ...node,\\n              data: {\\n                ...data,\\n                _connectionMode: enabled,\\n              },\\n            } as never;\\n          }),\\n        );\\n        updateNodeInternals(compId);\\n      }\\n      break;\\n    }\\n    case \\\"enable_tool_mode\\\": {\\n      // Mirror the backend Tool Mode flip (outputs collapse to one Toolset\\n      // handle) BEFORE the connect edge, else its source handle has no match.\\n      const compId = event.component_id as string;\\n      const outputs = event.outputs;\\n      if (compId && Array.isArray(outputs)) {\\n        const setNodes = useFlowStore.getState().setNodes;\\n        setNodes((prev) =>\\n          prev.map((n) => {\\n            const node = n as Record<string, unknown>;\\n            if (node.id !== compId) return n;\\n            const data = (node.data ?? {}) as Record<string, unknown>;\\n            const innerNode = (data?.node ?? {}) as Record<string, unknown>;\\n            return {\\n              ...node,\\n              data: {\\n                ...data,\\n                node: {\\n                  ...innerNode,\\n                  tool_mode: true,\\n                  outputs,\\n                },\\n              },\\n            } as never;\\n          }),\\n        );\\n        updateNodeInternals(compId);\\n      }\\n      break;\\n    }\\n    default:\\n      break;\\n  }\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/assistantPanel/helpers/merge-flow-into-canvas.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a24c0780da8550092e8f426d48698030f9d7d0f8cd0b486dabe9da2606a60df8\",\"content\":\"/**\\n * Merge a flow proposal into the existing canvas state additively.\\n *\\n * The default \\\"Continue on flow proposal\\\" semantic is destructive: it\\n * calls `setNodes(proposal.nodes) + setEdges(proposal.edges)`, replacing\\n * everything on the canvas. That's correct when the user explicitly\\n * wants to build from scratch on an empty canvas, but hostile when the\\n * canvas already has work the user values.\\n *\\n * This helper produces the additive alternative:\\n *\\n *   1. Detect ID collisions between proposal nodes and existing nodes;\\n *      rename the proposal-side colliders by appending a fresh suffix.\\n *      The component-type prefix (e.g. ``ChatInput-``) is preserved so\\n *      the renamed id still parses by downstream code that splits on\\n *      ``-`` to identify component types.\\n *   2. Rewrite proposal edges so their ``source`` and ``target`` track\\n *      the remapped node ids. Edge ids that collide with existing\\n *      canvas edges are also re-suffixed.\\n *   3. Offset proposal node positions so they don't overlap the\\n *      existing canvas \u2014 placed to the RIGHT of the existing bounding\\n *      box with a fixed gap. Relative spacing inside the proposal is\\n *      preserved.\\n *\\n * The function is pure (no React, no @xyflow state) \u2014 suitable for unit\\n * tests and predictable use from any caller.\\n */\\n\\nconst POSITION_GAP_PX = 80;\\nconst ID_SUFFIX_ENTROPY = 6; // ~36^6 \u2248 2 billion combinations; collision-resistant for any realistic canvas\\n\\ninterface CanvasNode {\\n  id: string;\\n  position: { x: number; y: number };\\n  [key: string]: unknown;\\n}\\n\\ninterface CanvasEdge {\\n  id: string;\\n  source: string;\\n  target: string;\\n  [key: string]: unknown;\\n}\\n\\ninterface FlowProposal {\\n  nodes: CanvasNode[];\\n  edges: CanvasEdge[];\\n}\\n\\nexport interface MergeResult {\\n  nodes: CanvasNode[];\\n  edges: CanvasEdge[];\\n}\\n\\nexport function mergeFlowIntoCanvas(\\n  existingNodes: CanvasNode[],\\n  existingEdges: CanvasEdge[],\\n  proposal: FlowProposal,\\n): MergeResult {\\n  // Empty canvas \u2192 return the proposal as-is; no offset, no remap.\\n  if (existingNodes.length === 0) {\\n    return {\\n      nodes: proposal.nodes,\\n      edges: proposal.edges,\\n    };\\n  }\\n\\n  // 1. ID remap pass \u2014 build a map old\u2192new for any colliding node id.\\n  const existingNodeIds = new Set(existingNodes.map((n) => n.id));\\n  const existingEdgeIds = new Set(existingEdges.map((e) => e.id));\\n  const nodeIdRemap = new Map<string, string>();\\n  for (const node of proposal.nodes) {\\n    if (existingNodeIds.has(node.id)) {\\n      nodeIdRemap.set(node.id, _generateUniqueNodeId(node.id, existingNodeIds));\\n    }\\n  }\\n\\n  // 2. Bounding-box offset \u2014 push the proposal to the right of the canvas.\\n  const offset = _computeRightOffset(existingNodes, proposal.nodes);\\n\\n  // 3. Rewrite proposal nodes \u2014 apply remap and offset.\\n  const newNodes: CanvasNode[] = proposal.nodes.map((node) => ({\\n    ...node,\\n    id: nodeIdRemap.get(node.id) ?? node.id,\\n    position: {\\n      x: node.position.x + offset.dx,\\n      y: node.position.y + offset.dy,\\n    },\\n  }));\\n\\n  // 4. Rewrite proposal edges \u2014 apply both the node-id remap and the\\n  //    edge-id remap (when the edge id itself collides).\\n  const newEdges: CanvasEdge[] = proposal.edges.map((edge) => ({\\n    ...edge,\\n    id: existingEdgeIds.has(edge.id)\\n      ? _generateUniqueEdgeId(edge.id, existingEdgeIds)\\n      : edge.id,\\n    source: nodeIdRemap.get(edge.source) ?? edge.source,\\n    target: nodeIdRemap.get(edge.target) ?? edge.target,\\n  }));\\n\\n  return {\\n    nodes: [...existingNodes, ...newNodes],\\n    edges: [...existingEdges, ...newEdges],\\n  };\\n}\\n\\n// ---------------------------------------------------------------------------\\n// internals\\n// ---------------------------------------------------------------------------\\n\\nfunction _generateUniqueNodeId(\\n  collidingId: string,\\n  taken: Set<string>,\\n): string {\\n  // Component type lives before the first '-'. Preserve it so downstream\\n  // code that splits on '-' to read the type keeps working.\\n  const dashAt = collidingId.indexOf(\\\"-\\\");\\n  const prefix = dashAt === -1 ? collidingId : collidingId.slice(0, dashAt);\\n  let candidate = \\\"\\\";\\n  do {\\n    candidate = `${prefix}-${_randomSuffix()}`;\\n  } while (taken.has(candidate));\\n  taken.add(candidate);\\n  return candidate;\\n}\\n\\nfunction _generateUniqueEdgeId(\\n  collidingId: string,\\n  taken: Set<string>,\\n): string {\\n  let candidate = \\\"\\\";\\n  do {\\n    candidate = `${collidingId}-${_randomSuffix()}`;\\n  } while (taken.has(candidate));\\n  taken.add(candidate);\\n  return candidate;\\n}\\n\\nfunction _randomSuffix(): string {\\n  // Base-36 random suffix. Deterministic-shape, collision-resistant at\\n  // the scales we care about (< 10k nodes per canvas).\\n  let s = \\\"\\\";\\n  for (let i = 0; i < ID_SUFFIX_ENTROPY; i++) {\\n    s += Math.floor(Math.random() * 36).toString(36);\\n  }\\n  return s;\\n}\\n\\nfunction _computeRightOffset(\\n  existing: CanvasNode[],\\n  proposal: CanvasNode[],\\n): { dx: number; dy: number } {\\n  if (proposal.length === 0) return { dx: 0, dy: 0 };\\n\\n  const existingRightEdge = Math.max(...existing.map((n) => n.position.x));\\n  const proposalLeftEdge = Math.min(...proposal.map((n) => n.position.x));\\n\\n  // Place the proposal's leftmost node at existing_right_edge + GAP.\\n  // Negative deltas (proposal already to the right) collapse to GAP to\\n  // keep behavior predictable.\\n  const dx = existingRightEdge - proposalLeftEdge + POSITION_GAP_PX;\\n\\n  // Vertical: keep the proposal's relative y intact \u2014 the user can\\n  // re-arrange. A perfect top-alignment would require careful bbox math\\n  // for node sizes we don't have access to here.\\n  return { dx, dy: 0 };\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/CanvasControlButton.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"213ae47fb80c851dded57f49d43059aa78c199f3faee413dfe32353170d3964c\",\"content\":\"import { ControlButton } from \\\"@xyflow/react\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport ShadTooltip from \\\"@/components/common/shadTooltipComponent\\\";\\nimport { cn } from \\\"@/utils/utils\\\";\\n\\ntype CanvasControlButtonProps = {\\n  iconName: string;\\n  tooltipText: string;\\n  onClick: () => void;\\n  disabled?: boolean;\\n  backgroundClasses?: string;\\n  iconClasses?: string;\\n  testId?: string;\\n  navItemId?: string;\\n};\\n\\nexport const CanvasControlButton = ({\\n  iconName,\\n  tooltipText,\\n  onClick,\\n  disabled,\\n  backgroundClasses,\\n  iconClasses,\\n  testId,\\n  navItemId,\\n}: CanvasControlButtonProps): JSX.Element => {\\n  return (\\n    <ShadTooltip content={tooltipText} side=\\\"right\\\" ariaDescribedBy={undefined}>\\n      <ControlButton\\n        data-testid={testId}\\n        data-sidebar-collapsed-nav-item={navItemId}\\n        className=\\\"group !h-8 !w-8 rounded !p-0 focus-visible:!outline focus-visible:!outline-2 focus-visible:!outline-offset-2 focus-visible:!outline-current\\\"\\n        onClick={onClick}\\n        disabled={disabled}\\n        aria-label={tooltipText}\\n      >\\n        <div\\n          className={cn(\\n            \\\"rounded p-2.5 text-muted-foreground group-hover:text-primary\\\",\\n            backgroundClasses,\\n          )}\\n        >\\n          <ForwardedIconComponent\\n            name={iconName}\\n            aria-hidden=\\\"true\\\"\\n            className={cn(\\\"scale-150 h-8 w-8\\\", iconClasses)}\\n          />\\n        </div>\\n      </ControlButton>\\n    </ShadTooltip>\\n  );\\n};\\n\\nexport default CanvasControlButton;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/CanvasControls.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5649f14bf975709496f0b6bcbd37dd965b9d51e8e60985b04f4c4f910b604be3\",\"content\":\"import * as PopoverPrimitive from \\\"@radix-ui/react-popover\\\";\\nimport { Panel, useStoreApi } from \\\"@xyflow/react\\\";\\nimport { ArrowRight, X } from \\\"lucide-react\\\";\\nimport { type ReactNode, useCallback, useEffect, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport { useShallow } from \\\"zustand/react/shallow\\\";\\nimport langflowAssistantIcon from \\\"@/assets/langflow_assistant.svg\\\";\\nimport langflowAssistantIdleIcon from \\\"@/assets/langflow_assistant_idle.svg\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport {\\n  readAssistantDiscovered,\\n  writeAssistantDiscovered,\\n} from \\\"@/components/core/assistantPanel/hooks/assistant-discovery-storage\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport useAssistantManagerStore from \\\"@/stores/assistantManagerStore\\\";\\nimport useFlowBuilderWelcomeStore from \\\"@/stores/flowBuilderWelcomeStore\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport { usePlaygroundStore } from \\\"@/stores/playgroundStore\\\";\\nimport type { AllNodeType } from \\\"@/types/flow\\\";\\nimport CanvasControlsDropdown from \\\"./CanvasControlsDropdown\\\";\\nimport HelpDropdown from \\\"./HelpDropdown\\\";\\nimport useMinimizeAllAndAlign from \\\"./hooks/use-minimize-all-and-align\\\";\\nimport { useDismissOnTabBoundary } from \\\"./utils/use-dismiss-on-tab-boundary\\\";\\n\\n// Delay before the \\\"Try the new Langflow Assistant!\\\" tooltip surfaces, in ms.\\n// Long enough that an active user mid-task isn't interrupted; short enough\\n// that a user who landed on the canvas and paused gets the hint.\\nconst ONBOARDING_TOOLTIP_DELAY_MS = 10_000;\\n\\nconst CanvasControls = ({\\n  children,\\n  selectedNode,\\n  effectiveLocked,\\n}: {\\n  children?: ReactNode;\\n  selectedNode: AllNodeType | null;\\n  effectiveLocked?: boolean;\\n}) => {\\n  const { t } = useTranslation();\\n  const reactFlowStoreApi = useStoreApi();\\n  const { allMinimized, hasGenericNodes, toggleMinimizeAllAndAlign } =\\n    useMinimizeAllAndAlign();\\n  const isFlowLocked = useFlowStore(\\n    useShallow((state) => state.currentFlow?.locked),\\n  );\\n  const locked = Boolean(effectiveLocked ?? isFlowLocked);\\n  const setAssistantSidebarOpen = useAssistantManagerStore(\\n    (state) => state.setAssistantSidebarOpen,\\n  );\\n  const assistantSidebarOpen = useAssistantManagerStore(\\n    (state) => state.assistantSidebarOpen,\\n  );\\n  // While the FlowBuilderWelcome overlay is open, suppress the onboarding\\n  // tooltip \u2014 it renders via Portal and would float over the welcome.\\n  const isWelcomeOpen = useFlowBuilderWelcomeStore((state) => state.isOpen);\\n  // Same reason as the welcome suppression: the playground sliding container\\n  // renders above the canvas, but the tooltip's Portal escapes that stacking\\n  // context and would float on top of the playground.\\n  const isPlaygroundOpen = usePlaygroundStore((state) => state.isOpen);\\n\\n  // Discovery state \u2014 once true, the \\\"New\\\" pill + onboarding tooltip never\\n  // surface again on this browser. Two paths flip it: opening the assistant\\n  // and clicking X on the tooltip. Both prove the user noticed the feature.\\n  const [discovered, setDiscovered] = useState<boolean>(() =>\\n    readAssistantDiscovered(),\\n  );\\n  // Tooltip surfaces only AFTER the idle delay below \u2014 gives the canvas time\\n  // to settle and avoids being the first thing the user sees on cold mount.\\n  const [tooltipVisible, setTooltipVisible] = useState(false);\\n\\n  useEffect(() => {\\n    if (discovered) return;\\n    const timer = window.setTimeout(() => {\\n      setTooltipVisible(true);\\n    }, ONBOARDING_TOOLTIP_DELAY_MS);\\n    return () => window.clearTimeout(timer);\\n  }, [discovered]);\\n\\n  const markDiscovered = useCallback(() => {\\n    setDiscovered(true);\\n    setTooltipVisible(false);\\n    writeAssistantDiscovered();\\n  }, []);\\n\\n  const handleAssistantClick = () => {\\n    if (locked) return;\\n    if (!discovered) markDiscovered();\\n    setAssistantSidebarOpen(!assistantSidebarOpen);\\n  };\\n\\n  const handleDismissTooltip = useCallback(\\n    (e: React.MouseEvent) => {\\n      // The dismiss X lives inside the button container; stop the click from\\n      // bubbling to ``handleAssistantClick`` which would open the panel.\\n      e.stopPropagation();\\n      markDiscovered();\\n    },\\n    [markDiscovered],\\n  );\\n  const {\\n    containerRef: onboardingTooltipRef,\\n    handleTabBoundary: handleOnboardingTooltipTabBoundary,\\n  } = useDismissOnTabBoundary<HTMLDivElement>(markDiscovered);\\n\\n  const [isAddNoteActive, setIsAddNoteActive] = useState(false);\\n\\n  const handleAddNote = useCallback(() => {\\n    if (locked) return;\\n    window.dispatchEvent(new Event(\\\"lf:start-add-note\\\"));\\n    setIsAddNoteActive(true);\\n  }, [locked]);\\n\\n  useEffect(() => {\\n    const onEnd = () => setIsAddNoteActive(false);\\n    window.addEventListener(\\\"lf:end-add-note\\\", onEnd);\\n    return () => window.removeEventListener(\\\"lf:end-add-note\\\", onEnd);\\n  }, []);\\n\\n  // Single source of truth for the onboarding moment \u2014 both the popover\\n  // tooltip and the \\\"New\\\" pill key off this so they appear together.\\n  const onboardingActive =\\n    !discovered &&\\n    !assistantSidebarOpen &&\\n    !isWelcomeOpen &&\\n    !isPlaygroundOpen &&\\n    !locked &&\\n    tooltipVisible;\\n\\n  useEffect(() => {\\n    reactFlowStoreApi.setState({\\n      nodesDraggable: !locked,\\n      nodesConnectable: !locked,\\n      elementsSelectable: !locked,\\n    });\\n  }, [locked, reactFlowStoreApi]);\\n\\n  return (\\n    <>\\n      <Panel\\n        data-testid=\\\"main_canvas_controls\\\"\\n        className=\\\"react-flow__controls flex !flex-row items-center gap-1 !overflow-visible rounded-lg bg-background p-1 fill-foreground stroke-foreground text-primary [&>button]:border-0\\\"\\n        position=\\\"bottom-center\\\"\\n      >\\n        {/* Wrap the assistant button + \\\"New\\\" pill in a Radix Popover so the\\n            onboarding tooltip can render in a Portal on ``document.body``.\\n            Without the portal the tooltip is absolutely positioned inside the\\n            ReactFlow Panel and gets clipped or stacked under the workspace\\n            sidebar (z-index races, overflow contexts). The portal lifts it\\n            above every sibling surface. */}\\n        <PopoverPrimitive.Root open={onboardingActive} modal={false}>\\n          <PopoverPrimitive.Anchor asChild>\\n            <div className=\\\"group relative\\\">\\n              {/* \\\"New\\\" discovery pill \u2014 surfaces ONLY on hover, hidden when\\n                  the panel is open (active state shouldn't carry the nudge)\\n                  and gone for good once the user has opened the assistant\\n                  (persisted ``discovered`` flag) \u2014 a feature the user already\\n                  found isn't \\\"new\\\" to them anymore.\\n                  Uses the brand token from index.css. */}\\n              {!assistantSidebarOpen && !discovered && !locked && (\\n                <span\\n                  data-testid=\\\"assistant-button-new-pill\\\"\\n                  // Visibility logic: stays in lock-step with the onboarding\\n                  // tooltip \u2014 when ``onboardingActive`` is true the pill is\\n                  // pinned open; otherwise it falls back to the hover-only\\n                  // behavior so power users still see it as a hint without\\n                  // it being intrusive.\\n                  className={`absolute -top-4 -left-1 z-10 flex items-center gap-0.5 rounded bg-accent-assistant-brand px-1 py-0.5 text-[9px] font-medium leading-none text-white transition-opacity duration-200 ${\\n                    onboardingActive\\n                      ? \\\"opacity-100\\\"\\n                      : \\\"opacity-0 group-hover:opacity-100\\\"\\n                  }`}\\n                >\\n                  <ForwardedIconComponent\\n                    name=\\\"Sparkles\\\"\\n                    className=\\\"h-2.5 w-2.5\\\"\\n                  />\\n                  {t(\\\"assistant.newPill\\\")}\\n                </span>\\n              )}\\n              <Button\\n                unstyled\\n                size=\\\"icon\\\"\\n                data-testid=\\\"assistant-button\\\"\\n                className=\\\"group/btn relative flex h-8 w-8 items-center justify-center overflow-hidden rounded-md hover:bg-muted disabled:cursor-not-allowed disabled:opacity-50\\\"\\n                onClick={handleAssistantClick}\\n                disabled={locked}\\n                title={locked ? t(\\\"version.readOnly\\\") : undefined}\\n                aria-label={t(\\\"assistant.title\\\")}\\n              >\\n                {/* Idle state \u2014 uses the design-tuned\\n                    ``langflow_assistant_idle.svg`` (noise filter + brand tint\\n                    baked into the SVG). Hidden whenever the panel is open so\\n                    the button reads as \\\"active\\\" alongside the open panel. */}\\n                <img\\n                  src={langflowAssistantIdleIcon}\\n                  alt=\\\"Langflow Assistant\\\"\\n                  className={`absolute inset-0 h-full w-full object-cover transition-opacity duration-150 ${\\n                    assistantSidebarOpen ? \\\"opacity-0\\\" : \\\"group-hover:opacity-0\\\"\\n                  }`}\\n                />\\n                {/* Brand-lit icon \u2014 surfaces on hover AND while the panel is\\n                    open; both states share the same active brand identity. */}\\n                <img\\n                  src={langflowAssistantIcon}\\n                  alt=\\\"\\\"\\n                  aria-hidden=\\\"true\\\"\\n                  className={`absolute inset-0 h-full w-full object-cover transition-opacity duration-150 ${\\n                    assistantSidebarOpen\\n                      ? \\\"opacity-100\\\"\\n                      : \\\"opacity-0 group-hover:opacity-100\\\"\\n                  }`}\\n                />\\n              </Button>\\n            </div>\\n          </PopoverPrimitive.Anchor>\\n          <PopoverPrimitive.Portal>\\n            <PopoverPrimitive.Content\\n              ref={onboardingTooltipRef}\\n              side=\\\"left\\\"\\n              // Breathing room between the tooltip and the assistant button.\\n              // 4px reads as \\\"touching\\\"; 12px gives a clear visual separation\\n              // that matches the spacing density of the canvas controls bar.\\n              sideOffset={12}\\n              align=\\\"center\\\"\\n              // Prevent Radix from grabbing focus when the tooltip opens \u2014\\n              // the user is mid-task on the canvas; surprise focus shifts\\n              // break their flow.\\n              onOpenAutoFocus={(e) => e.preventDefault()}\\n              onCloseAutoFocus={(e) => e.preventDefault()}\\n              onFocusOutside={markDiscovered}\\n              onEscapeKeyDown={markDiscovered}\\n              data-testid=\\\"assistant-onboarding-tooltip\\\"\\n              onKeyDown={handleOnboardingTooltipTabBoundary}\\n              // Canvas-level stacking: kept BELOW the z-50 modal/dialog/dropdown\\n              // layer so the onboarding tooltip never floats in front of an open\\n              // modal (e.g. \\\"My Files\\\"). The Portal still lifts it clear of the\\n              // ReactFlow Panel's overflow/clipping; only the z-index is capped.\\n              className=\\\"z-40 flex items-center gap-2 whitespace-nowrap rounded-md bg-muted px-2.5 py-1.5 text-sm font-medium text-foreground shadow-md\\\"\\n            >\\n              <button\\n                type=\\\"button\\\"\\n                data-testid=\\\"assistant-onboarding-dismiss\\\"\\n                aria-label={t(\\\"assistant.dismissOnboardingTooltip\\\")}\\n                className=\\\"flex h-4 w-4 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-muted-foreground/10 hover:text-foreground\\\"\\n                onClick={handleDismissTooltip}\\n              >\\n                <X className=\\\"h-3.5 w-3.5\\\" />\\n              </button>\\n              <span>{t(\\\"assistant.tryAssistant\\\")}</span>\\n              <button\\n                type=\\\"button\\\"\\n                data-testid=\\\"assistant-onboarding-open\\\"\\n                aria-label={t(\\\"assistant.openAssistant\\\")}\\n                className=\\\"flex h-4 w-4 shrink-0 items-center justify-center rounded text-foreground transition-colors hover:bg-muted-foreground/10\\\"\\n                onClick={handleAssistantClick}\\n              >\\n                <ArrowRight className=\\\"h-3.5 w-3.5\\\" />\\n              </button>\\n            </PopoverPrimitive.Content>\\n          </PopoverPrimitive.Portal>\\n        </PopoverPrimitive.Root>\\n        <CanvasControlsDropdown selectedNode={selectedNode} />\\n        <Button\\n          unstyled\\n          size=\\\"icon\\\"\\n          data-testid=\\\"canvas-add-note-button\\\"\\n          className=\\\"group flex h-8 w-8 items-center justify-center rounded-md hover:bg-muted disabled:cursor-not-allowed disabled:opacity-50\\\"\\n          title={locked ? t(\\\"version.readOnly\\\") : t(\\\"canvas.addStickyNote\\\")}\\n          aria-label={t(\\\"canvas.addStickyNote\\\")}\\n          onClick={handleAddNote}\\n          disabled={locked}\\n        >\\n          <ForwardedIconComponent\\n            name=\\\"sticky-note\\\"\\n            className={`h-[18px] w-[18px] transition-colors ${\\n              isAddNoteActive\\n                ? \\\"text-foreground\\\"\\n                : \\\"text-muted-foreground group-hover:text-foreground\\\"\\n            }`}\\n          />\\n        </Button>\\n        <Button\\n          unstyled\\n          size=\\\"icon\\\"\\n          data-testid=\\\"canvas_controls_minimize_all\\\"\\n          aria-pressed={allMinimized}\\n          disabled={locked || !hasGenericNodes}\\n          className={`group flex h-8 w-8 items-center justify-center rounded-md ${\\n            allMinimized ? \\\"bg-muted text-foreground\\\" : \\\"hover:bg-muted\\\"\\n          } ${locked || !hasGenericNodes ? \\\"cursor-not-allowed opacity-50\\\" : \\\"\\\"}`}\\n          title={\\n            locked\\n              ? t(\\\"version.readOnly\\\")\\n              : allMinimized\\n                ? t(\\\"canvasControls.expandAll\\\")\\n                : t(\\\"canvasControls.minimizeAll\\\")\\n          }\\n          aria-label={\\n            allMinimized\\n              ? t(\\\"canvasControls.expandAll\\\")\\n              : t(\\\"canvasControls.minimizeAll\\\")\\n          }\\n          onClick={toggleMinimizeAllAndAlign}\\n        >\\n          <ForwardedIconComponent\\n            name={allMinimized ? \\\"Maximize2\\\" : \\\"Minimize2\\\"}\\n            className={`h-[18px] w-[18px] transition-colors ${\\n              allMinimized\\n                ? \\\"text-foreground\\\"\\n                : \\\"text-muted-foreground group-hover:text-foreground\\\"\\n            }`}\\n          />\\n        </Button>\\n        <HelpDropdown />\\n        {children}\\n      </Panel>\\n    </>\\n  );\\n};\\n\\nexport default CanvasControls;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/CanvasControlsDropdown.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"638100f03fa7763c2e2243d22277704f6408f5bb20756d5893a0540fc009a69b\",\"content\":\"import { useReactFlow, useStore } from \\\"@xyflow/react\\\";\\nimport { useCallback, useEffect, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport { shallow } from \\\"zustand/shallow\\\";\\nimport IconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport {\\n  DropdownMenu,\\n  DropdownMenuContent,\\n  DropdownMenuTrigger,\\n} from \\\"@/components/ui/dropdown-menu\\\";\\nimport { Separator } from \\\"@/components/ui/separator\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport { AllNodeType } from \\\"@/types/flow\\\";\\nimport DropdownControlButton from \\\"./DropdownControlButton\\\";\\nimport {\\n  FIT_VIEW_OPTIONS,\\n  FIT_VIEW_PADDING_WITH_INSPECTION_PANEL,\\n} from \\\"./fit-view-options\\\";\\nimport { formatZoomPercentage, reactFlowSelector } from \\\"./utils/canvasUtils\\\";\\n\\nexport const KEYBOARD_SHORTCUTS = {\\n  ZOOM_IN: { key: \\\"+\\\", code: \\\"Equal\\\" },\\n  ZOOM_OUT: { key: \\\"-\\\", code: \\\"Minus\\\" },\\n  FIT_VIEW: { key: \\\"1\\\", code: \\\"Digit1\\\" },\\n  RESET_ZOOM: { key: \\\"0\\\", code: \\\"Digit0\\\" },\\n} as const;\\n\\nconst CanvasControlsDropdown = ({\\n  selectedNode,\\n}: {\\n  selectedNode: AllNodeType | null;\\n}) => {\\n  const { t } = useTranslation();\\n  const [isOpen, setIsOpen] = useState(false);\\n  const { fitView, zoomIn, zoomOut, zoomTo } = useReactFlow();\\n\\n  const { minZoomReached, maxZoomReached, zoom } = useStore(\\n    reactFlowSelector,\\n    shallow,\\n  );\\n\\n  const inspectionPanelVisible = useFlowStore(\\n    (state) => state.inspectionPanelVisible,\\n  );\\n\\n  useEffect(() => {\\n    const handleKeyDown = (event: KeyboardEvent) => {\\n      const isModifierPressed = event.metaKey || event.ctrlKey;\\n\\n      if (!isModifierPressed) return;\\n\\n      switch (event.code) {\\n        case KEYBOARD_SHORTCUTS.ZOOM_IN.code:\\n          event.preventDefault();\\n          if (!maxZoomReached) {\\n            zoomIn();\\n          }\\n          break;\\n        case KEYBOARD_SHORTCUTS.ZOOM_OUT.code:\\n          event.preventDefault();\\n          if (!minZoomReached) {\\n            zoomOut();\\n          }\\n          break;\\n        case KEYBOARD_SHORTCUTS.FIT_VIEW.code:\\n          event.preventDefault();\\n          fitView();\\n          break;\\n        case KEYBOARD_SHORTCUTS.RESET_ZOOM.code:\\n          event.preventDefault();\\n          zoomTo(1);\\n          break;\\n      }\\n    };\\n\\n    document.addEventListener(\\\"keydown\\\", handleKeyDown);\\n    return () => document.removeEventListener(\\\"keydown\\\", handleKeyDown);\\n  }, [zoomIn, zoomOut, fitView, zoomTo, maxZoomReached, minZoomReached]);\\n\\n  const handleZoomIn = useCallback(() => {\\n    zoomIn();\\n  }, [zoomIn]);\\n\\n  const handleZoomOut = useCallback(() => {\\n    zoomOut();\\n  }, [zoomOut]);\\n\\n  const handleFitView = useCallback(() => {\\n    fitView({\\n      ...FIT_VIEW_OPTIONS,\\n      // The inspection panel covers the right of the canvas, so the graph has\\n      // to clear it rather than the usual edge padding.\\n      padding:\\n        inspectionPanelVisible && selectedNode\\n          ? FIT_VIEW_PADDING_WITH_INSPECTION_PANEL\\n          : FIT_VIEW_OPTIONS.padding,\\n    });\\n  }, [fitView, inspectionPanelVisible, selectedNode]);\\n\\n  const handleResetZoom = useCallback(() => {\\n    zoomTo(1);\\n  }, [zoomTo]);\\n\\n  return (\\n    <DropdownMenu open={isOpen} onOpenChange={setIsOpen}>\\n      <DropdownMenuTrigger asChild>\\n        <Button\\n          variant=\\\"ghost\\\"\\n          data-testid=\\\"canvas_controls_dropdown\\\"\\n          className=\\\"group flex h-8 items-center justify-center rounded-md px-0.5 hover:bg-muted\\\"\\n          unstyled\\n          title={t(\\\"canvas.controls\\\")}\\n          aria-label={t(\\\"canvas.zoomControlAriaLabel\\\", {\\n            zoom: formatZoomPercentage(zoom),\\n          })}\\n        >\\n          <div className=\\\"flex items-center justify-center gap-1\\\">\\n            <span className=\\\"w-11 pl-1.5 text-left text-sm tabular-nums text-muted-foreground group-hover:text-foreground\\\">\\n              {formatZoomPercentage(zoom)}\\n            </span>\\n            <IconComponent\\n              name={isOpen ? \\\"ChevronDown\\\" : \\\"ChevronUp\\\"}\\n              aria-hidden=\\\"true\\\"\\n              className=\\\"text-muted-foreground group-hover:text-foreground !h-5 !w-5\\\"\\n            />\\n          </div>\\n        </Button>\\n      </DropdownMenuTrigger>\\n      <DropdownMenuContent\\n        side=\\\"top\\\"\\n        align=\\\"center\\\"\\n        className=\\\"flex flex-col w-full\\\"\\n      >\\n        <DropdownControlButton\\n          tooltipText={t(\\\"canvas.zoomIn\\\")}\\n          onClick={handleZoomIn}\\n          disabled={maxZoomReached}\\n          testId=\\\"zoom_in\\\"\\n          label={t(\\\"canvas.zoomIn\\\")}\\n          shortcut={KEYBOARD_SHORTCUTS.ZOOM_IN.key}\\n        />\\n        <DropdownControlButton\\n          tooltipText={t(\\\"canvas.zoomOut\\\")}\\n          onClick={handleZoomOut}\\n          disabled={minZoomReached}\\n          testId=\\\"zoom_out\\\"\\n          label={t(\\\"canvas.zoomOut\\\")}\\n          shortcut={KEYBOARD_SHORTCUTS.ZOOM_OUT.key}\\n        />\\n        <Separator />\\n        <DropdownControlButton\\n          tooltipText={t(\\\"canvas.resetZoomTooltip\\\")}\\n          onClick={handleResetZoom}\\n          testId=\\\"reset_zoom\\\"\\n          label={t(\\\"canvas.zoomTo100\\\")}\\n          shortcut={KEYBOARD_SHORTCUTS.RESET_ZOOM.key}\\n        />\\n        <DropdownControlButton\\n          tooltipText={t(\\\"canvas.fitViewTooltip\\\")}\\n          onClick={handleFitView}\\n          testId=\\\"fit_view\\\"\\n          label={t(\\\"canvas.zoomToFit\\\")}\\n          shortcut={KEYBOARD_SHORTCUTS.FIT_VIEW.key}\\n        />\\n      </DropdownMenuContent>\\n    </DropdownMenu>\\n  );\\n};\\n\\nexport default CanvasControlsDropdown;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/DropdownControlButton.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e238182413606be8b286ea00934540837fd734b915f826b020f4c7e890531cfa\",\"content\":\"import React from \\\"react\\\";\\nimport { ForwardedIconComponent } from \\\"@/components/common/genericIconComponent\\\";\\nimport {\\n  DropdownMenuCheckboxItem,\\n  DropdownMenuItem,\\n} from \\\"@/components/ui/dropdown-menu\\\";\\nimport { cn } from \\\"@/utils/utils\\\";\\nimport { getModifierKey } from \\\"./utils/canvasUtils\\\";\\n\\nexport type DropdownControlButtonProps = {\\n  tooltipText?: string;\\n  onClick?: () => void;\\n  disabled?: boolean;\\n  testId?: string;\\n  label?: string;\\n  shortcut?: string;\\n  iconName?: string;\\n  hasToogle?: boolean;\\n  toggleValue?: boolean;\\n  externalLink?: boolean;\\n};\\n\\nconst DropdownControlButton: React.FC<DropdownControlButtonProps> = ({\\n  tooltipText,\\n  onClick = () => {},\\n  disabled,\\n  testId,\\n  label = \\\"\\\",\\n  shortcut = \\\"\\\",\\n  iconName,\\n  hasToogle = false,\\n  toggleValue = false,\\n  externalLink = false,\\n}) => {\\n  const ariaLabel = tooltipText || label;\\n\\n  const content = (\\n    <>\\n      {iconName && (\\n        <ForwardedIconComponent\\n          name={iconName}\\n          aria-hidden=\\\"true\\\"\\n          className=\\\"text-muted-foreground group-hover:text-primary\\\"\\n        />\\n      )}\\n      <div className=\\\"flex flex-row items-center justify-between w-full h-full\\\">\\n        <span className=\\\"text-muted-foreground text-sm mr-2 group-hover:text-primary\\\">\\n          {label}\\n        </span>\\n        <div className=\\\"flex flex-row items-center text-sm\\\">\\n          {shortcut && (\\n            <div\\n              aria-hidden=\\\"true\\\"\\n              className=\\\"flex items-center gap-0.5 text-muted-foreground group-hover:text-primary\\\"\\n            >\\n              <span>{getModifierKey()}</span>\\n              <span>{shortcut}</span>\\n            </div>\\n          )}\\n          {externalLink && (\\n            <ForwardedIconComponent\\n              name=\\\"external-link\\\"\\n              aria-hidden=\\\"true\\\"\\n              className=\\\"text-muted-foreground group-hover:text-primary opacity-0 group-hover:opacity-100\\\"\\n            />\\n          )}\\n        </div>\\n      </div>\\n    </>\\n  );\\n\\n  // Menu toggles need their own accessible pattern (role=\\\"menuitemcheckbox\\\",\\n  // a single interactive control) rather than nesting an independently\\n  // interactive Switch inside a menu item \u2014 Radix's CheckboxItem is the\\n  // purpose-built primitive for exactly this.\\n  if (hasToogle) {\\n    return (\\n      <DropdownMenuCheckboxItem\\n        data-testid={testId}\\n        className={cn(\\n          \\\"group flex items-center justify-center !py-1.5 !px-2 hover:bg-accent h-full rounded-none\\\",\\n          disabled && \\\"cursor-not-allowed opacity-50\\\",\\n        )}\\n        checked={toggleValue}\\n        onCheckedChange={onClick}\\n        disabled={disabled}\\n        title={ariaLabel}\\n        aria-label={ariaLabel}\\n        onSelect={(event) => event.preventDefault()}\\n      >\\n        {content}\\n      </DropdownMenuCheckboxItem>\\n    );\\n  }\\n\\n  return (\\n    <DropdownMenuItem\\n      data-testid={testId}\\n      className={cn(\\n        \\\"group flex items-center justify-center !py-1.5 !px-2 hover:bg-accent h-full rounded-none\\\",\\n        disabled && \\\"cursor-not-allowed opacity-50\\\",\\n      )}\\n      onClick={onClick}\\n      disabled={disabled}\\n      title={ariaLabel}\\n      aria-label={ariaLabel}\\n      onSelect={(event) => event.preventDefault()}\\n    >\\n      {content}\\n    </DropdownMenuItem>\\n  );\\n};\\n\\nexport default DropdownControlButton;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/HelpDropdown.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"12261e235be54ec2312f270334aa1d00fb21d68f9cc6a6476f129d2dfc8e8e2e\",\"content\":\"import { useCallback, useState } from \\\"react\\\";\\nimport { useNavigate } from \\\"react-router-dom\\\";\\nimport { HelpDropdownView } from \\\"@/components/core/canvasControlsComponent/HelpDropdownView\\\";\\nimport {\\n  BUG_REPORT_URL,\\n  DATASTAX_DOCS_URL,\\n  DESKTOP_URL,\\n  DOCS_URL,\\n} from \\\"@/constants/constants\\\";\\nimport { ENABLE_DATASTAX_LANGFLOW } from \\\"@/customization/feature-flags\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\n\\nconst HelpDropdown = () => {\\n  const navigate = useNavigate();\\n  const [isHelpMenuOpen, setIsHelpMenuOpen] = useState(false);\\n  const helperLineEnabled = useFlowStore((state) => state.helperLineEnabled);\\n  const setHelperLineEnabled = useFlowStore(\\n    (state) => state.setHelperLineEnabled,\\n  );\\n\\n  const onToggleHelperLines = useCallback(() => {\\n    setHelperLineEnabled(!helperLineEnabled);\\n  }, [helperLineEnabled]);\\n\\n  const docsUrl = ENABLE_DATASTAX_LANGFLOW ? DATASTAX_DOCS_URL : DOCS_URL;\\n\\n  return (\\n    <HelpDropdownView\\n      isOpen={isHelpMenuOpen}\\n      onOpenChange={setIsHelpMenuOpen}\\n      helperLineEnabled={helperLineEnabled}\\n      onToggleHelperLines={onToggleHelperLines}\\n      navigateTo={(path) => navigate(path)}\\n      openLink={(url) => window.open(url, \\\"_blank\\\")}\\n      urls={{ docs: docsUrl, bugReport: BUG_REPORT_URL, desktop: DESKTOP_URL }}\\n    />\\n  );\\n};\\n\\nexport default HelpDropdown;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/HelpDropdownView.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a08f82706c9449fe642ef0700c679532f56f38465150146649a51bff239f938a\",\"content\":\"import { useTranslation } from \\\"react-i18next\\\";\\nimport IconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport {\\n  DropdownMenu,\\n  DropdownMenuContent,\\n  DropdownMenuTrigger,\\n} from \\\"@/components/ui/dropdown-menu\\\";\\nimport { Separator } from \\\"@/components/ui/separator\\\";\\nimport DropdownControlButton from \\\"./DropdownControlButton\\\";\\n\\nexport type HelpDropdownViewProps = {\\n  isOpen: boolean;\\n  onOpenChange: (open: boolean) => void;\\n  helperLineEnabled: boolean;\\n  onToggleHelperLines: () => void;\\n  navigateTo: (path: string) => void;\\n  openLink: (url: string) => void;\\n  urls: {\\n    docs: string;\\n    bugReport: string;\\n    desktop: string;\\n  };\\n};\\n\\nexport const HelpDropdownView = ({\\n  isOpen,\\n  onOpenChange,\\n  helperLineEnabled,\\n  onToggleHelperLines,\\n  navigateTo,\\n  openLink,\\n  urls,\\n}: HelpDropdownViewProps) => {\\n  const { t } = useTranslation();\\n  return (\\n    <DropdownMenu open={isOpen} onOpenChange={onOpenChange}>\\n      <DropdownMenuTrigger asChild>\\n        <Button\\n          variant=\\\"ghost\\\"\\n          size=\\\"icon\\\"\\n          className=\\\"group flex h-8 w-8 items-center justify-center rounded-md hover:bg-muted\\\"\\n          title={t(\\\"help.title\\\")}\\n          aria-label={t(\\\"help.title\\\")}\\n          data-testid=\\\"canvas_controls_dropdown_help\\\"\\n        >\\n          <IconComponent\\n            name=\\\"Circle-Help\\\"\\n            aria-hidden=\\\"true\\\"\\n            className=\\\"text-muted-foreground group-hover:text-foreground !h-5 !w-5\\\"\\n          />\\n        </Button>\\n      </DropdownMenuTrigger>\\n      <DropdownMenuContent\\n        side=\\\"top\\\"\\n        align=\\\"center\\\"\\n        className=\\\"flex flex-col w-full\\\"\\n      >\\n        <DropdownControlButton\\n          iconName=\\\"book-open\\\"\\n          testId=\\\"canvas_controls_dropdown_docs\\\"\\n          label={t(\\\"help.docs\\\")}\\n          externalLink\\n          onClick={() => openLink(urls.docs)}\\n        />\\n        <DropdownControlButton\\n          iconName=\\\"keyboard\\\"\\n          testId=\\\"canvas_controls_dropdown_shortcuts\\\"\\n          label={t(\\\"help.shortcuts\\\")}\\n          onClick={() => navigateTo(\\\"/settings/shortcuts\\\")}\\n        />\\n        <DropdownControlButton\\n          iconName=\\\"bug\\\"\\n          testId=\\\"canvas_controls_dropdown_report_a_bug\\\"\\n          externalLink\\n          label={t(\\\"help.reportBug\\\")}\\n          onClick={() => openLink(urls.bugReport)}\\n        />\\n        <Separator />\\n        <DropdownControlButton\\n          iconName=\\\"download\\\"\\n          testId=\\\"canvas_controls_dropdown_get_langflow_desktop\\\"\\n          label={t(\\\"help.getLangflowDesktop\\\")}\\n          externalLink\\n          onClick={() => openLink(urls.desktop)}\\n        />\\n        <DropdownControlButton\\n          iconName={!helperLineEnabled ? \\\"UnfoldHorizontal\\\" : \\\"FoldHorizontal\\\"}\\n          testId=\\\"canvas_controls_dropdown_enable_smart_guides\\\"\\n          onClick={onToggleHelperLines}\\n          toggleValue={helperLineEnabled}\\n          label={t(\\\"help.enableSmartGuides\\\")}\\n          hasToogle={true}\\n        />\\n      </DropdownMenuContent>\\n    </DropdownMenu>\\n  );\\n};\\n\\nexport default HelpDropdownView;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/CanvasControlButton.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6e0592bcd23acca0946b1f172d5163854b25b991830c64b7696aae48df913fb8\",\"content\":\"import { render, screen } from \\\"@testing-library/react\\\";\\nimport type { ComponentProps, ReactNode } from \\\"react\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport CanvasControlButton from \\\"../CanvasControlButton\\\";\\n\\n// ControlButton renders the real DOM <button> and spreads its props, so we can\\n// assert exactly which attributes (title / aria-label) reach the element.\\njest.mock(\\\"@xyflow/react\\\", () => ({\\n  ControlButton: ({ children, ...props }: ComponentProps<\\\"button\\\">) => (\\n    <button type=\\\"button\\\" {...props}>\\n      {children}\\n    </button>\\n  ),\\n}));\\n\\n// ShadTooltip is the single, styled tooltip \u2014 expose its content so we can\\n// confirm the button's label is surfaced through it (and only it).\\nlet lastShadTooltipProps: Record<string, unknown> = {};\\n\\njest.mock(\\\"@/components/common/shadTooltipComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({\\n    content,\\n    children,\\n    ...props\\n  }: {\\n    content?: string;\\n    children?: ReactNode;\\n    [key: string]: unknown;\\n  }) => {\\n    lastShadTooltipProps = props;\\n    return (\\n      <div data-testid=\\\"shad-tooltip\\\" data-content={content}>\\n        {children}\\n      </div>\\n    );\\n  },\\n}));\\n\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name }: { name?: string }) => (\\n    <div data-testid={`icon-${name}`} />\\n  ),\\n}));\\n\\n// Regression coverage for the duplicate sidebar tooltip bug: the control nav\\n// buttons rendered BOTH a native `title` attribute and a ShadTooltip, so\\n// hovering surfaced two tooltips at once (one of them exposing a raw i18n key).\\ndescribe(\\\"CanvasControlButton \u2014 single tooltip (no native title)\\\", () => {\\n  const setup = () =>\\n    render(\\n      <CanvasControlButton\\n        iconName=\\\"blocks\\\"\\n        tooltipText=\\\"Bundles\\\"\\n        onClick={jest.fn()}\\n        testId=\\\"bundles\\\"\\n      />,\\n    );\\n\\n  beforeEach(() => {\\n    lastShadTooltipProps = {};\\n  });\\n\\n  it(\\\"should_have_no_axe_violations\\\", async () => {\\n    const { container } = setup();\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"does not render a native title attribute (would be a second tooltip)\\\", () => {\\n    setup();\\n    const button = screen.getByRole(\\\"button\\\");\\n    expect(button).not.toHaveAttribute(\\\"title\\\");\\n  });\\n\\n  it(\\\"exposes the label via aria-label and the ShadTooltip, not a raw key\\\", () => {\\n    setup();\\n    expect(screen.getByRole(\\\"button\\\")).toHaveAttribute(\\\"aria-label\\\", \\\"Bundles\\\");\\n    expect(screen.getByTestId(\\\"shad-tooltip\\\")).toHaveAttribute(\\n      \\\"data-content\\\",\\n      \\\"Bundles\\\",\\n    );\\n  });\\n\\n  it(\\\"wraps the real button (not a decorative inner div) so aria-describedby suppression actually reaches it\\\", () => {\\n    setup();\\n\\n    // ShadTooltip must be the ancestor of the actual <button> so its\\n    // TooltipTrigger clones aria-describedby onto the real focusable\\n    // element, not an inert nested div.\\n    const tooltip = screen.getByTestId(\\\"shad-tooltip\\\");\\n    const button = screen.getByRole(\\\"button\\\");\\n    expect(tooltip).toContainElement(button);\\n    expect(\\\"ariaDescribedBy\\\" in lastShadTooltipProps).toBe(true);\\n    expect(lastShadTooltipProps.ariaDescribedBy).toBeUndefined();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/CanvasControls.a11y.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9ca4583145d904452b60566d1235dc6cc323bf70a1afd05d30726b9487e7e81c\",\"content\":\"import { render, screen } from \\\"@testing-library/react\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport CanvasControls from \\\"../CanvasControls\\\";\\n\\njest.mock(\\\"@xyflow/react\\\", () => ({\\n  Panel: ({ children, ...props }) => (\\n    <div data-testid=\\\"panel\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  useReactFlow: () => ({\\n    fitView: jest.fn(),\\n    zoomIn: jest.fn(),\\n    zoomOut: jest.fn(),\\n    zoomTo: jest.fn(),\\n  }),\\n  useUpdateNodeInternals: () => jest.fn(),\\n  useStore: () => ({\\n    isInteractive: true,\\n    minZoomReached: false,\\n    maxZoomReached: false,\\n    zoom: 1,\\n  }),\\n  useStoreApi: () => ({ setState: jest.fn() }),\\n}));\\n\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector) => {\\n    const state = {\\n      nodes: [],\\n      edges: [],\\n      setNodes: jest.fn(),\\n      currentFlow: { locked: false },\\n    };\\n    return typeof selector === \\\"function\\\" ? selector(state) : false;\\n  }),\\n}));\\n\\njest.mock(\\\"@/stores/flowsManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector) => {\\n    const state = {};\\n    return selector(state);\\n  }),\\n}));\\n\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name, className }) => (\\n    <span data-testid={`icon-${name}`} className={className} aria-hidden=\\\"true\\\">\\n      {name}\\n    </span>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({ children, onClick, title, ...rest }) => (\\n    <button onClick={onClick} title={title} {...rest}>\\n      {children}\\n    </button>\\n  ),\\n}));\\n\\njest.mock(\\\"../CanvasControlsDropdown\\\", () => ({\\n  __esModule: true,\\n  default: () => <div data-testid=\\\"controls-dropdown\\\" />,\\n}));\\n\\njest.mock(\\\"../HelpDropdown\\\", () => ({\\n  __esModule: true,\\n  default: () => <div data-testid=\\\"help-dropdown\\\" />,\\n}));\\n\\njest.mock(\\\"@/assets/langflow_assistant.svg\\\", () => \\\"mock-assistant-icon.svg\\\");\\njest.mock(\\n  \\\"@/assets/langflow_assistant_idle.svg\\\",\\n  () => \\\"mock-assistant-idle-icon.svg\\\",\\n);\\n\\njest.mock(\\\"@/stores/assistantManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector) => {\\n    const state = { toggleAssistant: jest.fn() };\\n    return typeof selector === \\\"function\\\" ? selector(state) : state;\\n  }),\\n}));\\n\\njest.mock(\\\"@/customization/feature-flags\\\", () => ({\\n  ENABLE_INSPECTION_PANEL: false,\\n}));\\n\\njest.mock(\\\"zustand/react/shallow\\\", () => ({\\n  useShallow: (fn: unknown) => fn,\\n}));\\n\\ndescribe(\\\"CanvasControls toolbar accessibility\\\", () => {\\n  it(\\\"should_have_no_axe_violations_when_unlocked\\\", async () => {\\n    const { container } = render(<CanvasControls selectedNode={null} />);\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations_when_locked\\\", async () => {\\n    const { container } = render(\\n      <CanvasControls selectedNode={null} effectiveLocked />,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"should_expose_accessible_name_for_add_note_button\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    expect(\\n      screen.getByRole(\\\"button\\\", { name: \\\"Add Sticky Note\\\" }),\\n    ).toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_expose_accessible_name_for_minimize_all_button\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    expect(\\n      screen.getByRole(\\\"button\\\", { name: \\\"Minimize all\\\" }),\\n    ).toBeInTheDocument();\\n  });\\n\\n  it(\\\"keeps each control's distinct accessible name when locked, instead of collapsing them all to the same read-only label\\\", () => {\\n    render(<CanvasControls selectedNode={null} effectiveLocked />);\\n\\n    // State belongs in state (disabled + title), not in the name \u2014 three\\n    // different controls all announcing \\\"(Read-Only)\\\" would be\\n    // indistinguishable to a screen reader user.\\n    expect(screen.getByTestId(\\\"canvas-add-note-button\\\")).toHaveAccessibleName(\\n      \\\"Add Sticky Note\\\",\\n    );\\n    expect(\\n      screen.getByTestId(\\\"canvas_controls_minimize_all\\\"),\\n    ).toHaveAccessibleName(\\\"Minimize all\\\");\\n    expect(screen.getByTestId(\\\"assistant-button\\\")).toHaveAccessibleName(\\n      \\\"Langflow Assistant\\\",\\n    );\\n  });\\n\\n  it(\\\"disables the controls and surfaces read-only via title when locked\\\", () => {\\n    render(<CanvasControls selectedNode={null} effectiveLocked />);\\n\\n    expect(screen.getByTestId(\\\"canvas-add-note-button\\\")).toBeDisabled();\\n    expect(screen.getByTestId(\\\"canvas-add-note-button\\\")).toHaveAttribute(\\n      \\\"title\\\",\\n      \\\"(Read-Only)\\\",\\n    );\\n    expect(screen.getByTestId(\\\"canvas_controls_minimize_all\\\")).toBeDisabled();\\n    expect(screen.getByTestId(\\\"canvas_controls_minimize_all\\\")).toHaveAttribute(\\n      \\\"title\\\",\\n      \\\"(Read-Only)\\\",\\n    );\\n    expect(screen.getByTestId(\\\"assistant-button\\\")).toBeDisabled();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/CanvasControls.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8e2f403d561f93b929968905a151db7a24f3972a5a9e53a92e93ea445fad1bc2\",\"content\":\"import { act, fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport userEvent from \\\"@testing-library/user-event\\\";\\nimport CanvasControls from \\\"../CanvasControls\\\";\\n\\n// The modal/dialog/dropdown overlay layer in the app all sits at `z-50`\\n// (see ui/dialog.tsx, ui/popover.tsx). The assistant onboarding tooltip must\\n// stay at canvas level \u2014 strictly BELOW this layer \u2014 so it never floats in\\n// front of an open modal like \\\"My Files\\\".\\nconst MODAL_LAYER_Z_INDEX = 50;\\nconst ONBOARDING_TOOLTIP_DELAY_MS = 10_000;\\n\\n// Extract the numeric z-index from a Tailwind className, supporting both the\\n// scale token (`z-40`) and the arbitrary-value form (`z-[60]`).\\nconst getZIndex = (className: string): number | null => {\\n  const token = className\\n    .split(/\\\\s+/)\\n    .find((cls) => /^z-(\\\\[?\\\\d+\\\\]?)$/.test(cls));\\n  if (!token) return null;\\n  const digits = token.replace(/^z-\\\\[?/, \\\"\\\").replace(/\\\\]$/, \\\"\\\");\\n  return Number.parseInt(digits, 10);\\n};\\n\\nconst reactFlowFns = {\\n  fitView: jest.fn(),\\n  zoomIn: jest.fn(),\\n  zoomOut: jest.fn(),\\n  zoomTo: jest.fn(),\\n};\\n\\njest.mock(\\\"@xyflow/react\\\", () => ({\\n  Panel: ({ children, ...props }) => (\\n    <div data-testid=\\\"panel\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  useReactFlow: () => reactFlowFns,\\n  useUpdateNodeInternals: () => jest.fn(),\\n  useStore: () => ({\\n    isInteractive: true,\\n    minZoomReached: false,\\n    maxZoomReached: false,\\n    zoom: 1,\\n  }),\\n  useStoreApi: () => ({ setState: jest.fn() }),\\n}));\\n\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector) => {\\n    const state = {\\n      nodes: [],\\n      edges: [],\\n      setNodes: jest.fn(),\\n      currentFlow: { locked: false },\\n    };\\n    return typeof selector === \\\"function\\\" ? selector(state) : false;\\n  }),\\n}));\\n\\njest.mock(\\\"@/stores/flowsManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector) => {\\n    const state = {};\\n    return selector(state);\\n  }),\\n}));\\n\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name, className }) => (\\n    <span data-testid={`icon-${name}`} className={className}>\\n      {name}\\n    </span>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({ children, onClick, title, ...rest }) => (\\n    <button onClick={onClick} title={title} {...rest}>\\n      {children}\\n    </button>\\n  ),\\n}));\\n\\njest.mock(\\\"../CanvasControlsDropdown\\\", () => ({\\n  __esModule: true,\\n  default: () => <div data-testid=\\\"controls-dropdown\\\" />,\\n}));\\n\\njest.mock(\\\"../HelpDropdown\\\", () => ({\\n  __esModule: true,\\n  default: () => <div data-testid=\\\"help-dropdown\\\" />,\\n}));\\n\\njest.mock(\\\"@/assets/langflow_assistant.svg\\\", () => \\\"mock-assistant-icon.svg\\\");\\njest.mock(\\n  \\\"@/assets/langflow_assistant_idle.svg\\\",\\n  () => \\\"mock-assistant-idle-icon.svg\\\",\\n);\\n\\njest.mock(\\\"@/stores/assistantManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector) => {\\n    const state = { toggleAssistant: jest.fn() };\\n    return typeof selector === \\\"function\\\" ? selector(state) : state;\\n  }),\\n}));\\n\\njest.mock(\\\"@/customization/feature-flags\\\", () => ({\\n  ENABLE_INSPECTION_PANEL: false,\\n}));\\n\\njest.mock(\\\"zustand/react/shallow\\\", () => ({\\n  useShallow: (fn: unknown) => fn,\\n}));\\n\\ndescribe(\\\"CanvasControls\\\", () => {\\n  const mockDispatchEvent = jest.fn();\\n  const originalDispatchEvent = window.dispatchEvent;\\n\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n    window.dispatchEvent = mockDispatchEvent;\\n  });\\n\\n  afterEach(() => {\\n    window.dispatchEvent = originalDispatchEvent;\\n  });\\n\\n  it(\\\"should_render_panel_with_all_controls_when_mounted\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"main_canvas_controls\\\")).toBeInTheDocument();\\n    expect(screen.getByTestId(\\\"controls-dropdown\\\")).toBeInTheDocument();\\n    expect(screen.getByTestId(\\\"help-dropdown\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_render_assistant_button_with_new_badge\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    expect(screen.getByText(\\\"New\\\")).toBeInTheDocument();\\n    expect(screen.getByAltText(\\\"Langflow Assistant\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_hide_new_badge_when_assistant_already_discovered\\\", () => {\\n    localStorage.setItem(\\\"langflow-assistant-discovered\\\", \\\"true\\\");\\n    try {\\n      render(<CanvasControls selectedNode={null} />);\\n\\n      expect(screen.queryByText(\\\"New\\\")).not.toBeInTheDocument();\\n    } finally {\\n      localStorage.clear();\\n    }\\n  });\\n\\n  it(\\\"should_keep_new_badge_hidden_after_assistant_opened_and_closed\\\", () => {\\n    localStorage.clear();\\n    render(<CanvasControls selectedNode={null} />);\\n    expect(screen.getByText(\\\"New\\\")).toBeInTheDocument();\\n\\n    // Open then close the assistant \u2014 the panel-open state alone hid the\\n    // badge before this fix, so the badge must stay gone once the panel is\\n    // closed again for the ``discovered`` gating to be proven.\\n    fireEvent.click(screen.getByTestId(\\\"assistant-button\\\"));\\n    fireEvent.click(screen.getByTestId(\\\"assistant-button\\\"));\\n\\n    expect(screen.queryByText(\\\"New\\\")).not.toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_render_sticky_note_button\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    expect(screen.getByTitle(\\\"Add Sticky Note\\\")).toBeInTheDocument();\\n    expect(screen.getByTestId(\\\"icon-sticky-note\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_dispatch_add_note_event_when_sticky_note_clicked\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    const stickyNoteButton = screen.getByTitle(\\\"Add Sticky Note\\\");\\n    fireEvent.click(stickyNoteButton);\\n\\n    expect(mockDispatchEvent).toHaveBeenCalledWith(\\n      expect.objectContaining({ type: \\\"lf:start-add-note\\\" }),\\n    );\\n  });\\n\\n  it(\\\"should_disable_canvas_mutation_controls_when_read_only\\\", () => {\\n    render(<CanvasControls selectedNode={null} effectiveLocked />);\\n\\n    expect(screen.getByTestId(\\\"assistant-button\\\")).toBeDisabled();\\n    expect(screen.getByTestId(\\\"canvas-add-note-button\\\")).toBeDisabled();\\n    expect(screen.getByTestId(\\\"canvas-add-note-button\\\")).toHaveAttribute(\\n      \\\"title\\\",\\n      \\\"(Read-Only)\\\",\\n    );\\n\\n    fireEvent.click(screen.getByTestId(\\\"canvas-add-note-button\\\"));\\n    expect(mockDispatchEvent).not.toHaveBeenCalled();\\n  });\\n\\n  it(\\\"should_render_children_when_provided\\\", () => {\\n    render(\\n      <CanvasControls selectedNode={null}>\\n        <div data-testid=\\\"child-element\\\">Lock Button</div>\\n      </CanvasControls>,\\n    );\\n\\n    expect(screen.getByTestId(\\\"child-element\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_position_panel_at_bottom_center\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    const panel = screen.getByTestId(\\\"main_canvas_controls\\\");\\n    expect(panel).toHaveAttribute(\\\"position\\\", \\\"bottom-center\\\");\\n  });\\n\\n  it(\\\"should_have_overflow_visible_class_on_panel\\\", () => {\\n    render(<CanvasControls selectedNode={null} />);\\n\\n    const panel = screen.getByTestId(\\\"main_canvas_controls\\\");\\n    expect(panel.className).toContain(\\\"!overflow-visible\\\");\\n  });\\n\\n  it(\\\"should_render_onboarding_tooltip_below_modal_layer_when_active\\\", () => {\\n    // Arrange \u2014 fresh browser (assistant not yet discovered) so the onboarding\\n    // tooltip is eligible to surface after the idle delay.\\n    localStorage.clear();\\n    jest.useFakeTimers();\\n\\n    try {\\n      render(<CanvasControls selectedNode={null} />);\\n\\n      // Act \u2014 let the idle delay elapse so the popover opens and the tooltip\\n      // (rendered via a Portal on document.body) mounts.\\n      act(() => {\\n        jest.advanceTimersByTime(ONBOARDING_TOOLTIP_DELAY_MS);\\n      });\\n\\n      // Assert \u2014 the tooltip stays at canvas level: its z-index must be below\\n      // the z-50 modal/dialog layer so it never floats over an open modal.\\n      const tooltip = screen.getByTestId(\\\"assistant-onboarding-tooltip\\\");\\n      const zIndex = getZIndex(tooltip.className);\\n\\n      expect(zIndex).not.toBeNull();\\n      expect(zIndex as number).toBeLessThan(MODAL_LAYER_Z_INDEX);\\n    } finally {\\n      jest.useRealTimers();\\n    }\\n  });\\n\\n  it(\\\"should_allow_tab_to_leave_onboarding_tooltip\\\", async () => {\\n    localStorage.clear();\\n    jest.useFakeTimers();\\n    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });\\n    const nextButton = document.createElement(\\\"button\\\");\\n    nextButton.textContent = \\\"Next focus target\\\";\\n\\n    try {\\n      render(<CanvasControls selectedNode={null} />);\\n\\n      act(() => {\\n        jest.advanceTimersByTime(ONBOARDING_TOOLTIP_DELAY_MS);\\n      });\\n\\n      document.body.appendChild(nextButton);\\n\\n      screen.getByTestId(\\\"assistant-onboarding-dismiss\\\").focus();\\n      await user.tab();\\n      expect(screen.getByTestId(\\\"assistant-onboarding-open\\\")).toHaveFocus();\\n      await user.tab();\\n\\n      expect(nextButton).toHaveFocus();\\n      expect(\\n        screen.queryByTestId(\\\"assistant-onboarding-tooltip\\\"),\\n      ).not.toBeInTheDocument();\\n    } finally {\\n      nextButton.remove();\\n      jest.useRealTimers();\\n    }\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/CanvasControlsDropdown.spec.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3ea0ac8754dd3f560257dda7c5560466055a6af1fdb9b170a1a4b0296f1b0e86\",\"content\":\"import { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport CanvasControlsDropdown, {\\n  KEYBOARD_SHORTCUTS,\\n} from \\\"../CanvasControlsDropdown\\\";\\nimport {\\n  FIT_VIEW_OPTIONS,\\n  FIT_VIEW_PADDING_WITH_INSPECTION_PANEL,\\n} from \\\"../fit-view-options\\\";\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({ children, ...rest }) => <button {...rest}>{children}</button>,\\n}));\\njest.mock(\\\"@/components/ui/dropdown-menu\\\", () => ({\\n  DropdownMenu: ({ children, open, onOpenChange }) => (\\n    <div data-testid=\\\"dropdown-menu\\\" data-open={open}>\\n      <button\\n        onClick={() => onOpenChange?.(!open)}\\n        aria-expanded={open}\\n        aria-haspopup=\\\"true\\\"\\n        type=\\\"button\\\"\\n      >\\n        {children}\\n      </button>\\n    </div>\\n  ),\\n  DropdownMenuContent: ({ children }) => (\\n    <div data-testid=\\\"dropdown-content\\\">{children}</div>\\n  ),\\n  DropdownMenuTrigger: ({ children }) => (\\n    <div data-testid=\\\"dropdown-trigger\\\">{children}</div>\\n  ),\\n}));\\njest.mock(\\\"@/components/ui/separator\\\", () => ({\\n  Separator: () => <div data-testid=\\\"separator\\\" />,\\n}));\\njest.mock(\\\"../DropdownControlButton\\\", () => ({\\n  __esModule: true,\\n  default: ({ label, onClick, disabled, testId, shortcut }) => (\\n    <button\\n      type=\\\"button\\\"\\n      aria-label={label}\\n      onClick={onClick}\\n      disabled={disabled}\\n      data-testid={testId}\\n    >\\n      {label} ({shortcut})\\n    </button>\\n  ),\\n}));\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name }) => <span data-testid=\\\"icon\\\">{name}</span>,\\n}));\\n\\n// Minimize utils import surface (prevents pulling stores/darkStore via utils.ts)\\njest.mock(\\\"@/utils/utils\\\", () => ({\\n  __esModule: true,\\n  getOS: () => \\\"macos\\\",\\n  cn: (...args) => args.filter(Boolean).join(\\\" \\\"),\\n}));\\n\\nconst fitView = jest.fn();\\nconst zoomIn = jest.fn();\\nconst zoomOut = jest.fn();\\nconst zoomTo = jest.fn();\\n\\njest.mock(\\\"@xyflow/react\\\", () => ({\\n  useReactFlow: () => ({ fitView, zoomIn, zoomOut, zoomTo }),\\n  useStore: (selector) =>\\n    selector({\\n      nodesDraggable: true,\\n      nodesConnectable: true,\\n      elementsSelectable: true,\\n      transform: [0, 0, 1],\\n      minZoom: 0.2,\\n      maxZoom: 2,\\n    }),\\n}));\\n\\nconst useFlowStoreState = { inspectionPanelVisible: false };\\n\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: (selector) => selector(useFlowStoreState),\\n}));\\n\\ndescribe(\\\"CanvasControlsDropdown\\\", () => {\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n    useFlowStoreState.inspectionPanelVisible = false;\\n  });\\n\\n  it(\\\"renders current zoom percentage and toggles menu\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n    expect(screen.getByText(\\\"100%\\\"));\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown\\\"));\\n    expect(screen.getByTestId(\\\"dropdown-content\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"handles zoom in/out, fit and reset via click\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown\\\"));\\n\\n    fireEvent.click(screen.getByTestId(\\\"zoom_in\\\"));\\n    expect(zoomIn).toHaveBeenCalled();\\n\\n    fireEvent.click(screen.getByTestId(\\\"zoom_out\\\"));\\n    expect(zoomOut).toHaveBeenCalled();\\n\\n    fireEvent.click(screen.getByTestId(\\\"fit_view\\\"));\\n    expect(fitView).toHaveBeenCalled();\\n\\n    fireEvent.click(screen.getByTestId(\\\"reset_zoom\\\"));\\n    expect(zoomTo).toHaveBeenCalledWith(1);\\n  });\\n\\n  // Opening a flow fits the canvas with the same options, so a padding that\\n  // only lived here would make the initial view drift from Zoom to Fit.\\n  it(\\\"fits with the shared canvas fit options\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown\\\"));\\n\\n    fireEvent.click(screen.getByTestId(\\\"fit_view\\\"));\\n\\n    expect(fitView).toHaveBeenCalledWith(FIT_VIEW_OPTIONS);\\n  });\\n\\n  it(\\\"clears the inspection panel when it covers the canvas\\\", () => {\\n    useFlowStoreState.inspectionPanelVisible = true;\\n    render(<CanvasControlsDropdown selectedNode={{ id: \\\"node-1\\\" } as never} />);\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown\\\"));\\n\\n    fireEvent.click(screen.getByTestId(\\\"fit_view\\\"));\\n\\n    expect(fitView).toHaveBeenCalledWith({\\n      ...FIT_VIEW_OPTIONS,\\n      padding: FIT_VIEW_PADDING_WITH_INSPECTION_PANEL,\\n    });\\n  });\\n\\n  it(\\\"handles keyboard shortcuts with modifier\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    const keydown = (code: string) =>\\n      document.dispatchEvent(\\n        new KeyboardEvent(\\\"keydown\\\", { code, metaKey: true }),\\n      );\\n\\n    keydown(KEYBOARD_SHORTCUTS.ZOOM_IN.code);\\n    expect(zoomIn).toHaveBeenCalled();\\n\\n    keydown(KEYBOARD_SHORTCUTS.ZOOM_OUT.code);\\n    expect(zoomOut).toHaveBeenCalled();\\n\\n    keydown(KEYBOARD_SHORTCUTS.FIT_VIEW.code);\\n    expect(fitView).toHaveBeenCalled();\\n\\n    keydown(KEYBOARD_SHORTCUTS.RESET_ZOOM.code);\\n    expect(zoomTo).toHaveBeenCalledWith(1);\\n  });\\n\\n  it(\\\"does not zoom out when at minimum zoom\\\", () => {\\n    // Temporarily override the useStore mock for this test\\n    const originalUseStore = jest.requireMock(\\\"@xyflow/react\\\").useStore;\\n    jest.requireMock(\\\"@xyflow/react\\\").useStore = jest.fn((selector) =>\\n      selector({\\n        nodesDraggable: true,\\n        nodesConnectable: true,\\n        elementsSelectable: true,\\n        transform: [0, 0, 0.25], // At minimum zoom\\n        minZoom: 0.25,\\n        maxZoom: 2,\\n      }),\\n    );\\n\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    const keydown = (code: string) =>\\n      document.dispatchEvent(\\n        new KeyboardEvent(\\\"keydown\\\", { code, metaKey: true }),\\n      );\\n\\n    keydown(KEYBOARD_SHORTCUTS.ZOOM_OUT.code);\\n    expect(zoomOut).not.toHaveBeenCalled();\\n\\n    // Restore original mock\\n    jest.requireMock(\\\"@xyflow/react\\\").useStore = originalUseStore;\\n  });\\n\\n  it(\\\"does not zoom in when at maximum zoom\\\", () => {\\n    // Temporarily override the useStore mock for this test\\n    const originalUseStore = jest.requireMock(\\\"@xyflow/react\\\").useStore;\\n    jest.requireMock(\\\"@xyflow/react\\\").useStore = jest.fn((selector) =>\\n      selector({\\n        nodesDraggable: true,\\n        nodesConnectable: true,\\n        elementsSelectable: true,\\n        transform: [0, 0, 2], // At maximum zoom\\n        minZoom: 0.25,\\n        maxZoom: 2,\\n      }),\\n    );\\n\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    const keydown = (code: string) =>\\n      document.dispatchEvent(\\n        new KeyboardEvent(\\\"keydown\\\", { code, metaKey: true }),\\n      );\\n\\n    keydown(KEYBOARD_SHORTCUTS.ZOOM_IN.code);\\n    expect(zoomIn).not.toHaveBeenCalled();\\n\\n    // Restore original mock\\n    jest.requireMock(\\\"@xyflow/react\\\").useStore = originalUseStore;\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/CanvasControlsDropdown.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"74e1018796b28db58d9b84b7a9247182880dd42fab11be031bfc76bfbb50707c\",\"content\":\"import { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport CanvasControlsDropdown, {\\n  KEYBOARD_SHORTCUTS,\\n} from \\\"../CanvasControlsDropdown\\\";\\n\\n// Mock React Flow hooks\\nconst mockReactFlowFns = {\\n  fitView: jest.fn(),\\n  zoomIn: jest.fn(),\\n  zoomOut: jest.fn(),\\n  zoomTo: jest.fn(),\\n};\\n\\nlet mockStoreValues = {\\n  isInteractive: true,\\n  minZoomReached: false,\\n  maxZoomReached: false,\\n  zoom: 1,\\n};\\n\\njest.mock(\\\"@xyflow/react\\\", () => ({\\n  useReactFlow: () => mockReactFlowFns,\\n  useStore: (selector: (state: typeof mockStoreValues) => unknown) =>\\n    selector(mockStoreValues),\\n}));\\n\\n// Mock dependencies\\njest.mock(\\\"zustand/shallow\\\", () => ({\\n  shallow: jest.fn((fn) => fn),\\n}));\\n\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name }: { name: string }) => (\\n    <span data-testid={`icon-${name}`}>{name}</span>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({\\n    children,\\n    ...props\\n  }: React.ButtonHTMLAttributes<HTMLButtonElement>) => (\\n    <button {...props}>{children}</button>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/dropdown-menu\\\", () => ({\\n  DropdownMenu: ({\\n    children,\\n    ...props\\n  }: React.HTMLAttributes<HTMLDivElement>) => (\\n    <div data-testid=\\\"dropdown-menu\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  DropdownMenuTrigger: ({\\n    children,\\n    asChild: _asChild,\\n    ...props\\n  }: React.HTMLAttributes<HTMLDivElement> & { asChild?: boolean }) => (\\n    <div data-testid=\\\"dropdown-trigger\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  DropdownMenuContent: ({\\n    children,\\n    ...props\\n  }: React.HTMLAttributes<HTMLDivElement>) => (\\n    <div data-testid=\\\"dropdown-content\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/separator\\\", () => ({\\n  Separator: () => <div data-testid=\\\"separator\\\" />,\\n}));\\n\\njest.mock(\\\"../DropdownControlButton\\\", () => ({\\n  __esModule: true,\\n  default: ({\\n    testId,\\n    onClick,\\n    disabled,\\n    label,\\n    shortcut,\\n  }: {\\n    testId: string;\\n    onClick: () => void;\\n    disabled?: boolean;\\n    label: string;\\n    shortcut?: string;\\n  }) => (\\n    <button\\n      data-testid={testId + \\\"_dropdown\\\"}\\n      onClick={onClick}\\n      disabled={disabled}\\n      data-label={label}\\n      data-shortcut={shortcut}\\n    >\\n      {label}\\n    </button>\\n  ),\\n}));\\n\\njest.mock(\\\"../utils/canvasUtils\\\", () => ({\\n  formatZoomPercentage: jest.fn((zoom: number) => `${Math.round(zoom * 100)}%`),\\n  reactFlowSelector: jest.fn((state: unknown) => state),\\n}));\\n\\ndescribe(\\\"CanvasControlsDropdown\\\", () => {\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n\\n    // Reset mock store values\\n    mockStoreValues = {\\n      isInteractive: true,\\n      minZoomReached: false,\\n      maxZoomReached: false,\\n      zoom: 1,\\n    };\\n\\n    // Mock addEventListener and removeEventListener\\n    jest.spyOn(document, \\\"addEventListener\\\");\\n    jest.spyOn(document, \\\"removeEventListener\\\");\\n  });\\n\\n  afterEach(() => {\\n    jest.restoreAllMocks();\\n  });\\n\\n  it(\\\"renders dropdown trigger with zoom percentage\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"canvas_controls_dropdown\\\")).toBeInTheDocument();\\n    expect(screen.getByText(\\\"100%\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations\\\", async () => {\\n    const { container } = render(\\n      <CanvasControlsDropdown selectedNode={null} />,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations when zoom is at its min bound (disabled zoom out)\\\", async () => {\\n    mockStoreValues.minZoomReached = true;\\n\\n    const { container } = render(\\n      <CanvasControlsDropdown selectedNode={null} />,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"exposes an accessible name that names the control and includes the current zoom value\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"canvas_controls_dropdown\\\")).toHaveAttribute(\\n      \\\"aria-label\\\",\\n      \\\"Zoom canvas control, 100%\\\",\\n    );\\n  });\\n\\n  it(\\\"updates the accessible name's zoom value when the zoom level changes\\\", () => {\\n    mockStoreValues = {\\n      isInteractive: true,\\n      minZoomReached: false,\\n      maxZoomReached: false,\\n      zoom: 1.5,\\n    };\\n\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"canvas_controls_dropdown\\\")).toHaveAttribute(\\n      \\\"aria-label\\\",\\n      \\\"Zoom canvas control, 150%\\\",\\n    );\\n  });\\n\\n  it(\\\"renders chevron icon\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    // Should have one of the chevron icons (the actual logic depends on internal state)\\n    const chevronUp = screen.queryByTestId(\\\"icon-ChevronUp\\\");\\n    const chevronDown = screen.queryByTestId(\\\"icon-ChevronDown\\\");\\n\\n    expect(chevronUp || chevronDown).toBeInTheDocument();\\n  });\\n\\n  it(\\\"renders all control buttons with correct props\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"zoom_in_dropdown\\\")).toBeInTheDocument();\\n    expect(screen.getByTestId(\\\"zoom_out_dropdown\\\")).toBeInTheDocument();\\n    expect(screen.getByTestId(\\\"reset_zoom_dropdown\\\")).toBeInTheDocument();\\n    expect(screen.getByTestId(\\\"fit_view_dropdown\\\")).toBeInTheDocument();\\n\\n    // Check shortcuts are passed correctly\\n    expect(screen.getByTestId(\\\"zoom_in_dropdown\\\")).toHaveAttribute(\\n      \\\"data-shortcut\\\",\\n      KEYBOARD_SHORTCUTS.ZOOM_IN.key,\\n    );\\n    expect(screen.getByTestId(\\\"zoom_out_dropdown\\\")).toHaveAttribute(\\n      \\\"data-shortcut\\\",\\n      KEYBOARD_SHORTCUTS.ZOOM_OUT.key,\\n    );\\n  });\\n\\n  it(\\\"handles zoom in button click\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"zoom_in_dropdown\\\"));\\n    expect(mockReactFlowFns.zoomIn).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"handles zoom out button click\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"zoom_out_dropdown\\\"));\\n    expect(mockReactFlowFns.zoomOut).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"handles fit view button click\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"fit_view_dropdown\\\"));\\n    expect(mockReactFlowFns.fitView).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"handles reset zoom button click\\\", () => {\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"reset_zoom_dropdown\\\"));\\n    expect(mockReactFlowFns.zoomTo).toHaveBeenCalledWith(1);\\n  });\\n\\n  it(\\\"disables zoom in when maxZoomReached is true\\\", () => {\\n    mockStoreValues.maxZoomReached = true;\\n\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"zoom_in_dropdown\\\")).toBeDisabled();\\n  });\\n\\n  it(\\\"disables zoom out when minZoomReached is true\\\", () => {\\n    mockStoreValues.minZoomReached = true;\\n\\n    render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n    expect(screen.getByTestId(\\\"zoom_out_dropdown\\\")).toBeDisabled();\\n  });\\n\\n  describe(\\\"Keyboard shortcuts\\\", () => {\\n    it(\\\"sets up keyboard event listeners on mount\\\", () => {\\n      render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n      expect(document.addEventListener).toHaveBeenCalledWith(\\n        \\\"keydown\\\",\\n        expect.any(Function),\\n      );\\n    });\\n  });\\n\\n  describe(\\\"Event listener management\\\", () => {\\n    it(\\\"removes keydown event listener on unmount\\\", () => {\\n      const { unmount } = render(\\n        <CanvasControlsDropdown selectedNode={null} />,\\n      );\\n\\n      unmount();\\n\\n      expect(document.removeEventListener).toHaveBeenCalledWith(\\n        \\\"keydown\\\",\\n        expect.any(Function),\\n      );\\n    });\\n  });\\n\\n  describe(\\\"Dynamic zoom display\\\", () => {\\n    it(\\\"displays zoom percentage correctly\\\", () => {\\n      render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n      expect(screen.getByText(\\\"100%\\\")).toBeInTheDocument();\\n    });\\n\\n    it(\\\"handles fractional zoom values correctly\\\", () => {\\n      mockStoreValues.zoom = 0.75;\\n\\n      render(<CanvasControlsDropdown selectedNode={null} />);\\n\\n      expect(screen.getByText(\\\"75%\\\")).toBeInTheDocument();\\n    });\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/DropdownControlButton.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"15812604f405dec69b3139fd288559c2a60f574924277d08112456ad00baaa48\",\"content\":\"import { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport type { ReactNode } from \\\"react\\\";\\nimport {\\n  DropdownMenu,\\n  DropdownMenuContent,\\n} from \\\"@/components/ui/dropdown-menu\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport DropdownControlButton from \\\"../DropdownControlButton\\\";\\n\\n// Mock dependencies\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => {\\n  const MockIcon = ({\\n    name,\\n    className,\\n  }: {\\n    name: string;\\n    className: string;\\n  }) => <span data-testid={`icon-${name}`} className={className} />;\\n  return {\\n    __esModule: true,\\n    default: MockIcon,\\n    ForwardedIconComponent: MockIcon,\\n  };\\n});\\n\\njest.mock(\\\"@/utils/utils\\\", () => ({\\n  cn: (...args: (string | undefined | null | boolean)[]) =>\\n    args.filter(Boolean).join(\\\" \\\"),\\n}));\\n\\njest.mock(\\\"../utils/canvasUtils\\\", () => ({\\n  getModifierKey: jest.fn(() => \\\"\u2318\\\"),\\n}));\\n\\n// DropdownMenuItem/DropdownMenuCheckboxItem are real Radix menu primitives \u2014\\n// they require a real DropdownMenu/DropdownMenuContent ancestor to work, so\\n// every render here goes through that context (kept open so the content is\\n// actually mounted).\\nconst renderInMenu = (ui: ReactNode) =>\\n  render(\\n    <DropdownMenu open>\\n      <DropdownMenuContent>{ui}</DropdownMenuContent>\\n    </DropdownMenu>,\\n  );\\n\\ndescribe(\\\"DropdownControlButton\\\", () => {\\n  const defaultProps = {\\n    testId: \\\"test-button\\\",\\n    label: \\\"Test Button\\\",\\n    onClick: jest.fn(),\\n  };\\n\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations as a plain menuitem\\\", async () => {\\n    const { container } = renderInMenu(\\n      <DropdownControlButton {...defaultProps} iconName=\\\"test-icon\\\" />,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations as a menuitemcheckbox (the previously-nested toggle)\\\", async () => {\\n    const { container } = renderInMenu(\\n      <DropdownControlButton\\n        {...defaultProps}\\n        hasToogle={true}\\n        toggleValue={true}\\n      />,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"renders as a menuitem with the label\\\", () => {\\n    renderInMenu(<DropdownControlButton {...defaultProps} />);\\n\\n    const item = screen.getByTestId(\\\"test-button\\\");\\n    expect(item).toBeInTheDocument();\\n    expect(item).toHaveAttribute(\\\"role\\\", \\\"menuitem\\\");\\n    expect(screen.getByText(\\\"Test Button\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"calls onClick handler when clicked\\\", () => {\\n    const mockOnClick = jest.fn();\\n    renderInMenu(\\n      <DropdownControlButton {...defaultProps} onClick={mockOnClick} />,\\n    );\\n\\n    fireEvent.click(screen.getByTestId(\\\"test-button\\\"));\\n    expect(mockOnClick).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"renders with icon when iconName is provided\\\", () => {\\n    renderInMenu(\\n      <DropdownControlButton {...defaultProps} iconName=\\\"test-icon\\\" />,\\n    );\\n\\n    expect(screen.getByTestId(\\\"icon-test-icon\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"displays shortcut with modifier key\\\", () => {\\n    renderInMenu(<DropdownControlButton {...defaultProps} shortcut=\\\"+\\\" />);\\n\\n    expect(screen.getByText(\\\"\u2318\\\")).toBeInTheDocument();\\n    expect(screen.getByText(\\\"+\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"applies disabled state correctly\\\", () => {\\n    renderInMenu(<DropdownControlButton {...defaultProps} disabled />);\\n\\n    const item = screen.getByTestId(\\\"test-button\\\");\\n    expect(item).toHaveAttribute(\\\"aria-disabled\\\", \\\"true\\\");\\n  });\\n\\n  it(\\\"exposes an accessible name via aria-label (and title as a hover hint)\\\", () => {\\n    const tooltipText = \\\"This is a tooltip\\\";\\n    renderInMenu(\\n      <DropdownControlButton {...defaultProps} tooltipText={tooltipText} />,\\n    );\\n\\n    const item = screen.getByTestId(\\\"test-button\\\");\\n    expect(item).toHaveAttribute(\\\"aria-label\\\", tooltipText);\\n    expect(item).toHaveAttribute(\\\"title\\\", tooltipText);\\n  });\\n\\n  it(\\\"renders as a menuitemcheckbox reflecting the toggle state when hasToogle is true\\\", () => {\\n    renderInMenu(\\n      <DropdownControlButton\\n        {...defaultProps}\\n        hasToogle={true}\\n        toggleValue={true}\\n      />,\\n    );\\n\\n    const item = screen.getByTestId(\\\"test-button\\\");\\n    expect(item).toHaveAttribute(\\\"role\\\", \\\"menuitemcheckbox\\\");\\n    expect(item).toHaveAttribute(\\\"aria-checked\\\", \\\"true\\\");\\n  });\\n\\n  it(\\\"reflects an unchecked toggle state\\\", () => {\\n    renderInMenu(\\n      <DropdownControlButton\\n        {...defaultProps}\\n        hasToogle={true}\\n        toggleValue={false}\\n      />,\\n    );\\n\\n    expect(screen.getByTestId(\\\"test-button\\\")).toHaveAttribute(\\n      \\\"aria-checked\\\",\\n      \\\"false\\\",\\n    );\\n  });\\n\\n  it(\\\"calls onClick (via onCheckedChange) when the toggle item is activated\\\", () => {\\n    const mockOnClick = jest.fn();\\n    renderInMenu(\\n      <DropdownControlButton\\n        {...defaultProps}\\n        onClick={mockOnClick}\\n        hasToogle={true}\\n        toggleValue={false}\\n      />,\\n    );\\n\\n    fireEvent.click(screen.getByTestId(\\\"test-button\\\"));\\n    expect(mockOnClick).toHaveBeenCalled();\\n  });\\n\\n  it(\\\"renders without shortcut when not provided\\\", () => {\\n    renderInMenu(<DropdownControlButton {...defaultProps} />);\\n\\n    expect(screen.queryByText(\\\"\u2318\\\")).not.toBeInTheDocument();\\n  });\\n\\n  it(\\\"uses default onClick when not provided\\\", () => {\\n    renderInMenu(<DropdownControlButton testId=\\\"test-button\\\" label=\\\"Test\\\" />);\\n\\n    // Should not throw error when clicked\\n    fireEvent.click(screen.getByTestId(\\\"test-button\\\"));\\n  });\\n\\n  it(\\\"applies correct CSS classes for disabled state\\\", () => {\\n    renderInMenu(<DropdownControlButton {...defaultProps} disabled />);\\n\\n    const item = screen.getByTestId(\\\"test-button\\\");\\n    expect(item.className).toContain(\\\"cursor-not-allowed opacity-50\\\");\\n  });\\n\\n  it(\\\"renders empty label by default\\\", () => {\\n    renderInMenu(<DropdownControlButton testId=\\\"test-button\\\" />);\\n\\n    expect(screen.getByTestId(\\\"test-button\\\")).toBeInTheDocument();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/Dropdowns.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"db65a713141922d17db8a55bc225c7dc25c348fc9b7a7787a14db7591ed5aff1\",\"content\":\"import { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport { MemoryRouter, useNavigate } from \\\"react-router-dom\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport HelpDropdown from \\\"../HelpDropdown\\\";\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({\\n    children,\\n    ...props\\n  }: React.ButtonHTMLAttributes<HTMLButtonElement>) => (\\n    <button {...props}>{children}</button>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/dropdown-menu\\\", () => ({\\n  DropdownMenu: ({\\n    children,\\n    ...props\\n  }: React.HTMLAttributes<HTMLDivElement>) => (\\n    <div data-testid=\\\"dropdown-menu\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  DropdownMenuTrigger: ({\\n    children,\\n    ...props\\n  }: React.HTMLAttributes<HTMLDivElement>) => (\\n    <div data-testid=\\\"dropdown-trigger\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  DropdownMenuContent: ({\\n    children,\\n    ...props\\n  }: React.HTMLAttributes<HTMLDivElement>) => (\\n    <div data-testid=\\\"dropdown-content\\\" role=\\\"menu\\\" {...props}>\\n      {children}\\n    </div>\\n  ),\\n  DropdownMenuItem: ({\\n    children,\\n    onClick,\\n    ...props\\n  }: React.ButtonHTMLAttributes<HTMLButtonElement>) => (\\n    <button type=\\\"button\\\" role=\\\"menuitem\\\" onClick={onClick} {...props}>\\n      {children}\\n    </button>\\n  ),\\n  DropdownMenuCheckboxItem: ({\\n    children,\\n    onCheckedChange,\\n    checked,\\n    ...props\\n  }: React.ButtonHTMLAttributes<HTMLButtonElement> & {\\n    onCheckedChange?: (checked: boolean) => void;\\n    checked?: boolean;\\n  }) => (\\n    <button\\n      type=\\\"button\\\"\\n      role=\\\"menuitemcheckbox\\\"\\n      aria-checked={checked}\\n      onClick={() => onCheckedChange?.(!checked)}\\n      {...props}\\n    >\\n      {children}\\n    </button>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/separator\\\", () => ({\\n  Separator: () => <div data-testid=\\\"separator\\\" role=\\\"separator\\\" />,\\n}));\\n\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: () => <span data-testid=\\\"icon\\\" />,\\n  ForwardedIconComponent: ({ name }: { name: string }) => (\\n    <span data-testid={`icon-${name}`} />\\n  ),\\n}));\\n\\njest.mock(\\\"@/constants/constants\\\", () => ({\\n  __esModule: true,\\n  DATASTAX_DOCS_URL: \\\"https://docs.datastax.com\\\",\\n  DOCS_URL: \\\"https://docs.langflow.org\\\",\\n  DESKTOP_URL: \\\"https://desktop.langflow.org\\\",\\n}));\\n\\njest.mock(\\\"@/customization/feature-flags\\\", () => ({\\n  ENABLE_DATASTAX_LANGFLOW: false,\\n}));\\n\\njest.mock(\\\"@/utils/utils\\\", () => ({\\n  cn: (...args: unknown[]) => args.filter(Boolean).join(\\\" \\\"),\\n  getOS: () => \\\"macos\\\",\\n}));\\n\\njest.mock(\\\"react-router-dom\\\", () => {\\n  const actual = jest.requireActual(\\\"react-router-dom\\\");\\n  return {\\n    ...actual,\\n    useNavigate: jest.fn(),\\n  };\\n});\\n\\njest.mock(\\\"@/stores/darkStore\\\", () => ({\\n  useDarkStore: () => ({\\n    dark: false,\\n    setDark: jest.fn(),\\n  }),\\n}));\\n\\nconst mockFlowStoreState = {\\n  helperLineEnabled: false,\\n  setHelperLineEnabled: jest.fn(),\\n};\\n\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: (selector: (state: typeof mockFlowStoreState) => unknown) =>\\n    selector(mockFlowStoreState),\\n}));\\n\\n// Mock window.open\\nObject.defineProperty(window, \\\"open\\\", {\\n  writable: true,\\n  value: jest.fn(),\\n});\\n\\ndescribe(\\\"HelpDropdown\\\", () => {\\n  beforeEach(() => {\\n    (window.open as jest.Mock).mockClear();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations\\\", async () => {\\n    const { container } = render(\\n      <MemoryRouter>\\n        <HelpDropdown />\\n      </MemoryRouter>,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"opens docs in new tab and navigates to shortcuts\\\", () => {\\n    const mockNavigate = jest.fn();\\n    (useNavigate as unknown as jest.Mock).mockReturnValue(mockNavigate);\\n\\n    render(\\n      <MemoryRouter>\\n        <HelpDropdown />\\n      </MemoryRouter>,\\n    );\\n\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown_docs\\\"));\\n    expect(window.open).toHaveBeenCalledWith(\\n      \\\"https://docs.langflow.org\\\",\\n      \\\"_blank\\\",\\n    );\\n\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown_shortcuts\\\"));\\n    expect(mockNavigate).toHaveBeenCalledWith(\\\"/settings/shortcuts\\\");\\n\\n    fireEvent.click(\\n      screen.getByTestId(\\\"canvas_controls_dropdown_get_langflow_desktop\\\"),\\n    );\\n    expect(window.open).toHaveBeenCalledWith(\\n      \\\"https://desktop.langflow.org\\\",\\n      \\\"_blank\\\",\\n    );\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/HelpDropdown.spec.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0199c72321cce225c6b4c648e41379fa2720bc13db4ea5d06fc362cc8702c6df\",\"content\":\"import { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport { HelpDropdownView } from \\\"../HelpDropdownView\\\";\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({ children, ...rest }) => <button {...rest}>{children}</button>,\\n}));\\n\\njest.mock(\\\"@/components/ui/dropdown-menu\\\", () => ({\\n  DropdownMenu: ({ children, open, onOpenChange }) => (\\n    <div data-testid=\\\"dropdown-menu\\\" data-open={open}>\\n      <button\\n        onClick={() => onOpenChange?.(!open)}\\n        aria-expanded={open}\\n        aria-haspopup=\\\"true\\\"\\n        type=\\\"button\\\"\\n      >\\n        {children}\\n      </button>\\n    </div>\\n  ),\\n  DropdownMenuContent: ({ children }) => (\\n    <div data-testid=\\\"dropdown-content\\\">{children}</div>\\n  ),\\n  DropdownMenuTrigger: ({ children }) => (\\n    <div data-testid=\\\"dropdown-trigger\\\">{children}</div>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/ui/separator\\\", () => ({\\n  Separator: () => <div data-testid=\\\"separator\\\" />,\\n}));\\n\\njest.mock(\\\"../DropdownControlButton\\\", () => ({\\n  __esModule: true,\\n  default: ({ label, onClick, disabled, testId }) => (\\n    <button\\n      aria-label={label}\\n      onClick={onClick}\\n      disabled={disabled}\\n      data-testid={testId}\\n    >\\n      {label}\\n    </button>\\n  ),\\n}));\\n\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name }) => <span data-testid=\\\"icon\\\">{name}</span>,\\n}));\\n\\n// Minimize utils import surface (prevents pulling heavy modules)\\njest.mock(\\\"@/utils/utils\\\", () => ({\\n  __esModule: true,\\n  getOS: () => \\\"macos\\\",\\n  cn: (...args: Array<string>) => args.filter(Boolean).join(\\\" \\\"),\\n}));\\n\\ndescribe(\\\"HelpDropdownView\\\", () => {\\n  it(\\\"calls provided handlers for each menu item\\\", () => {\\n    const onOpenChange = jest.fn();\\n    const onToggleHelperLines = jest.fn();\\n    const navigateTo = jest.fn();\\n    const openLink = jest.fn();\\n    const urls = {\\n      docs: \\\"https://docs\\\",\\n      bugReport: \\\"https://bugs\\\",\\n      desktop: \\\"https://desktop\\\",\\n    };\\n\\n    render(\\n      <HelpDropdownView\\n        isOpen={true}\\n        onOpenChange={onOpenChange}\\n        helperLineEnabled={false}\\n        onToggleHelperLines={onToggleHelperLines}\\n        navigateTo={navigateTo}\\n        openLink={openLink}\\n        urls={urls}\\n      />,\\n    );\\n\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown_docs\\\"));\\n    expect(openLink).toHaveBeenCalledWith(\\\"https://docs\\\");\\n\\n    fireEvent.click(screen.getByTestId(\\\"canvas_controls_dropdown_shortcuts\\\"));\\n    expect(navigateTo).toHaveBeenCalledWith(\\\"/settings/shortcuts\\\");\\n\\n    fireEvent.click(\\n      screen.getByTestId(\\\"canvas_controls_dropdown_report_a_bug\\\"),\\n    );\\n    expect(openLink).toHaveBeenCalledWith(\\\"https://bugs\\\");\\n\\n    fireEvent.click(\\n      screen.getByTestId(\\\"canvas_controls_dropdown_get_langflow_desktop\\\"),\\n    );\\n    expect(openLink).toHaveBeenCalledWith(\\\"https://desktop\\\");\\n\\n    fireEvent.click(\\n      screen.getByTestId(\\\"canvas_controls_dropdown_enable_smart_guides\\\"),\\n    );\\n    expect(onToggleHelperLines).toHaveBeenCalled();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/canvasUtils.test.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bed00b74b00fad64ffebf0b73b32bc0851a1665c2f1f856a1664bf0f12758005\",\"content\":\"import { ReactFlowState } from \\\"@xyflow/react\\\";\\nimport {\\n  formatZoomPercentage,\\n  getModifierKey,\\n  reactFlowSelector,\\n} from \\\"../utils/canvasUtils\\\";\\n\\n// Mock the getOS utility\\njest.mock(\\\"@/utils/utils\\\", () => ({\\n  getOS: jest.fn(),\\n}));\\n\\nimport { getOS } from \\\"@/utils/utils\\\";\\n\\nconst mockGetOS = getOS as jest.MockedFunction<typeof getOS>;\\n\\ndescribe(\\\"canvasUtils\\\", () => {\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n  });\\n\\n  describe(\\\"getModifierKey\\\", () => {\\n    it(\\\"returns \u2318 for macOS\\\", () => {\\n      mockGetOS.mockReturnValue(\\\"macos\\\");\\n      expect(getModifierKey()).toBe(\\\"\u2318\\\");\\n    });\\n\\n    it(\\\"returns Ctrl for Windows\\\", () => {\\n      mockGetOS.mockReturnValue(\\\"windows\\\");\\n      expect(getModifierKey()).toBe(\\\"Ctrl\\\");\\n    });\\n\\n    it(\\\"returns Ctrl for Linux\\\", () => {\\n      mockGetOS.mockReturnValue(\\\"linux\\\");\\n      expect(getModifierKey()).toBe(\\\"Ctrl\\\");\\n    });\\n\\n    it(\\\"returns Ctrl for unknown OS\\\", () => {\\n      mockGetOS.mockReturnValue(\\\"unknown\\\");\\n      expect(getModifierKey()).toBe(\\\"Ctrl\\\");\\n    });\\n  });\\n\\n  describe(\\\"formatZoomPercentage\\\", () => {\\n    it(\\\"formats zoom level 1 as 100%\\\", () => {\\n      expect(formatZoomPercentage(1)).toBe(\\\"100%\\\");\\n    });\\n\\n    it(\\\"formats zoom level 0.5 as 50%\\\", () => {\\n      expect(formatZoomPercentage(0.5)).toBe(\\\"50%\\\");\\n    });\\n\\n    it(\\\"formats zoom level 1.5 as 150%\\\", () => {\\n      expect(formatZoomPercentage(1.5)).toBe(\\\"150%\\\");\\n    });\\n\\n    it(\\\"formats zoom level 0.25 as 25%\\\", () => {\\n      expect(formatZoomPercentage(0.25)).toBe(\\\"25%\\\");\\n    });\\n\\n    it(\\\"formats zoom level 2.789 as 279%\\\", () => {\\n      expect(formatZoomPercentage(2.789)).toBe(\\\"279%\\\");\\n    });\\n\\n    it(\\\"rounds decimal values correctly\\\", () => {\\n      expect(formatZoomPercentage(0.333)).toBe(\\\"33%\\\");\\n      expect(formatZoomPercentage(0.666)).toBe(\\\"67%\\\");\\n      expect(formatZoomPercentage(1.234)).toBe(\\\"123%\\\");\\n    });\\n\\n    it(\\\"handles zero zoom level\\\", () => {\\n      expect(formatZoomPercentage(0)).toBe(\\\"0%\\\");\\n    });\\n\\n    it(\\\"handles very small zoom levels\\\", () => {\\n      expect(formatZoomPercentage(0.001)).toBe(\\\"0%\\\");\\n      expect(formatZoomPercentage(0.005)).toBe(\\\"1%\\\");\\n    });\\n\\n    it(\\\"handles very large zoom levels\\\", () => {\\n      expect(formatZoomPercentage(10)).toBe(\\\"1000%\\\");\\n      expect(formatZoomPercentage(50.5)).toBe(\\\"5050%\\\");\\n    });\\n  });\\n\\n  describe(\\\"reactFlowSelector\\\", () => {\\n    const createMockReactFlowState = (\\n      overrides: Partial<ReactFlowState> = {},\\n    ): ReactFlowState =>\\n      ({\\n        nodesDraggable: true,\\n        nodesConnectable: true,\\n        elementsSelectable: true,\\n        transform: [0, 0, 1], // x, y, zoom\\n        minZoom: 0.1,\\n        maxZoom: 5,\\n        ...overrides,\\n      }) as ReactFlowState;\\n\\n    it(\\\"returns correct isInteractive when all interaction modes are enabled\\\", () => {\\n      const state = createMockReactFlowState({\\n        nodesDraggable: true,\\n        nodesConnectable: true,\\n        elementsSelectable: true,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.isInteractive).toBe(true);\\n    });\\n\\n    it(\\\"returns correct isInteractive when only nodesDraggable is enabled\\\", () => {\\n      const state = createMockReactFlowState({\\n        nodesDraggable: true,\\n        nodesConnectable: false,\\n        elementsSelectable: false,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.isInteractive).toBe(true);\\n    });\\n\\n    it(\\\"returns correct isInteractive when only nodesConnectable is enabled\\\", () => {\\n      const state = createMockReactFlowState({\\n        nodesDraggable: false,\\n        nodesConnectable: true,\\n        elementsSelectable: false,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.isInteractive).toBe(true);\\n    });\\n\\n    it(\\\"returns correct isInteractive when only elementsSelectable is enabled\\\", () => {\\n      const state = createMockReactFlowState({\\n        nodesDraggable: false,\\n        nodesConnectable: false,\\n        elementsSelectable: true,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.isInteractive).toBe(true);\\n    });\\n\\n    it(\\\"returns false for isInteractive when all interaction modes are disabled\\\", () => {\\n      const state = createMockReactFlowState({\\n        nodesDraggable: false,\\n        nodesConnectable: false,\\n        elementsSelectable: false,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.isInteractive).toBe(false);\\n    });\\n\\n    it(\\\"returns correct minZoomReached when zoom is at minimum\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 0.1], // zoom at minZoom\\n        minZoom: 0.1,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.minZoomReached).toBe(true);\\n    });\\n\\n    it(\\\"returns correct minZoomReached when zoom is below minimum\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 0.05], // zoom below minZoom\\n        minZoom: 0.1,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.minZoomReached).toBe(true);\\n    });\\n\\n    it(\\\"returns correct minZoomReached when zoom is above minimum\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 0.5], // zoom above minZoom\\n        minZoom: 0.1,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.minZoomReached).toBe(false);\\n    });\\n\\n    it(\\\"returns correct maxZoomReached when zoom is at maximum\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 5], // zoom at maxZoom\\n        maxZoom: 5,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.maxZoomReached).toBe(true);\\n    });\\n\\n    it(\\\"returns correct maxZoomReached when zoom is above maximum\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 10], // zoom above maxZoom\\n        maxZoom: 5,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.maxZoomReached).toBe(true);\\n    });\\n\\n    it(\\\"returns correct maxZoomReached when zoom is below maximum\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 2], // zoom below maxZoom\\n        maxZoom: 5,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.maxZoomReached).toBe(false);\\n    });\\n\\n    it(\\\"returns correct zoom level from transform\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [100, 200, 1.5], // x, y, zoom\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.zoom).toBe(1.5);\\n    });\\n\\n    it(\\\"handles edge case where zoom equals both min and max\\\", () => {\\n      const state = createMockReactFlowState({\\n        transform: [0, 0, 1],\\n        minZoom: 1,\\n        maxZoom: 1,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n      expect(result.minZoomReached).toBe(true);\\n      expect(result.maxZoomReached).toBe(true);\\n      expect(result.zoom).toBe(1);\\n    });\\n\\n    it(\\\"returns complete selector object with all properties\\\", () => {\\n      const state = createMockReactFlowState({\\n        nodesDraggable: true,\\n        nodesConnectable: false,\\n        elementsSelectable: true,\\n        transform: [0, 0, 2],\\n        minZoom: 0.5,\\n        maxZoom: 4,\\n      });\\n\\n      const result = reactFlowSelector(state);\\n\\n      expect(result).toEqual({\\n        isInteractive: true,\\n        minZoomReached: false,\\n        maxZoomReached: false,\\n        zoom: 2,\\n      });\\n    });\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/__tests__/useMinimizeAllAndAlign.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"adb724db5b8286ef3b17e5da56434d797ec4dc046cb8d295f6dfd44f8fe683e8\",\"content\":\"import { act, renderHook } from \\\"@testing-library/react\\\";\\nimport useMinimizeAllAndAlign from \\\"../hooks/use-minimize-all-and-align\\\";\\n\\nconst mockUpdateNodeInternals = jest.fn();\\njest.mock(\\\"@xyflow/react\\\", () => ({\\n  useUpdateNodeInternals: () => mockUpdateNodeInternals,\\n}));\\n\\ntype MockNode = {\\n  id: string;\\n  type: string;\\n  position: { x: number; y: number };\\n  data: { id: string; showNode?: boolean };\\n};\\n\\nconst mockTakeSnapshot = jest.fn();\\njest.mock(\\\"@/stores/flowsManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: (selector: (state: unknown) => unknown) =>\\n    selector({ takeSnapshot: mockTakeSnapshot }),\\n}));\\n\\nlet mockNodes: MockNode[] = [];\\nconst mockSetNodes = jest.fn();\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: (selector: (state: unknown) => unknown) =>\\n    selector({ nodes: mockNodes, setNodes: mockSetNodes }),\\n}));\\n\\nconst mockGetLayoutedNodes = jest.fn();\\njest.mock(\\\"@/utils/layoutUtils\\\", () => ({\\n  getLayoutedNodes: (...args: unknown[]) => mockGetLayoutedNodes(...args),\\n}));\\n\\nconst genericNode = (\\n  id: string,\\n  showNode?: boolean,\\n  position = { x: 10, y: 20 },\\n) => ({\\n  id,\\n  type: \\\"genericNode\\\",\\n  position,\\n  data: { id, showNode },\\n});\\n\\nconst noteNode = (id: string) => ({\\n  id,\\n  type: \\\"noteNode\\\",\\n  position: { x: 0, y: 0 },\\n  data: { id },\\n});\\n\\ndescribe(\\\"useMinimizeAllAndAlign (LE-1810 T9 \u2014 minimize only, no re-layout)\\\", () => {\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n  });\\n\\n  it(\\\"reports allMinimized=false when any generic node is expanded\\\", () => {\\n    mockNodes = [genericNode(\\\"a\\\", false), genericNode(\\\"b\\\", true)];\\n    const { result } = renderHook(() => useMinimizeAllAndAlign());\\n\\n    expect(result.current.allMinimized).toBe(false);\\n    expect(result.current.hasGenericNodes).toBe(true);\\n  });\\n\\n  it(\\\"reports allMinimized=true when every generic node is collapsed\\\", () => {\\n    mockNodes = [\\n      genericNode(\\\"a\\\", false),\\n      genericNode(\\\"b\\\", false),\\n      noteNode(\\\"n\\\"),\\n    ];\\n    const { result } = renderHook(() => useMinimizeAllAndAlign());\\n\\n    expect(result.current.allMinimized).toBe(true);\\n  });\\n\\n  it(\\\"minimizes every generic node keeping positions \u2014 no layout, no viewport change\\\", () => {\\n    mockNodes = [\\n      genericNode(\\\"a\\\", true, { x: 1, y: 2 }),\\n      genericNode(\\\"b\\\", undefined, { x: 3, y: 4 }),\\n      noteNode(\\\"n\\\"),\\n    ];\\n    const { result } = renderHook(() => useMinimizeAllAndAlign());\\n\\n    act(() => {\\n      result.current.toggleMinimizeAllAndAlign();\\n    });\\n\\n    expect(mockTakeSnapshot).toHaveBeenCalled();\\n    // Reporter call on LE-1810: minimize-all must ONLY minimize.\\n    expect(mockGetLayoutedNodes).not.toHaveBeenCalled();\\n\\n    const [updated] = mockSetNodes.mock.calls[0];\\n    const generics = updated.filter(\\n      (node: MockNode) => node.type === \\\"genericNode\\\",\\n    );\\n    expect(\\n      generics.every((node: MockNode) => node.data.showNode === false),\\n    ).toBe(true);\\n    expect(generics.map((node: MockNode) => node.position)).toEqual([\\n      { x: 1, y: 2 },\\n      { x: 3, y: 4 },\\n    ]);\\n    const note = updated.find((node: MockNode) => node.type === \\\"noteNode\\\");\\n    expect(note.data.showNode).toBeUndefined();\\n    expect(mockUpdateNodeInternals).toHaveBeenCalledWith([\\\"a\\\", \\\"b\\\"]);\\n  });\\n\\n  it(\\\"expands every generic node keeping positions\\\", () => {\\n    mockNodes = [\\n      genericNode(\\\"a\\\", false, { x: 5, y: 6 }),\\n      genericNode(\\\"b\\\", false, { x: 7, y: 8 }),\\n    ];\\n    const { result } = renderHook(() => useMinimizeAllAndAlign());\\n\\n    act(() => {\\n      result.current.toggleMinimizeAllAndAlign();\\n    });\\n\\n    expect(mockTakeSnapshot).toHaveBeenCalled();\\n    expect(mockGetLayoutedNodes).not.toHaveBeenCalled();\\n\\n    const [updated] = mockSetNodes.mock.calls[0];\\n    expect(updated.every((node: MockNode) => node.data.showNode === true)).toBe(\\n      true,\\n    );\\n    expect(updated.map((node: MockNode) => node.position)).toEqual([\\n      { x: 5, y: 6 },\\n      { x: 7, y: 8 },\\n    ]);\\n    expect(mockUpdateNodeInternals).toHaveBeenCalledWith([\\\"a\\\", \\\"b\\\"]);\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/fit-view-options.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d80673b18b52f62e8a403dadd93295cf53a8620c3b07d12268194c4714e50885\",\"content\":\"import type { FitViewOptions } from \\\"@xyflow/react\\\";\\n\\nexport const MIN_ZOOM = 0.25;\\nexport const MAX_ZOOM = 2;\\n\\n/**\\n * Padding kept around the graph when fitting the canvas. The top allowance\\n * clears the floating toolbar; the sides are symmetric unless the inspection\\n * panel is open over the right edge.\\n */\\nexport const FIT_VIEW_PADDING = {\\n  left: \\\"20px\\\",\\n  right: \\\"20px\\\",\\n  top: \\\"80px\\\",\\n} as const;\\n\\n/** Padding to use while the inspection panel covers the right of the canvas. */\\nexport const FIT_VIEW_PADDING_WITH_INSPECTION_PANEL = {\\n  ...FIT_VIEW_PADDING,\\n  right: \\\"340px\\\",\\n} as const;\\n\\n/**\\n * Single source of truth for how the canvas fits the graph, shared by the\\n * initial fit and the Zoom to Fit control so opening a flow lands on exactly\\n * the viewport the shortcut produces.\\n */\\nexport const FIT_VIEW_OPTIONS: FitViewOptions = {\\n  minZoom: MIN_ZOOM,\\n  maxZoom: MAX_ZOOM,\\n  padding: FIT_VIEW_PADDING,\\n};\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/hooks/use-minimize-all-and-align.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"34d30701f28187a5ef95050672ba6e9c4ecb5a225b7096550458422719d27021\",\"content\":\"import { useUpdateNodeInternals } from \\\"@xyflow/react\\\";\\nimport { useCallback, useMemo } from \\\"react\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport type { AllNodeType } from \\\"@/types/flow\\\";\\n\\nexport default function useMinimizeAllAndAlign() {\\n  const nodes = useFlowStore((state) => state.nodes);\\n  const setNodes = useFlowStore((state) => state.setNodes);\\n  const takeSnapshot = useFlowsManagerStore((state) => state.takeSnapshot);\\n  const updateNodeInternals = useUpdateNodeInternals();\\n\\n  const genericNodeIds = useMemo(\\n    () =>\\n      nodes\\n        .filter((node) => node.type === \\\"genericNode\\\")\\n        .map((node) => node.id),\\n    [nodes],\\n  );\\n\\n  const allMinimized = useMemo(\\n    () =>\\n      genericNodeIds.length > 0 &&\\n      nodes\\n        .filter((node) => node.type === \\\"genericNode\\\")\\n        .every((node) => node.data?.showNode === false),\\n    [nodes, genericNodeIds],\\n  );\\n\\n  // LE-1810 review round (reporter): minimize-all ONLY toggles showNode \u2014\\n  // no re-layout, no viewport change. Components keep their positions.\\n  const setAllShowNode = useCallback(\\n    (showNode: boolean) => {\\n      takeSnapshot();\\n      setNodes(\\n        nodes.map((node) =>\\n          node.type === \\\"genericNode\\\"\\n            ? ({\\n                ...node,\\n                data: { ...node.data, showNode },\\n              } as AllNodeType)\\n            : node,\\n        ),\\n      );\\n      updateNodeInternals(genericNodeIds);\\n    },\\n    [nodes, genericNodeIds, setNodes, takeSnapshot, updateNodeInternals],\\n  );\\n\\n  const toggleMinimizeAllAndAlign = useCallback(() => {\\n    setAllShowNode(allMinimized);\\n  }, [allMinimized, setAllShowNode]);\\n\\n  return {\\n    allMinimized,\\n    hasGenericNodes: genericNodeIds.length > 0,\\n    toggleMinimizeAllAndAlign,\\n  };\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/utils/canvasUtils.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1b3842df2618a917241e82f7a05d95c1b31302ce9d36836710c5896051591559\",\"content\":\"import { ReactFlowState } from \\\"@xyflow/react\\\";\\nimport { getOS } from \\\"@/utils/utils\\\";\\n\\nexport const getModifierKey = (): string => {\\n  const os = getOS();\\n  return os === \\\"macos\\\" ? \\\"\u2318\\\" : \\\"Ctrl\\\";\\n};\\n\\nexport const formatZoomPercentage = (zoom: number): string =>\\n  `${Math.round(zoom * 100)}%`;\\n\\nexport const reactFlowSelector = (s: ReactFlowState) => ({\\n  isInteractive: s.nodesDraggable || s.nodesConnectable || s.elementsSelectable,\\n  minZoomReached: s.transform[2] <= s.minZoom,\\n  maxZoomReached: s.transform[2] >= s.maxZoom,\\n  zoom: s.transform[2],\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/canvasControlsComponent/utils/use-dismiss-on-tab-boundary.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bff3859c0f332a5b96e8f45a50cca9b803a00a370c7af241e090d1928c2a1976\",\"content\":\"import { type KeyboardEvent, useCallback, useRef } from \\\"react\\\";\\nimport { tabbable } from \\\"tabbable\\\";\\n\\nconst getTabbableElements = (root: HTMLElement) =>\\n  tabbable(root, {\\n    displayCheck: process.env.NODE_ENV === \\\"test\\\" ? \\\"none\\\" : \\\"full\\\",\\n  }).filter(\\n    (element) =>\\n      !element.hasAttribute(\\\"data-radix-focus-guard\\\") &&\\n      !element.closest(\\\"[inert]\\\") &&\\n      !element.closest('[aria-hidden=\\\"true\\\"]'),\\n  );\\n\\nexport function useDismissOnTabBoundary<TElement extends HTMLElement>(\\n  onDismiss: () => void,\\n) {\\n  const containerRef = useRef<TElement>(null);\\n\\n  const handleTabBoundary = useCallback(\\n    (event: KeyboardEvent<TElement>) => {\\n      if (event.key !== \\\"Tab\\\") return;\\n\\n      const container = containerRef.current;\\n      const activeElement = document.activeElement as HTMLElement | null;\\n      if (!container || !activeElement || !container.contains(activeElement)) {\\n        return;\\n      }\\n\\n      const containerTabbables = getTabbableElements(container);\\n      const firstContainerTabbable = containerTabbables[0];\\n      const lastContainerTabbable = containerTabbables.at(-1);\\n      const isLeavingBackward =\\n        event.shiftKey && activeElement === firstContainerTabbable;\\n      const isLeavingForward =\\n        !event.shiftKey && activeElement === lastContainerTabbable;\\n\\n      if (!isLeavingBackward && !isLeavingForward) return;\\n\\n      const documentTabbables = getTabbableElements(document.body);\\n      const activeIndex = documentTabbables.indexOf(activeElement);\\n      const candidates = event.shiftKey\\n        ? documentTabbables.slice(0, activeIndex).reverse()\\n        : documentTabbables.slice(activeIndex + 1);\\n      const nextFocusable = candidates.find(\\n        (element) => !container.contains(element),\\n      );\\n\\n      event.preventDefault();\\n      onDismiss();\\n      nextFocusable?.focus();\\n    },\\n    [onDismiss],\\n  );\\n\\n  return { containerRef, handleTabBoundary };\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/cardComponent/components/dragCardComponent/index.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"40c542b435b52a435967c0c9a31ac7c7555d30260f2a434f68356e1e0be0f2f8\",\"content\":\"import type { FlowType } from \\\"@/types/flow\\\";\\nimport { cn } from \\\"../../../../../utils/utils\\\";\\nimport ForwardedIconComponent from \\\"../../../../common/genericIconComponent\\\";\\nimport { Card, CardHeader, CardTitle } from \\\"../../../../ui/card\\\";\\n\\nexport default function DragCardComponent({ data }: { data: FlowType }) {\\n  return (\\n    <>\\n      <Card\\n        draggable\\n        //TODO check color schema\\n        className={cn(\\n          \\\"group relative flex flex-col justify-between overflow-hidden transition-all hover:bg-muted/50 hover:shadow-md hover:dark:bg-[#ffffff10]\\\",\\n        )}\\n      >\\n        <div>\\n          <CardHeader>\\n            <div>\\n              <CardTitle className=\\\"flex w-full items-start justify-between gap-3 text-xl\\\">\\n                <ForwardedIconComponent\\n                  className={cn(\\n                    \\\"visible flex-shrink-0\\\",\\n                    data.is_component\\n                      ? \\\"mx-0.5 h-6 w-6 text-component-icon\\\"\\n                      : \\\"h-7 w-7 flex-shrink-0 text-flow-icon\\\",\\n                  )}\\n                  name={data.is_component ? \\\"ToyBrick\\\" : \\\"Group\\\"}\\n                />\\n\\n                <div className=\\\"w-full truncate pr-3\\\">{data.name}</div>\\n              </CardTitle>\\n            </div>\\n          </CardHeader>\\n        </div>\\n      </Card>\\n    </>\\n  );\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/cardComponent/hooks/use-on-drag-start.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4a199b0592111a890094d7a789a7775b6f00e312bdfdef78fdc8a86f6f856360\",\"content\":\"import { useCallback } from \\\"react\\\";\\nimport { createRoot } from \\\"react-dom/client\\\";\\nimport type { FlowType } from \\\"@/types/flow\\\";\\nimport useFlowsManagerStore from \\\"../../../../stores/flowsManagerStore\\\";\\nimport DragCardComponent from \\\"../components/dragCardComponent\\\";\\n\\nconst useDragStart = (data: FlowType) => {\\n  const getFlowById = useFlowsManagerStore((state) => state.getFlowById);\\n\\n  const onDragStart = useCallback(\\n    (event) => {\\n      const image = <DragCardComponent data={data} />; // Replace with whatever you want here\\n\\n      const ghost = document.createElement(\\\"div\\\");\\n      ghost.style.transform = \\\"translate(-10000px, -10000px)\\\";\\n      ghost.style.position = \\\"absolute\\\";\\n      document.body.appendChild(ghost);\\n      event.dataTransfer.setDragImage(ghost, 0, 0);\\n\\n      const root = createRoot(ghost);\\n      root.render(image);\\n\\n      const flow = getFlowById(data.id);\\n      if (flow) {\\n        event.dataTransfer.setData(\\\"flow\\\", JSON.stringify(data));\\n      }\\n    },\\n    [data],\\n  );\\n\\n  return { onDragStart };\\n};\\n\\nexport default useDragStart;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/editFlowSettingsComponent/__tests__/EditFlowSettings.spec.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cc805e329f688a33c5c39df5666d887f5aaf8e84e35d9f7a6b3c23601a07cd50\",\"content\":\"import { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport EditFlowSettings from \\\"../index\\\";\\n\\njest.mock(\\\"@/components/ui/input\\\", () => ({\\n  Input: ({ ...props }) => <input {...props} />,\\n}));\\njest.mock(\\\"@/components/ui/textarea\\\", () => ({\\n  Textarea: ({ ...props }) => <textarea {...props} />,\\n}));\\njest.mock(\\\"@/components/ui/switch\\\", () => ({\\n  Switch: ({ checked, onCheckedChange, ...rest }) => (\\n    <input\\n      role=\\\"switch\\\"\\n      aria-checked={!!checked}\\n      type=\\\"checkbox\\\"\\n      checked={!!checked}\\n      onChange={(e) => onCheckedChange?.(e.target.checked)}\\n      {...rest}\\n    />\\n  ),\\n}));\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: () => <span />,\\n}));\\n// Mock Radix Form to avoid context requirement\\njest.mock(\\\"@radix-ui/react-form\\\", () => ({\\n  __esModule: true,\\n  Field: ({ children }) => <div>{children}</div>,\\n  Label: ({ children }) => <label>{children}</label>,\\n  Control: ({ children }) => <>{children}</>,\\n  Message: ({ children }) => <div>{children}</div>,\\n  Root: ({ children }) => <form>{children}</form>,\\n}));\\n\\n// Prevent importing utils that pull darkStore via side-effects\\njest.mock(\\\"@/utils/utils\\\", () => ({\\n  __esModule: true,\\n  cn: (...args) => args.filter(Boolean).join(\\\" \\\"),\\n}));\\n\\ndescribe(\\\"EditFlowSettings\\\", () => {\\n  it(\\\"validates name and shows messages\\\", () => {\\n    const setName = jest.fn();\\n    render(\\n      <EditFlowSettings\\n        name=\\\"\\\"\\n        description=\\\"\\\"\\n        invalidNameList={[\\\"Taken\\\"]}\\n        setName={setName}\\n        setDescription={jest.fn()}\\n      />,\\n    );\\n\\n    const nameInput = screen.getByTestId(\\\"input-flow-name\\\");\\n    fireEvent.change(nameInput, { target: { value: \\\"T\\\" } });\\n    expect(setName).toHaveBeenCalledWith(\\\"T\\\");\\n\\n    fireEvent.change(nameInput, { target: { value: \\\"\\\" } });\\n    expect(screen.getByText(/Please enter a name/)).toBeInTheDocument();\\n\\n    fireEvent.change(nameInput, { target: { value: \\\"Taken\\\" } });\\n    expect(screen.getAllByText(/already exists/).length).toBeGreaterThan(0);\\n  });\\n\\n  it(\\\"submits with Enter in description without Shift\\\", () => {\\n    const submitForm = jest.fn();\\n    render(\\n      <EditFlowSettings\\n        name=\\\"Flow\\\"\\n        description=\\\"Desc\\\"\\n        submitForm={submitForm}\\n        setName={jest.fn()}\\n        setDescription={jest.fn()}\\n      />,\\n    );\\n\\n    const desc = screen.getByTestId(\\\"input-flow-description\\\");\\n    fireEvent.keyDown(desc, { key: \\\"Enter\\\", shiftKey: false });\\n    expect(submitForm).toHaveBeenCalled();\\n  });\\n\\n  it(\\\"toggles lock switch\\\", () => {\\n    const setLocked = jest.fn();\\n    render(\\n      <EditFlowSettings\\n        name=\\\"Flow\\\"\\n        description=\\\"Desc\\\"\\n        locked={false}\\n        setLocked={setLocked}\\n        setName={jest.fn()}\\n        setDescription={jest.fn()}\\n      />,\\n    );\\n    const sw = screen.getByTestId(\\\"lock-flow-switch\\\");\\n    fireEvent.click(sw);\\n    expect(setLocked).toHaveBeenCalledWith(true);\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/editFlowSettingsComponent/__tests__/editFlowSettingsComponent.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c6edba8205a3a77c8a9312a050b9babf251ec165847530dbe9a7d855625215da\",\"content\":\"import * as Form from \\\"@radix-ui/react-form\\\";\\nimport { render, screen } from \\\"@testing-library/react\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport { EditFlowSettings } from \\\"../index\\\";\\n\\nconst renderWithForm = (ui: React.ReactElement) =>\\n  render(<Form.Root>{ui}</Form.Root>);\\n\\ndescribe(\\\"EditFlowSettings lock switch\\\", () => {\\n  const defaultProps = {\\n    name: \\\"My Flow\\\",\\n    description: \\\"\\\",\\n    setName: jest.fn(),\\n    setDescription: jest.fn(),\\n    setLocked: jest.fn(),\\n  };\\n\\n  it(\\\"should_have_no_axe_violations\\\", async () => {\\n    const { container } = renderWithForm(\\n      <EditFlowSettings {...defaultProps} />,\\n    );\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"exposes a descriptive accessible name on the lock switch\\\", () => {\\n    renderWithForm(<EditFlowSettings {...defaultProps} />);\\n\\n    expect(\\n      screen.getByRole(\\\"switch\\\", {\\n        name: \\\"Lock flow switch\\\",\\n      }),\\n    ).toBeInTheDocument();\\n  });\\n\\n  it(\\\"reflects the locked/unlocked state on the correctly named switch\\\", () => {\\n    renderWithForm(<EditFlowSettings {...defaultProps} locked={true} />);\\n\\n    expect(\\n      screen.getByRole(\\\"switch\\\", {\\n        name: \\\"Lock flow switch\\\",\\n      }),\\n    ).toHaveAttribute(\\\"aria-checked\\\", \\\"true\\\");\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/editFlowSettingsComponent/index.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"290ace2607d55e81f867a1432f3b12bd2748b8e19db28653c025e36458fe1597\",\"content\":\"import * as Form from \\\"@radix-ui/react-form\\\";\\nimport type React from \\\"react\\\";\\nimport { useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport { Switch } from \\\"@/components/ui/switch\\\";\\nimport type { InputProps } from \\\"../../../types/components\\\";\\nimport { cn } from \\\"../../../utils/utils\\\";\\nimport { Input } from \\\"../../ui/input\\\";\\nimport { Textarea } from \\\"../../ui/textarea\\\";\\n\\nexport const EditFlowSettings: React.FC<\\n  InputProps & {\\n    submitForm?: () => void;\\n    locked?: boolean;\\n    setLocked?: (v: boolean) => void;\\n    readOnly?: boolean;\\n  }\\n> = ({\\n  name,\\n  invalidNameList = [],\\n  description,\\n  maxLength = 50,\\n  descriptionMaxLength = 250,\\n  minLength = 1,\\n  setName,\\n  setDescription,\\n  submitForm,\\n  locked = false,\\n  setLocked,\\n  readOnly = false,\\n}: InputProps & {\\n  submitForm?: () => void;\\n  locked?: boolean;\\n  setLocked?: (v: boolean) => void;\\n  readOnly?: boolean;\\n}): JSX.Element => {\\n  const { t } = useTranslation();\\n  const [isMaxLength, setIsMaxLength] = useState(false);\\n  const [isMaxDescriptionLength, setIsMaxDescriptionLength] = useState(false);\\n  const [isMinLength, setIsMinLength] = useState(false);\\n  const [isInvalidName, setIsInvalidName] = useState(false);\\n\\n  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {\\n    const { value } = event.target;\\n    if (value.length >= maxLength) {\\n      setIsMaxLength(true);\\n    } else {\\n      setIsMaxLength(false);\\n    }\\n    if (value.length < minLength) {\\n      setIsMinLength(true);\\n    } else {\\n      setIsMinLength(false);\\n    }\\n    let invalid = false;\\n    for (let i = 0; i < invalidNameList!.length; i++) {\\n      if (value === invalidNameList![i]) {\\n        invalid = true;\\n        break;\\n      }\\n      invalid = false;\\n    }\\n    setIsInvalidName(invalid);\\n    setName!(value);\\n    if (value.length === 0) {\\n      setIsMinLength(true);\\n    }\\n  };\\n\\n  const handleDescriptionChange = (\\n    event: React.ChangeEvent<HTMLTextAreaElement>,\\n  ) => {\\n    const { value } = event.target;\\n    if (value.length >= descriptionMaxLength) {\\n      setIsMaxDescriptionLength(true);\\n    } else {\\n      setIsMaxDescriptionLength(false);\\n    }\\n    setDescription!(value);\\n  };\\n\\n  const handleDescriptionKeyDown = (\\n    event: React.KeyboardEvent<HTMLTextAreaElement>,\\n  ) => {\\n    if (event.key === \\\"Enter\\\" && !event.shiftKey) {\\n      event.preventDefault();\\n      if (submitForm) submitForm();\\n    }\\n    // else allow default (newline)\\n  };\\n\\n  const handleFocus = (event) => event.target.select();\\n\\n  return (\\n    <>\\n      <Form.Field name=\\\"name\\\">\\n        <div className=\\\"edit-flow-arrangement\\\">\\n          <Form.Label className=\\\"text-mmd font-medium\\\">\\n            {t(\\\"flow.nameLabel\\\")}\\n            {setName ? \\\"\\\" : \\\":\\\"}\\n          </Form.Label>\\n          {isMaxLength && (\\n            <span className=\\\"edit-flow-span\\\">\\n              {t(\\\"flow.characterLimitReached\\\")}\\n            </span>\\n          )}\\n          {isMinLength && (\\n            <span className=\\\"edit-flow-span\\\">\\n              {t(\\\"flow.minimumCharacters\\\", { count: minLength })}\\n            </span>\\n          )}\\n          {isInvalidName && (\\n            <span className=\\\"edit-flow-span\\\">\\n              {t(\\\"flow.nameAlreadyExists\\\")}\\n            </span>\\n          )}\\n        </div>\\n        {setName ? (\\n          <Form.Control asChild>\\n            <Input\\n              className=\\\"nopan nodelete nodrag noflow mt-2 font-normal\\\"\\n              onChange={handleNameChange}\\n              type=\\\"text\\\"\\n              name=\\\"name\\\"\\n              value={name ?? \\\"\\\"}\\n              placeholder={t(\\\"flow.namePlaceholder\\\")}\\n              id=\\\"name\\\"\\n              maxLength={maxLength}\\n              minLength={minLength}\\n              required={true}\\n              onDoubleClickCapture={handleFocus}\\n              data-testid=\\\"input-flow-name\\\"\\n              autoFocus\\n              disabled={locked || readOnly}\\n            />\\n          </Form.Control>\\n        ) : (\\n          <span className=\\\"font-normal text-muted-foreground word-break-break-word\\\">\\n            {name}\\n          </span>\\n        )}\\n        <Form.Message match=\\\"valueMissing\\\" className=\\\"field-invalid\\\">\\n          {t(\\\"flow.pleaseEnterName\\\")}\\n        </Form.Message>\\n        <Form.Message\\n          match={(value) => !!(value && invalidNameList.includes(value))}\\n          className=\\\"field-invalid\\\"\\n        >\\n          {t(\\\"flow.nameAlreadyExists\\\")}\\n        </Form.Message>\\n      </Form.Field>\\n      <Form.Field name=\\\"description\\\">\\n        <div className=\\\"edit-flow-arrangement mt-2\\\">\\n          <Form.Label className=\\\"text-mmd font-medium\\\">\\n            {t(\\\"flow.descriptionLabel\\\")}\\n            {setDescription ? \\\"\\\" : \\\":\\\"}\\n          </Form.Label>\\n          {isMaxDescriptionLength && (\\n            <span className=\\\"edit-flow-span\\\">\\n              {t(\\\"flow.characterLimitReached\\\")}\\n            </span>\\n          )}\\n        </div>\\n        {setDescription ? (\\n          <Form.Control asChild>\\n            <Textarea\\n              name=\\\"description\\\"\\n              id=\\\"description\\\"\\n              onChange={handleDescriptionChange}\\n              value={description!}\\n              placeholder={t(\\\"flow.descriptionPlaceholder\\\")}\\n              data-testid=\\\"input-flow-description\\\"\\n              className=\\\"mt-2 max-h-[250px] resize-none font-normal\\\"\\n              rows={5}\\n              maxLength={descriptionMaxLength}\\n              onDoubleClickCapture={handleFocus}\\n              onKeyDown={handleDescriptionKeyDown}\\n              disabled={locked || readOnly}\\n            />\\n          </Form.Control>\\n        ) : (\\n          <div\\n            className={cn(\\n              \\\"max-h-[250px] overflow-auto pt-2 font-normal text-muted-foreground word-break-break-word\\\",\\n              description === \\\"\\\" ? \\\"font-light italic\\\" : \\\"\\\",\\n            )}\\n          >\\n            {description === \\\"\\\" ? t(\\\"flow.noDescription\\\") : description}\\n          </div>\\n        )}\\n        <Form.Message match=\\\"valueMissing\\\" className=\\\"field-invalid\\\">\\n          {t(\\\"flow.pleaseEnterDescription\\\")}\\n        </Form.Message>\\n        {/* Callers that only display the flow (no setLocked) would otherwise\\n            render a focusable switch that cannot change anything. */}\\n        {setLocked && (\\n          <div className=\\\"mt-3\\\">\\n            <div className=\\\"flex items-center gap-2\\\">\\n              <div>\\n                <div className=\\\"flex items-center gap-2\\\">\\n                  <Form.Label className=\\\"text-mmd font-medium\\\">\\n                    {t(\\\"flow.lockFlow\\\")}\\n                  </Form.Label>\\n\\n                  <ForwardedIconComponent\\n                    name={locked ? \\\"Lock\\\" : \\\"Unlock\\\"}\\n                    className=\\\"text-muted-foreground !w-5 !h-5\\\"\\n                  />\\n                </div>\\n\\n                <p className=\\\"text-xs text-muted-foreground/70 mt-1 font-normal\\\">\\n                  {t(\\\"flow.lockFlowDescription\\\")}\\n                </p>\\n              </div>\\n\\n              <Switch\\n                checked={!!locked}\\n                onCheckedChange={(v) => setLocked(v)}\\n                disabled={readOnly}\\n                className=\\\"data-[state=checked]:bg-primary ml-auto\\\"\\n                data-testid=\\\"lock-flow-switch\\\"\\n                aria-label={t(\\\"flow.lockFlowAriaLabel\\\")}\\n              />\\n            </div>\\n          </div>\\n        )}\\n      </Form.Field>\\n    </>\\n  );\\n};\\n\\nexport default EditFlowSettings;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/__tests__/flow-builder-welcome-mount.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eec075fb19559fbb7027fab905a04557037e0fa5209fbbff2a0c926a094279f7\",\"content\":\"/**\\n * Tests for the welcome-overlay mount, focused on the placeholder-cleanup\\n * behavior.\\n *\\n * Bug: clicking \\\"New Flow\\\" eagerly creates an empty placeholder flow and opens\\n * the welcome overlay on it. Picking a template via \\\"Browse more\u2026\\\" spins up a\\n * SECOND flow and navigates to it, leaving the blank placeholder orphaned \u2014 so\\n * the user ends up with two flows when they wanted one. The mount must delete\\n * the orphaned placeholder when the user navigates away from it.\\n */\\n\\nimport { render } from \\\"@testing-library/react\\\";\\nimport { FlowBuilderWelcomeMount } from \\\"../flow-builder-welcome-mount\\\";\\n\\n// Heavy children \u2014 render nothing, we only exercise the mount's effects.\\njest.mock(\\\"../flow-builder-welcome\\\", () => ({\\n  __esModule: true,\\n  FlowBuilderWelcome: () => null,\\n}));\\njest.mock(\\\"../../../../modals/templatesModal\\\", () => ({\\n  __esModule: true,\\n  default: () => null,\\n}));\\n\\nconst close = jest.fn();\\nconst setPendingMessage = jest.fn();\\nlet welcomeState: {\\n  isOpen: boolean;\\n  openedForFlowId: string | null;\\n};\\njest.mock(\\\"@/stores/flowBuilderWelcomeStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector?: (state: unknown) => unknown) => {\\n    const state = {\\n      ...welcomeState,\\n      close,\\n      setPendingMessage,\\n    };\\n    return selector ? selector(state) : state;\\n  }),\\n}));\\n\\nlet flowsManagerState: {\\n  currentFlowId: string | null;\\n  flows: Array<{ id: string; data?: { nodes?: unknown[] } }>;\\n};\\njest.mock(\\\"@/stores/flowsManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector?: (state: unknown) => unknown) => {\\n    return selector ? selector(flowsManagerState) : flowsManagerState;\\n  }),\\n}));\\n\\nconst setAssistantSidebarOpen = jest.fn();\\njest.mock(\\\"@/stores/assistantManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector?: (state: unknown) => unknown) => {\\n    const state = { setAssistantSidebarOpen };\\n    return selector ? selector(state) : state;\\n  }),\\n}));\\n\\njest.mock(\\\"@/components/ui/sidebar\\\", () => ({\\n  __esModule: true,\\n  useSidebar: () => ({ setOpen: jest.fn(), setActiveSection: jest.fn() }),\\n}));\\n\\nconst applyTemplate = jest.fn();\\njest.mock(\\\"../hooks/use-apply-template-to-current-flow\\\", () => ({\\n  __esModule: true,\\n  useApplyTemplateToCurrentFlow: () => applyTemplate,\\n}));\\n\\nconst deleteFlow = jest.fn().mockResolvedValue(undefined);\\njest.mock(\\\"@/hooks/flows/use-delete-flow\\\", () => ({\\n  __esModule: true,\\n  default: () => ({ deleteFlow, isDeleting: false }),\\n}));\\n\\ndescribe(\\\"FlowBuilderWelcomeMount placeholder cleanup\\\", () => {\\n  beforeEach(() => {\\n    close.mockClear();\\n    deleteFlow.mockClear();\\n    welcomeState = { isOpen: true, openedForFlowId: \\\"flow-placeholder\\\" };\\n    flowsManagerState = {\\n      currentFlowId: \\\"flow-placeholder\\\",\\n      flows: [{ id: \\\"flow-placeholder\\\", data: { nodes: [] } }],\\n    };\\n  });\\n\\n  it(\\\"should_delete_the_blank_placeholder_when_user_navigates_to_a_different_template_flow\\\", () => {\\n    // Arrange \u2014 welcome opened for the blank placeholder, but the user picked a\\n    // template that spun up \\\"flow-template\\\" and navigated to it.\\n    welcomeState = { isOpen: true, openedForFlowId: \\\"flow-placeholder\\\" };\\n    flowsManagerState = {\\n      currentFlowId: \\\"flow-template\\\",\\n      flows: [\\n        { id: \\\"flow-placeholder\\\", data: { nodes: [] } },\\n        { id: \\\"flow-template\\\", data: { nodes: [{ id: \\\"n1\\\" }] } },\\n      ],\\n    };\\n\\n    // Act\\n    render(<FlowBuilderWelcomeMount />);\\n\\n    // Assert \u2014 the orphaned blank placeholder is deleted (single flow remains)\\n    expect(deleteFlow).toHaveBeenCalledWith({ id: \\\"flow-placeholder\\\" });\\n    expect(close).toHaveBeenCalled();\\n  });\\n\\n  it(\\\"should_still_reap_the_placeholder_after_the_overlay_was_dismissed_for_navigation\\\", () => {\\n    // The templates path calls dismissForNavigation() in the same tick as the\\n    // navigate, so this effect always runs with isOpen already false. Cleanup\\n    // must key off openedForFlowId alone, never isOpen.\\n    welcomeState = { isOpen: false, openedForFlowId: \\\"flow-placeholder\\\" };\\n    flowsManagerState = {\\n      currentFlowId: \\\"flow-template\\\",\\n      flows: [\\n        { id: \\\"flow-placeholder\\\", data: { nodes: [] } },\\n        { id: \\\"flow-template\\\", data: { nodes: [{ id: \\\"n1\\\" }] } },\\n      ],\\n    };\\n\\n    render(<FlowBuilderWelcomeMount />);\\n\\n    expect(deleteFlow).toHaveBeenCalledWith({ id: \\\"flow-placeholder\\\" });\\n    expect(close).toHaveBeenCalled();\\n  });\\n\\n  it(\\\"should_not_delete_anything_when_still_on_the_placeholder_flow\\\", () => {\\n    // Quick-template path mutates the placeholder in place \u2014 same flow id, so\\n    // there is nothing to clean up.\\n    welcomeState = { isOpen: true, openedForFlowId: \\\"flow-placeholder\\\" };\\n    flowsManagerState = {\\n      currentFlowId: \\\"flow-placeholder\\\",\\n      flows: [{ id: \\\"flow-placeholder\\\", data: { nodes: [] } }],\\n    };\\n\\n    render(<FlowBuilderWelcomeMount />);\\n\\n    expect(deleteFlow).not.toHaveBeenCalled();\\n  });\\n\\n  it(\\\"should_not_delete_the_placeholder_when_it_already_has_nodes\\\", () => {\\n    // Safety guard: never delete a flow the user actually built on.\\n    welcomeState = { isOpen: true, openedForFlowId: \\\"flow-placeholder\\\" };\\n    flowsManagerState = {\\n      currentFlowId: \\\"flow-template\\\",\\n      flows: [\\n        { id: \\\"flow-placeholder\\\", data: { nodes: [{ id: \\\"kept\\\" }] } },\\n        { id: \\\"flow-template\\\", data: { nodes: [{ id: \\\"n1\\\" }] } },\\n      ],\\n    };\\n\\n    render(<FlowBuilderWelcomeMount />);\\n\\n    expect(deleteFlow).not.toHaveBeenCalled();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/__tests__/flow-builder-welcome.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8e6cfa22e4d02aa6060216c0350ed891edd503e30ae4a104e0ab7641df4ee90d\",\"content\":\"/**\\n * Component tests for the FlowBuilderWelcome overlay.\\n *\\n * Treats the overlay as a presentational component driven by injected\\n * callbacks \u2014 the actual wire-up to the store / templates modal / assistant\\n * panel lives in the parent, so these tests can assert behavior in isolation.\\n */\\n\\nimport { fireEvent, render, screen } from \\\"@testing-library/react\\\";\\nimport userEvent from \\\"@testing-library/user-event\\\";\\nimport type { AssistantModel } from \\\"@/components/core/assistantPanel/assistant-panel.types\\\";\\nimport { DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH } from \\\"@/constants/constants\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport { useUtilityStore } from \\\"@/stores/utilityStore\\\";\\nimport { FlowBuilderWelcome } from \\\"../flow-builder-welcome\\\";\\n\\nconst WELCOME_TITLE = \\\"What do you want to build?\\\";\\nconst WELCOME_TEXTAREA_PLACEHOLDER = \\\"Describe your flow...\\\";\\nconst WELCOME_SIMPLE_AGENT_LABEL = \\\"Simple Agent\\\";\\nconst WELCOME_VECTOR_STORE_RAG_LABEL = \\\"Vector Store RAG\\\";\\nconst WELCOME_BROWSE_MORE_LABEL = \\\"Browse more...\\\";\\n\\n// Mock the icon component to keep these tests free from SVG / asset noise.\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => {\\n  return function MockIcon({ name }: { name: string }) {\\n    return <span data-testid={`icon-${name}`} />;\\n  };\\n});\\n\\n// ShadTooltip wraps Radix Tooltip which needs a TooltipProvider ancestor \u2014\\n// the welcome renders standalone in these tests. Pass children through.\\njest.mock(\\\"@/components/common/shadTooltipComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ children }: { children: React.ReactNode }) => children,\\n}));\\n\\n// ModelSelector pulls in React Query (useGetModelProviders) which needs a\\n// QueryClientProvider wrapper. These tests focus on the welcome's own\\n// callbacks/wiring, so replace the selector with a stub.\\njest.mock(\\\"@/components/core/assistantPanel/components/model-selector\\\", () => ({\\n  ModelSelector: () => <div data-testid=\\\"mock-model-selector\\\" />,\\n}));\\n\\nconst SELECTED_MODEL: AssistantModel = {\\n  id: \\\"OpenAI-gpt-4o\\\",\\n  name: \\\"gpt-4o\\\",\\n  provider: \\\"OpenAI\\\",\\n  displayName: \\\"gpt-4o\\\",\\n};\\nlet mockSelectedModel: AssistantModel | null = SELECTED_MODEL;\\n\\n// The shared model state hook touches ``localStorage`` on init \u2014 keep that\\n// path predictable in tests while still exercising authorization of the\\n// selected value.\\njest.mock(\\n  \\\"@/components/core/assistantPanel/hooks/use-assistant-selected-model\\\",\\n  () => ({\\n    useAssistantSelectedModel: () => [mockSelectedModel, jest.fn()],\\n  }),\\n);\\n\\n// useEnabledModels hits React Query. Default the stub to \\\"has providers\\\" so\\n// the normal input renders; individual tests can override via the mockable\\n// reference below.\\nconst mockUseEnabledModels = jest.fn(() => ({\\n  hasEnabledModels: true,\\n  filteredProviders: [],\\n  isLoading: false,\\n  isError: false,\\n  isCatalogReady: true,\\n  isModelEnabled: (model: AssistantModel | null): boolean => model !== null,\\n}));\\njest.mock(\\\"@/components/core/assistantPanel/hooks/use-enabled-models\\\", () => ({\\n  useEnabledModels: () => mockUseEnabledModels(),\\n}));\\n\\n// ModelProviderModal is a heavy settings surface \u2014 stub it; we only assert\\n// it mounts when the configure CTA is clicked.\\njest.mock(\\\"@/modals/modelProviderModal\\\", () => ({\\n  __esModule: true,\\n  default: ({ open }: { open: boolean }) =>\\n    open ? <div data-testid=\\\"mock-model-provider-modal\\\" /> : null,\\n}));\\n\\nfunction makeProps(\\n  overrides: Partial<Parameters<typeof FlowBuilderWelcome>[0]> = {},\\n) {\\n  return {\\n    onSubmit: jest.fn(),\\n    onSelectTemplate: jest.fn(),\\n    onBrowseMore: jest.fn(),\\n    onClose: jest.fn(),\\n    onSelectRailItem: jest.fn(),\\n    ...overrides,\\n  };\\n}\\n\\nconst example = (name_key: string) =>\\n  ({ id: name_key, name: name_key, name_key }) as never;\\n\\n/** Both quick templates plus one other, i.e. an unrestricted catalog. */\\nconst FULL_CATALOG = [\\n  example(\\\"simple_agent\\\"),\\n  example(\\\"vector_store_rag\\\"),\\n  example(\\\"basic_prompting\\\"),\\n];\\n\\ndescribe(\\\"FlowBuilderWelcome\\\", () => {\\n  beforeEach(() => {\\n    useFlowsManagerStore.setState({ examples: FULL_CATALOG });\\n    mockSelectedModel = SELECTED_MODEL;\\n    mockUseEnabledModels.mockReturnValue({\\n      hasEnabledModels: true,\\n      filteredProviders: [],\\n      isLoading: false,\\n      isError: false,\\n      isCatalogReady: true,\\n      isModelEnabled: (model: AssistantModel | null): boolean => model !== null,\\n    });\\n    useUtilityStore\\n      .getState()\\n      .setAssistantMaxMessageLength(DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH);\\n  });\\n\\n  describe(\\\"no model provider configured\\\", () => {\\n    it(\\\"should_show_configure_provider_state_instead_of_textarea\\\", () => {\\n      mockUseEnabledModels.mockReturnValue({\\n        hasEnabledModels: false,\\n        filteredProviders: [],\\n        isLoading: false,\\n        isError: false,\\n        isCatalogReady: true,\\n        isModelEnabled: () => false,\\n      });\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-no-provider\\\"),\\n      ).toBeInTheDocument();\\n      expect(\\n        screen.queryByTestId(\\\"flow-builder-welcome-textarea\\\"),\\n      ).not.toBeInTheDocument();\\n    });\\n\\n    it(\\\"should_keep_template_buttons_available_with_no_provider\\\", () => {\\n      mockUseEnabledModels.mockReturnValue({\\n        hasEnabledModels: false,\\n        filteredProviders: [],\\n        isLoading: false,\\n        isError: false,\\n        isCatalogReady: true,\\n        isModelEnabled: () => false,\\n      });\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-template-simple-agent\\\"),\\n      ).toBeInTheDocument();\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-browse-more\\\"),\\n      ).toBeInTheDocument();\\n    });\\n\\n    it(\\\"should_open_provider_modal_when_configure_clicked\\\", async () => {\\n      mockUseEnabledModels.mockReturnValue({\\n        hasEnabledModels: false,\\n        filteredProviders: [],\\n        isLoading: false,\\n        isError: false,\\n        isCatalogReady: true,\\n        isModelEnabled: () => false,\\n      });\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-configure-providers\\\"),\\n      );\\n      expect(\\n        screen.getByTestId(\\\"mock-model-provider-modal\\\"),\\n      ).toBeInTheDocument();\\n    });\\n\\n    it(\\\"should_NOT_show_configure_state_while_models_are_loading\\\", () => {\\n      mockUseEnabledModels.mockReturnValue({\\n        hasEnabledModels: false,\\n        filteredProviders: [],\\n        isLoading: true,\\n        isError: false,\\n        isCatalogReady: false,\\n        isModelEnabled: () => false,\\n      });\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      expect(\\n        screen.queryByTestId(\\\"flow-builder-welcome-no-provider\\\"),\\n      ).not.toBeInTheDocument();\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-textarea\\\"),\\n      ).toBeInTheDocument();\\n    });\\n  });\\n\\n  describe(\\\"rendering\\\", () => {\\n    it(\\\"should_render_the_headline_and_textarea_placeholder\\\", () => {\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      expect(screen.getByText(WELCOME_TITLE)).toBeInTheDocument();\\n      expect(\\n        screen.getByPlaceholderText(WELCOME_TEXTAREA_PLACEHOLDER),\\n      ).toBeInTheDocument();\\n    });\\n\\n    it(\\\"should_render_both_quick_template_buttons\\\", () => {\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      expect(\\n        screen.getByRole(\\\"button\\\", { name: WELCOME_SIMPLE_AGENT_LABEL }),\\n      ).toBeInTheDocument();\\n      expect(\\n        screen.getByRole(\\\"button\\\", { name: WELCOME_VECTOR_STORE_RAG_LABEL }),\\n      ).toBeInTheDocument();\\n    });\\n\\n    it(\\\"should_render_the_browse_more_templates_link\\\", () => {\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n      expect(\\n        screen.getByRole(\\\"button\\\", { name: WELCOME_BROWSE_MORE_LABEL }),\\n      ).toBeInTheDocument();\\n    });\\n  });\\n\\n  describe(\\\"submit\\\", () => {\\n    it(\\\"should_call_onSubmit_with_trimmed_text_when_user_clicks_send\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      await userEvent.type(\\n        screen.getByPlaceholderText(WELCOME_TEXTAREA_PLACEHOLDER),\\n        \\\"  build a chatbot  \\\",\\n      );\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-send-button\\\"),\\n      );\\n\\n      expect(props.onSubmit).toHaveBeenCalledWith(\\\"build a chatbot\\\");\\n    });\\n\\n    it(\\\"should_NOT_call_onSubmit_when_textarea_is_empty_or_only_whitespace\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      await userEvent.type(\\n        screen.getByPlaceholderText(WELCOME_TEXTAREA_PLACEHOLDER),\\n        \\\"   \\\",\\n      );\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-send-button\\\"),\\n      );\\n\\n      expect(props.onSubmit).not.toHaveBeenCalled();\\n    });\\n\\n    it(\\\"should_call_onSubmit_when_user_presses_Enter_without_shift\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      const textarea = screen.getByPlaceholderText(\\n        WELCOME_TEXTAREA_PLACEHOLDER,\\n      );\\n      await userEvent.type(textarea, \\\"hello{Enter}\\\");\\n\\n      expect(props.onSubmit).toHaveBeenCalledWith(\\\"hello\\\");\\n    });\\n\\n    it(\\\"should_NOT_call_onSubmit_when_user_presses_Shift_Enter\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      const textarea = screen.getByPlaceholderText(\\n        WELCOME_TEXTAREA_PLACEHOLDER,\\n      );\\n      await userEvent.type(textarea, \\\"line1{Shift>}{Enter}{/Shift}line2\\\");\\n\\n      expect(props.onSubmit).not.toHaveBeenCalled();\\n      expect(textarea).toHaveValue(\\\"line1\\\\nline2\\\");\\n    });\\n\\n    it(\\\"should_disable_send_and_block_Enter_while_the_scoped_catalog_is_loading\\\", async () => {\\n      mockUseEnabledModels.mockReturnValue({\\n        hasEnabledModels: false,\\n        filteredProviders: [],\\n        isLoading: true,\\n        isError: false,\\n        isCatalogReady: false,\\n        isModelEnabled: () => false,\\n      });\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      const textarea = screen.getByPlaceholderText(\\n        WELCOME_TEXTAREA_PLACEHOLDER,\\n      );\\n      await userEvent.type(textarea, \\\"build a scoped agent\\\");\\n\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-send-button\\\"),\\n      ).toBeDisabled();\\n      fireEvent.keyDown(textarea, { key: \\\"Enter\\\", shiftKey: false });\\n      expect(props.onSubmit).not.toHaveBeenCalled();\\n    });\\n\\n    it(\\\"should_reject_a_stale_saved_model_after_the_flow_scope_changes\\\", async () => {\\n      mockUseEnabledModels.mockReturnValue({\\n        hasEnabledModels: true,\\n        filteredProviders: [],\\n        isLoading: false,\\n        isError: false,\\n        isCatalogReady: true,\\n        isModelEnabled: () => false,\\n      });\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      const textarea = screen.getByPlaceholderText(\\n        WELCOME_TEXTAREA_PLACEHOLDER,\\n      );\\n      await userEvent.type(textarea, \\\"build a scoped agent\\\");\\n\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-send-button\\\"),\\n      ).toBeDisabled();\\n      fireEvent.keyDown(textarea, { key: \\\"Enter\\\", shiftKey: false });\\n      expect(props.onSubmit).not.toHaveBeenCalled();\\n    });\\n  });\\n\\n  describe(\\\"quick templates\\\", () => {\\n    it(\\\"should_call_onSelectTemplate_with_simple_agent_name_key_when_button_is_clicked\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByRole(\\\"button\\\", { name: WELCOME_SIMPLE_AGENT_LABEL }),\\n      );\\n      expect(props.onSelectTemplate).toHaveBeenCalledWith(\\\"simple_agent\\\");\\n    });\\n\\n    it(\\\"should_call_onSelectTemplate_with_vector_store_rag_name_key_when_button_is_clicked\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByRole(\\\"button\\\", { name: WELCOME_VECTOR_STORE_RAG_LABEL }),\\n      );\\n      expect(props.onSelectTemplate).toHaveBeenCalledWith(\\\"vector_store_rag\\\");\\n    });\\n  });\\n\\n  describe(\\\"catalog policy\\\", () => {\\n    it(\\\"should_hide_a_quick_template_its_catalog_no_longer_offers\\\", () => {\\n      // Clicking a button for a blocked template only fails the lookup, so it\\n      // is not offered at all.\\n      useFlowsManagerStore.setState({\\n        examples: [example(\\\"vector_store_rag\\\")],\\n      });\\n\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n\\n      expect(\\n        screen.queryByTestId(\\\"flow-builder-welcome-template-simple-agent\\\"),\\n      ).toBeNull();\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-template-vector-store-rag\\\"),\\n      ).toBeInTheDocument();\\n    });\\n\\n    it(\\\"should_keep_browse_more_while_any_template_survives\\\", () => {\\n      // The modal is worth opening for templates that have no button here.\\n      useFlowsManagerStore.setState({ examples: [example(\\\"basic_prompting\\\")] });\\n\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-browse-more\\\"),\\n      ).toBeInTheDocument();\\n      expect(\\n        screen.queryByTestId(\\\"flow-builder-welcome-template-simple-agent\\\"),\\n      ).toBeNull();\\n    });\\n\\n    it(\\\"should_offer_a_blank_flow_when_no_template_survives\\\", () => {\\n      // Nothing to browse and nothing to start from, so the row collapses to\\n      // the one action left rather than three dead ends.\\n      useFlowsManagerStore.setState({ examples: [] });\\n\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-blank-flow\\\"),\\n      ).toBeInTheDocument();\\n      expect(\\n        screen.queryByTestId(\\\"flow-builder-welcome-browse-more\\\"),\\n      ).toBeNull();\\n      expect(screen.queryByText(\\\"Or start from a template:\\\")).toBeNull();\\n    });\\n\\n    it(\\\"should_land_on_the_blank_canvas_from_the_blank_flow_action\\\", async () => {\\n      // The welcome already sits on a freshly created empty flow, so starting\\n      // blank is just dismissing the overlay onto it.\\n      useFlowsManagerStore.setState({ examples: [] });\\n      const props = makeProps();\\n\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-blank-flow\\\"),\\n      );\\n\\n      expect(props.onClose).toHaveBeenCalledTimes(1);\\n    });\\n  });\\n\\n  describe(\\\"browse more\\\", () => {\\n    it(\\\"should_call_onBrowseMore_when_the_browse_link_is_clicked\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByRole(\\\"button\\\", { name: WELCOME_BROWSE_MORE_LABEL }),\\n      );\\n      expect(props.onBrowseMore).toHaveBeenCalledTimes(1);\\n    });\\n  });\\n\\n  describe(\\\"faux sidebar rail\\\", () => {\\n    it(\\\"should_call_onSelectRailItem_with_section_id_when_rail_icon_is_clicked\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-faux-rail-components\\\"),\\n      );\\n      expect(props.onSelectRailItem).toHaveBeenCalledWith(\\\"components\\\");\\n    });\\n\\n    it(\\\"should_NOT_call_onClose_when_a_rail_icon_is_clicked\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-faux-rail-memories\\\"),\\n      );\\n      expect(props.onClose).not.toHaveBeenCalled();\\n    });\\n  });\\n\\n  describe(\\\"close paths\\\", () => {\\n    it(\\\"should_call_onClose_when_user_clicks_the_backdrop\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByTestId(\\\"flow-builder-welcome-backdrop\\\"),\\n      );\\n      expect(props.onClose).toHaveBeenCalledTimes(1);\\n    });\\n\\n    it(\\\"should_NOT_call_onClose_when_user_clicks_inside_the_content_panel\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.click(\\n        screen.getByPlaceholderText(WELCOME_TEXTAREA_PLACEHOLDER),\\n      );\\n      expect(props.onClose).not.toHaveBeenCalled();\\n    });\\n\\n    it(\\\"should_call_onClose_when_user_presses_Escape\\\", async () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      await userEvent.keyboard(\\\"{Escape}\\\");\\n      expect(props.onClose).toHaveBeenCalledTimes(1);\\n    });\\n\\n    it(\\\"should_ignore_Escape_already_consumed_by_a_dialog_layer\\\", () => {\\n      // Radix's DismissableLayer preventDefaults the Escape it uses to close\\n      // a dialog stacked above the welcome (e.g. the TemplatesModal) but the\\n      // event still bubbles to window; the welcome must not treat it as its\\n      // own dismissal, or one keypress closes both layers (LE-2041 QA).\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n      const event = new KeyboardEvent(\\\"keydown\\\", {\\n        key: \\\"Escape\\\",\\n        cancelable: true,\\n        bubbles: true,\\n      });\\n      event.preventDefault();\\n      window.dispatchEvent(event);\\n      expect(props.onClose).not.toHaveBeenCalled();\\n    });\\n  });\\n  describe(\\\"message length limit\\\", () => {\\n    const typeInto = (value: string) => {\\n      const textarea = screen.getByTestId(\\n        \\\"flow-builder-welcome-textarea\\\",\\n      ) as HTMLTextAreaElement;\\n      fireEvent.change(textarea, { target: { value } });\\n      return textarea;\\n    };\\n\\n    it(\\\"should_accept_a_prompt_far_past_the_old_500_character_cap\\\", () => {\\n      // Regression: onChange sliced the value at 500 characters, so a longer\\n      // prompt lost its tail with nothing on screen to say so.\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n\\n      const textarea = typeInto(\\\"a\\\".repeat(1600));\\n\\n      expect(textarea.value).toHaveLength(1600);\\n      expect(textarea).toHaveAttribute(\\n        \\\"maxlength\\\",\\n        String(DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH),\\n      );\\n    });\\n\\n    it(\\\"should_always_show_the_character_count\\\", () => {\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-char-count\\\"),\\n      ).toHaveTextContent(`0/${DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH}`);\\n\\n      typeInto(\\\"a\\\".repeat(120));\\n\\n      expect(\\n        screen.getByTestId(\\\"flow-builder-welcome-char-count\\\"),\\n      ).toHaveTextContent(`120/${DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH}`);\\n    });\\n\\n    it(\\\"should_submit_a_prompt_at_the_configured_limit\\\", () => {\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      const prompt = \\\"a\\\".repeat(DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH);\\n      typeInto(prompt);\\n      fireEvent.click(screen.getByTestId(\\\"flow-builder-welcome-send-button\\\"));\\n\\n      expect(props.onSubmit).toHaveBeenCalledWith(prompt);\\n    });\\n\\n    it(\\\"should_name_the_environment_variable_when_the_limit_is_reached\\\", () => {\\n      render(<FlowBuilderWelcome {...makeProps()} />);\\n\\n      const textarea = typeInto(\\n        \\\"a\\\".repeat(DEFAULT_ASSISTANT_MAX_MESSAGE_LENGTH),\\n      );\\n\\n      const hint = screen.getByTestId(\\\"flow-builder-welcome-limit-hint\\\");\\n      expect(hint).toBeVisible();\\n      expect(hint).toHaveTextContent(\\\"LANGFLOW_ASSISTANT_MAX_MESSAGE_LENGTH\\\");\\n      expect(textarea).toHaveAttribute(\\\"aria-describedby\\\", hint.id);\\n    });\\n\\n    it(\\\"should_follow_the_limit_served_by_the_backend_config\\\", () => {\\n      useUtilityStore.getState().setAssistantMaxMessageLength(6000);\\n      const props = makeProps();\\n      render(<FlowBuilderWelcome {...props} />);\\n\\n      const prompt = \\\"a\\\".repeat(4000);\\n      const textarea = typeInto(prompt);\\n\\n      expect(textarea).toHaveAttribute(\\\"maxlength\\\", \\\"6000\\\");\\n      fireEvent.click(screen.getByTestId(\\\"flow-builder-welcome-send-button\\\"));\\n\\n      expect(props.onSubmit).toHaveBeenCalledWith(prompt);\\n    });\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/flow-builder-welcome-mount.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8bcc8705b47af062c1a5750a7d92c24daf818d4956e7a8ddebe53fad2b5eb5c3\",\"content\":\"import { useCallback, useEffect, useState } from \\\"react\\\";\\nimport { type SidebarSection, useSidebar } from \\\"@/components/ui/sidebar\\\";\\nimport useDeleteFlow from \\\"@/hooks/flows/use-delete-flow\\\";\\nimport useAssistantManagerStore from \\\"@/stores/assistantManagerStore\\\";\\nimport useFlowBuilderWelcomeStore from \\\"@/stores/flowBuilderWelcomeStore\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport TemplatesModal from \\\"../../../modals/templatesModal\\\";\\nimport { FlowBuilderWelcome } from \\\"./flow-builder-welcome\\\";\\nimport { useApplyTemplateToCurrentFlow } from \\\"./hooks/use-apply-template-to-current-flow\\\";\\n\\n/**\\n * Renders the FlowBuilderWelcome overlay on the canvas plus the\\n * TemplatesModal that \\\"Browse more templates\\\" opens, wiring all four\\n * exit paths to the rest of the app:\\n *\\n *   - Submit text       \u2192 stash as ``pendingMessage`` + open AssistantPanel\\n *   - Pick a template   \u2192 mutate current flow with the template's nodes/edges\\n *   - Browse more       \u2192 open the existing TemplatesModal locally\\n *   - Backdrop / Esc    \u2192 close the overlay, leave the blank canvas\\n *\\n * Mounted inside the FlowPage's canvas wrapper so it overlays the\\n * ReactFlow viewport but stays under app-level modals.\\n */\\nexport function FlowBuilderWelcomeMount() {\\n  const isOpen = useFlowBuilderWelcomeStore((state) => state.isOpen);\\n  const openedForFlowId = useFlowBuilderWelcomeStore(\\n    (state) => state.openedForFlowId,\\n  );\\n  const close = useFlowBuilderWelcomeStore((state) => state.close);\\n  const setPendingMessage = useFlowBuilderWelcomeStore(\\n    (state) => state.setPendingMessage,\\n  );\\n  const currentFlowId = useFlowsManagerStore((state) => state.currentFlowId);\\n  const flows = useFlowsManagerStore((state) => state.flows);\\n  const { deleteFlow } = useDeleteFlow();\\n\\n  // If the user navigates to a different flow while the welcome is open\\n  // (e.g. picks a template in the TemplatesModal that spins up a fresh\\n  // flow), auto-close it. Without this guard the welcome lingers on top of\\n  // the freshly-loaded canvas it doesn't belong to.\\n  //\\n  // The \\\"New Flow\\\" entry point eagerly creates an empty placeholder flow for\\n  // the welcome to overlay. When the user instead picks a template via \\\"Browse\\n  // more\u2026\\\", a SECOND flow spins up and we navigate to it \u2014 orphaning the blank\\n  // placeholder. Delete that placeholder here so the user is left with a SINGLE\\n  // flow (the template they chose) instead of two. Guarded to only remove a\\n  // still-blank placeholder so we never discard a flow the user built on.\\n  // Intentionally NOT guarded on ``isOpen``: the templates path dismisses the\\n  // overlay synchronously at navigation (see ``dismissForNavigation``), so by\\n  // the time this runs ``isOpen`` is already false and only ``openedForFlowId``\\n  // is left to tell us there is a placeholder to reap.\\n  useEffect(() => {\\n    if (openedForFlowId && currentFlowId && currentFlowId !== openedForFlowId) {\\n      const placeholder = flows?.find((flow) => flow.id === openedForFlowId);\\n      const isBlankPlaceholder =\\n        !!placeholder && (placeholder.data?.nodes?.length ?? 0) === 0;\\n      if (isBlankPlaceholder) {\\n        // Fire-and-forget: a failed cleanup must not block the close handoff.\\n        void deleteFlow({ id: openedForFlowId }).catch(() => {});\\n      }\\n      close();\\n    }\\n  }, [openedForFlowId, currentFlowId, close, flows, deleteFlow]);\\n  const setAssistantSidebarOpen = useAssistantManagerStore(\\n    (state) => state.setAssistantSidebarOpen,\\n  );\\n  const applyTemplate = useApplyTemplateToCurrentFlow();\\n  // Local \u2014 the TemplatesModal is reachable only from the welcome's \\\"Browse\\n  // more\\\" link, so its open state lives next to the welcome rather than in\\n  // a global store.\\n  const [isTemplatesOpen, setIsTemplatesOpen] = useState(false);\\n\\n  // The real FlowSidebarComponent is hidden via ``display: none`` at the\\n  // FlowPage level while the welcome is open, so we don't need to touch its\\n  // open/closed state here. We only need ``setOpen`` and ``setActiveSection``\\n  // for the rail-click handler below \u2014 clicking a rail icon should reveal\\n  // the real sidebar pre-expanded with the right section selected.\\n  const { setOpen: setSidebarOpen, setActiveSection } = useSidebar();\\n\\n  const handleSubmit = useCallback(\\n    (text: string) => {\\n      // Order matters here:\\n      //   1. ``close()`` first \u2014 closing also clears ``pendingMessage`` by\\n      //      design (prevents a stale prompt from replaying next time the\\n      //      welcome opens), so it MUST run before we stash the new prompt.\\n      //   2. ``setPendingMessage`` next \u2014 primes the AssistantPanel's\\n      //      open-effect with the freshly-typed prompt.\\n      //   3. ``setAssistantSidebarOpen(true)`` last \u2014 flips the panel on,\\n      //      causing it to mount AFTER the pending message is already in\\n      //      the store so its open-effect picks it up on first render.\\n      close();\\n      setPendingMessage(text);\\n      setAssistantSidebarOpen(true);\\n    },\\n    [setPendingMessage, setAssistantSidebarOpen, close],\\n  );\\n\\n  const handleSelectTemplate = useCallback(\\n    (nameKey: \\\"simple_agent\\\" | \\\"vector_store_rag\\\") => {\\n      // Pass ``close`` as the after-fit callback so the welcome stays in\\n      // front while React commits the nodes and ReactFlow animates fitView.\\n      // The overlay dismisses on the same frame the camera move starts \u2014\\n      // smooth handoff instead of a \\\"flash of unfitted canvas\\\".\\n      const applied = applyTemplate(nameKey, close);\\n      // ``applyTemplate`` returns false synchronously if the template lookup\\n      // misses; in that case ``close`` never runs, and the user stays on the\\n      // welcome with no canvas mutation.\\n      if (!applied) return;\\n    },\\n    [applyTemplate, close],\\n  );\\n\\n  const handleBrowseMore = useCallback(() => {\\n    setIsTemplatesOpen(true);\\n  }, []);\\n\\n  // Faux rail icon \u2192 open the real sidebar to its FULL expanded view with\\n  // that section pre-selected, then dismiss the welcome. Order: section\\n  // first (so the panel opens already showing the right content), then\\n  // open, then close.\\n  const handleSelectRailItem = useCallback(\\n    (section: SidebarSection) => {\\n      setActiveSection(section);\\n      setSidebarOpen(true);\\n      close();\\n    },\\n    [setActiveSection, setSidebarOpen, close],\\n  );\\n\\n  // Backdrop click / Escape \u2192 land the user on the canvas with the real\\n  // sidebar in its COLLAPSED, icon-only state (matches the minimalist look\\n  // of the welcome's faux rail). The FlowPage sidebar runs in\\n  // ``collapsible=\\\"icon\\\"`` mode, so ``open=false`` leaves the segmented\\n  // icon strip visible while hiding the expanded content panel.\\n  const handleDismiss = useCallback(() => {\\n    setSidebarOpen(false);\\n    close();\\n  }, [setSidebarOpen, close]);\\n\\n  return (\\n    <>\\n      {isOpen && (\\n        <FlowBuilderWelcome\\n          onSubmit={handleSubmit}\\n          onSelectTemplate={handleSelectTemplate}\\n          onBrowseMore={handleBrowseMore}\\n          onClose={handleDismiss}\\n          onSelectRailItem={handleSelectRailItem}\\n        />\\n      )}\\n      {/* Templates modal is mounted alongside the welcome so picking a\\n          template inside the modal can navigate to its new flow while the\\n          welcome stays out of the way. The modal handles its own create-\\n          flow + navigate plumbing \u2014 see ``modals/templatesModal``. */}\\n      {isTemplatesOpen && (\\n        <TemplatesModal open={isTemplatesOpen} setOpen={setIsTemplatesOpen} />\\n      )}\\n    </>\\n  );\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/flow-builder-welcome.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b089f2cd52a393d18525d178582a396a80f4df852ee97bd5fd6916a1e0000af2\",\"content\":\"import { ArrowUp } from \\\"lucide-react\\\";\\nimport { type KeyboardEvent, useEffect, useId, useRef, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport ShadTooltip from \\\"@/components/common/shadTooltipComponent\\\";\\nimport { ModelSelector } from \\\"@/components/core/assistantPanel/components/model-selector\\\";\\nimport { useAssistantSelectedModel } from \\\"@/components/core/assistantPanel/hooks/use-assistant-selected-model\\\";\\nimport { useAutoGrowTextarea } from \\\"@/components/core/assistantPanel/hooks/use-auto-grow-textarea\\\";\\nimport { useEnabledModels } from \\\"@/components/core/assistantPanel/hooks/use-enabled-models\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport type { SidebarSection } from \\\"@/components/ui/sidebar\\\";\\nimport ModelProviderModal from \\\"@/modals/modelProviderModal\\\";\\nimport { NAV_ITEMS } from \\\"@/pages/FlowPage/components/flowSidebarComponent/components/sidebar-nav-items\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport { useUtilityStore } from \\\"@/stores/utilityStore\\\";\\nimport {\\n  findStarterTemplate,\\n  type StarterTemplateNameKey,\\n} from \\\"./helpers/find-starter-template\\\";\\n\\nconst COMPOSER_MAX_HEIGHT_PX = 144; // 9rem \u2014 keeps the conversation above the composer readable\\n\\ninterface FlowBuilderWelcomeProps {\\n  /** Called with the trimmed text when the user submits the textarea. */\\n  onSubmit: (text: string) => void;\\n  /** Called with the stable ``name_key`` when a quick-template button is clicked. */\\n  onSelectTemplate: (nameKey: StarterTemplateNameKey) => void;\\n  /** Opens the existing full templates modal. */\\n  onBrowseMore: () => void;\\n  /** Called when the user dismisses the overlay (backdrop click, Escape). */\\n  onClose: () => void;\\n  /** Called when the user clicks an icon on the faux sidebar rail \u2014 the\\n   *  parent should open the real sidebar with that section pre-selected and\\n   *  then close the welcome. */\\n  onSelectRailItem: (section: SidebarSection) => void;\\n}\\n\\n// Faux rail uses the SAME source of truth as the real ``SidebarSegmentedNav``\\n// \u2014 importing ``NAV_ITEMS`` directly so any future add/remove/reorder of\\n// sidebar sections is automatically reflected here. Keeps the two views from\\n// drifting apart.\\n\\nconst TEMPLATE_BUTTON_CLASS =\\n  \\\"flex h-[3.125rem] w-[11rem] items-center justify-center gap-2.5 whitespace-nowrap rounded-xl border border-border bg-muted p-[0.8125rem] text-sm font-medium text-foreground transition-colors hover:bg-border\\\";\\n\\nexport function FlowBuilderWelcome({\\n  onSubmit,\\n  onSelectTemplate,\\n  onBrowseMore,\\n  onClose,\\n  onSelectRailItem,\\n}: FlowBuilderWelcomeProps) {\\n  const [message, setMessage] = useState(\\\"\\\");\\n  // Same server-owned cap the assistant panel uses (LANGFLOW_ASSISTANT_MAX_MESSAGE_LENGTH,\\n  // served by /config): this textarea posts to the same assistant endpoint.\\n  const maxMessageLength = useUtilityStore(\\n    (state) => state.assistantMaxMessageLength,\\n  );\\n  const limitHintId = useId();\\n  const textareaRef = useRef<HTMLTextAreaElement>(null);\\n  useAutoGrowTextarea(textareaRef, message, COMPOSER_MAX_HEIGHT_PX);\\n  // AppInitPage holds every route back until the examples fetch settles, so an\\n  // empty list here means a policy blocked them, never \\\"still loading\\\".\\n  const examples = useFlowsManagerStore((state) => state.examples);\\n  const currentFlowId = useFlowsManagerStore((state) => state.currentFlowId);\\n  const hasSimpleAgent = findStarterTemplate(examples, \\\"simple_agent\\\") !== null;\\n  const hasVectorStoreRag =\\n    findStarterTemplate(examples, \\\"vector_store_rag\\\") !== null;\\n  // \\\"Browse more\u2026\\\" opens the full modal, which is worth offering for any\\n  // surviving template, not just the two with their own button.\\n  const hasAnyTemplate = examples.length > 0;\\n\\n  useEffect(() => {\\n    textareaRef.current?.focus();\\n  }, []);\\n\\n  useEffect(() => {\\n    const handleKey = (e: globalThis.KeyboardEvent) => {\\n      // Radix's DismissableLayer preventDefaults the Escape it consumes to\\n      // dismiss a dialog (e.g. the TemplatesModal opened from \\\"Browse\\n      // more\u2026\\\") but does not stop propagation, so without this guard one\\n      // keypress would close both the modal and the welcome underneath,\\n      // stranding keyboard/screen-reader focus on the canvas (LE-2041 QA).\\n      if (e.key === \\\"Escape\\\" && !e.defaultPrevented) onClose();\\n    };\\n    window.addEventListener(\\\"keydown\\\", handleKey);\\n    return () => window.removeEventListener(\\\"keydown\\\", handleKey);\\n  }, [onClose]);\\n\\n  const messageLength = message.length;\\n  // The cap is hard, but never silent: the counter is always on screen and hitting the limit\\n  // names the environment variable that raises it.\\n  const isAtLimit = messageLength >= maxMessageLength;\\n  const { t } = useTranslation();\\n  // Shared model state with the AssistantPanel \u2014 picking a model here\\n  // persists to the same localStorage key, so the assistant opens with the\\n  // user's selection already applied (no second tour through the picker).\\n  const [selectedModel, setSelectedModel] = useAssistantSelectedModel();\\n  // No-provider hybrid: the AI textarea needs a model provider, but the\\n  // template buttons below don't. So when no provider is configured we swap\\n  // ONLY the input area for a configure-provider nudge and leave templates\\n  // fully usable.\\n  const { hasEnabledModels, isCatalogReady, isModelEnabled } =\\n    useEnabledModels();\\n  const [isProviderModalOpen, setIsProviderModalOpen] = useState(false);\\n  const selectedModelAuthorized = isModelEnabled(selectedModel);\\n  const canSend =\\n    message.trim().length > 0 && isCatalogReady && selectedModelAuthorized;\\n  const trySubmit = () => {\\n    const trimmed = message.trim();\\n    if (!canSend || trimmed.length > maxMessageLength) return;\\n    onSubmit(trimmed);\\n  };\\n  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {\\n    if (e.key === \\\"Enter\\\" && !e.shiftKey) {\\n      e.preventDefault();\\n      trySubmit();\\n    }\\n  };\\n  // A settled empty catalog means configuration is needed. Pending, paused,\\n  // or failed policy resolution keeps the composer visible but inert so stale\\n  // cached data never masquerades as current authorization.\\n  const showNoProviderState = isCatalogReady && !hasEnabledModels;\\n\\n  return (\\n    <div\\n      data-testid=\\\"flow-builder-welcome\\\"\\n      className=\\\"pointer-events-auto absolute inset-0 z-30 flex items-center justify-center\\\"\\n    >\\n      <button\\n        type=\\\"button\\\"\\n        data-testid=\\\"flow-builder-welcome-backdrop\\\"\\n        aria-label=\\\"Close welcome overlay\\\"\\n        className=\\\"absolute inset-0 cursor-default bg-background/70\\\"\\n        onClick={onClose}\\n      />\\n\\n      {/* Faux collapsed sidebar rail \u2014 paints in front of the backdrop so the\\n          user sees the icon strip from the design mock. Visually mirrors the\\n          real ``SidebarSegmentedNav`` (same icons, same primitives, same\\n          40px-wide column with border-r). Any click on a rail icon dismisses\\n          the overlay \u2014 the real sidebar then takes over. */}\\n      {/* Floating wrapper rail \u2014 matches the design mock: a rounded pill\\n          inset from all canvas edges, nearly full-height, with the icons\\n          clustered at the top. Subtle border separates it from the canvas\\n          background. */}\\n      <aside\\n        data-testid=\\\"flow-builder-welcome-faux-rail\\\"\\n        className=\\\"absolute left-1.5 top-1.5 z-10 flex w-10 animate-in flex-col items-center gap-1.5 rounded-lg border border-border bg-background p-1 duration-300 fade-in slide-in-from-left-2\\\"\\n        onClick={(e) => e.stopPropagation()}\\n      >\\n        {/* Mirror the real always-visible nav, Agent tab included. */}\\n        {NAV_ITEMS.map((item) => {\\n          const tooltip = t(item.tooltip);\\n          return (\\n            <ShadTooltip key={item.id} content={tooltip} side=\\\"right\\\">\\n              <button\\n                type=\\\"button\\\"\\n                onClick={() => onSelectRailItem(item.id)}\\n                aria-label={tooltip}\\n                data-testid={`flow-builder-welcome-faux-rail-${item.id}`}\\n                className=\\\"flex h-8 w-8 items-center justify-center rounded-md p-0 text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-accent-foreground\\\"\\n              >\\n                <ForwardedIconComponent\\n                  name={item.icon}\\n                  className=\\\"h-4.5 w-4.5\\\"\\n                />\\n                <span className=\\\"sr-only\\\">{tooltip}</span>\\n              </button>\\n            </ShadTooltip>\\n          );\\n        })}\\n      </aside>\\n\\n      <div\\n        data-testid=\\\"flow-builder-welcome-panel\\\"\\n        className=\\\"relative z-10 flex w-full max-w-[46rem] flex-col items-center gap-6 px-6\\\"\\n        onClick={(e) => e.stopPropagation()}\\n      >\\n        <h1 className=\\\"text-center text-4xl font-semibold text-foreground\\\">\\n          {showNoProviderState\\n            ? t(\\\"flowBuilderWelcome.titleNoProvider\\\")\\n            : t(\\\"flowBuilderWelcome.title\\\")}\\n        </h1>\\n\\n        {showNoProviderState ? (\\n          // No provider: drop the glow + gray input shell entirely. A clean,\\n          // minimal block \u2014 just the message + CTA \u2014 reads as a calm setup\\n          // step rather than a broken input. Templates below stay usable.\\n          <div\\n            data-testid=\\\"flow-builder-welcome-no-provider\\\"\\n            className=\\\"flex w-full flex-col items-center gap-3 py-4 text-center\\\"\\n          >\\n            <p className=\\\"max-w-[26rem] text-sm text-muted-foreground\\\">\\n              {t(\\\"flowBuilderWelcome.noProviderDescription\\\")}\\n            </p>\\n            <Button\\n              variant=\\\"outline\\\"\\n              data-testid=\\\"flow-builder-welcome-configure-providers\\\"\\n              className=\\\"gap-2\\\"\\n              onClick={() => setIsProviderModalOpen(true)}\\n            >\\n              <ForwardedIconComponent name=\\\"Settings\\\" className=\\\"h-4 w-4\\\" />\\n              {t(\\\"flowBuilderWelcome.configureModelProviders\\\")}\\n            </Button>\\n          </div>\\n        ) : (\\n          // Input container \u2014 design spec: 736\u00d7142px \u2248 46\u00d78.875rem, 6px\\n          // radius. ``w-full`` + max-width for responsiveness; ``min-h`` so\\n          // it grows with the textarea. The relative shell hosts the\\n          // gradient glow behind the input; glow tokens mirror the\\n          // AssistantPanel.\\n          <div className=\\\"relative w-full\\\">\\n            <div\\n              aria-hidden=\\\"true\\\"\\n              className=\\\"welcome-glow-breath pointer-events-none absolute -bottom-2 left-1/2 h-16 w-3/4 rounded-full blur-2xl\\\"\\n              style={{\\n                background:\\n                  \\\"linear-gradient(90deg, hsl(var(--accent-assistant-purple) / 0.4) 0%, hsl(var(--accent-assistant-brand) / 0.5) 50%, hsl(var(--accent-assistant-purple) / 0.4) 100%)\\\",\\n              }}\\n            />\\n            <div className=\\\"relative flex min-h-[8.875rem] w-full flex-col rounded-md border border-border bg-muted shadow-[0_0_15px_hsl(var(--accent-assistant-purple)/0.12),0_0_30px_hsl(var(--accent-assistant-brand)/0.08)]\\\">\\n              <textarea\\n                ref={textareaRef}\\n                data-testid=\\\"flow-builder-welcome-textarea\\\"\\n                placeholder={t(\\\"flowBuilderWelcome.textareaPlaceholder\\\")}\\n                value={message}\\n                maxLength={maxMessageLength}\\n                aria-describedby={isAtLimit ? limitHintId : undefined}\\n                onChange={(e) => setMessage(e.target.value)}\\n                onKeyDown={handleKeyDown}\\n                rows={3}\\n                className=\\\"nopan nodelete nodrag noflow nowheel max-h-[9rem] flex-1 resize-none overflow-y-auto border-0 bg-transparent px-4 pt-3 text-sm text-foreground outline-none placeholder:text-muted-foreground focus-visible:ring-0\\\"\\n              />\\n              {isAtLimit && (\\n                <div\\n                  id={limitHintId}\\n                  role=\\\"status\\\"\\n                  data-testid=\\\"flow-builder-welcome-limit-hint\\\"\\n                  className=\\\"px-4 py-1 text-xs text-destructive\\\"\\n                >\\n                  {t(\\\"assistant.messageLimitReached\\\")}\\n                </div>\\n              )}\\n              <div className=\\\"flex items-center justify-between gap-2 px-2 pb-2\\\">\\n                <ModelSelector\\n                  selectedModel={selectedModel}\\n                  onModelChange={setSelectedModel}\\n                />\\n                <div className=\\\"flex items-center gap-2\\\">\\n                  <span\\n                    data-testid=\\\"flow-builder-welcome-char-count\\\"\\n                    className={\\n                      isAtLimit\\n                        ? \\\"text-xs tabular-nums text-destructive\\\"\\n                        : \\\"text-xs tabular-nums text-muted-foreground\\\"\\n                    }\\n                  >\\n                    {messageLength}/{maxMessageLength}\\n                  </span>\\n                  <button\\n                    type=\\\"button\\\"\\n                    data-testid=\\\"flow-builder-welcome-send-button\\\"\\n                    aria-label={t(\\\"flowBuilderWelcome.sendLabel\\\")}\\n                    title={t(\\\"flowBuilderWelcome.sendLabel\\\")}\\n                    disabled={!canSend}\\n                    onClick={trySubmit}\\n                    className=\\\"flex h-8 w-8 items-center justify-center rounded-md bg-foreground text-background transition-colors hover:bg-foreground/90 disabled:opacity-50\\\"\\n                  >\\n                    <ArrowUp className=\\\"h-4 w-4\\\" />\\n                  </button>\\n                </div>\\n              </div>\\n            </div>\\n          </div>\\n        )}\\n        {isProviderModalOpen && (\\n          <ModelProviderModal\\n            open={isProviderModalOpen}\\n            onClose={() => setIsProviderModalOpen(false)}\\n            modelType=\\\"llm\\\"\\n            flowId={currentFlowId}\\n          />\\n        )}\\n\\n        {/* Template buttons \u2014 design spec: 143\u00d750px, 12px radius, 13px\\n            padding, 10px gap. A catalog policy can block any of these, and a\\n            button for a template that is gone would only fail on click, so\\n            each appears with its template. With nothing left to offer, the\\n            row becomes the one action still available: start blank. */}\\n        <div className=\\\"flex flex-col items-center gap-2\\\">\\n          {hasAnyTemplate ? (\\n            <>\\n              <span className=\\\"text-sm text-muted-foreground\\\">\\n                {t(\\\"flowBuilderWelcome.orTemplateLabel\\\")}\\n              </span>\\n              <div className=\\\"flex flex-wrap items-center justify-center gap-3\\\">\\n                {hasSimpleAgent && (\\n                  <button\\n                    type=\\\"button\\\"\\n                    data-testid=\\\"flow-builder-welcome-template-simple-agent\\\"\\n                    onClick={() => onSelectTemplate(\\\"simple_agent\\\")}\\n                    className={TEMPLATE_BUTTON_CLASS}\\n                  >\\n                    <ForwardedIconComponent name=\\\"Bot\\\" className=\\\"h-4 w-4\\\" />\\n                    {t(\\\"flowBuilderWelcome.simpleAgentLabel\\\")}\\n                  </button>\\n                )}\\n                {hasVectorStoreRag && (\\n                  <button\\n                    type=\\\"button\\\"\\n                    data-testid=\\\"flow-builder-welcome-template-vector-store-rag\\\"\\n                    onClick={() => onSelectTemplate(\\\"vector_store_rag\\\")}\\n                    className={TEMPLATE_BUTTON_CLASS}\\n                  >\\n                    <ForwardedIconComponent\\n                      name=\\\"Database\\\"\\n                      className=\\\"h-4 w-4\\\"\\n                    />\\n                    {t(\\\"flowBuilderWelcome.vectorStoreRagLabel\\\")}\\n                  </button>\\n                )}\\n                <button\\n                  type=\\\"button\\\"\\n                  data-testid=\\\"flow-builder-welcome-browse-more\\\"\\n                  onClick={onBrowseMore}\\n                  className={TEMPLATE_BUTTON_CLASS}\\n                >\\n                  <ForwardedIconComponent\\n                    name=\\\"LayoutGrid\\\"\\n                    className=\\\"h-4 w-4\\\"\\n                  />\\n                  {t(\\\"flowBuilderWelcome.browseMoreLabel\\\")}\\n                </button>\\n              </div>\\n            </>\\n          ) : (\\n            <button\\n              type=\\\"button\\\"\\n              data-testid=\\\"flow-builder-welcome-blank-flow\\\"\\n              onClick={onClose}\\n              className={TEMPLATE_BUTTON_CLASS}\\n            >\\n              <ForwardedIconComponent name=\\\"Plus\\\" className=\\\"h-4 w-4\\\" />\\n              {t(\\\"flowBuilderWelcome.blankFlowLabel\\\")}\\n            </button>\\n          )}\\n        </div>\\n      </div>\\n    </div>\\n  );\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/helpers/__tests__/find-starter-template.test.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4b158fe41cdcf1b1ded79995d3324ed0a498089c8b1d2cc895892e1757d34c04\",\"content\":\"import type { FlowType } from \\\"@/types/flow\\\";\\nimport { findStarterTemplate } from \\\"../find-starter-template\\\";\\n\\nfunction makeFlow(overrides: Partial<FlowType>): FlowType {\\n  return {\\n    id: overrides.id ?? \\\"fid-\\\" + Math.random().toString(36).slice(2),\\n    name: overrides.name ?? \\\"Untitled\\\",\\n    description: overrides.description ?? \\\"\\\",\\n    data: overrides.data ?? {\\n      nodes: [],\\n      edges: [],\\n      viewport: { x: 0, y: 0, zoom: 1 },\\n    },\\n    name_key: overrides.name_key ?? null,\\n    tags: overrides.tags ?? [],\\n  } as FlowType;\\n}\\n\\ndescribe(\\\"findStarterTemplate\\\", () => {\\n  it(\\\"should_return_the_example_when_name_key_matches\\\", () => {\\n    const simple = makeFlow({ name: \\\"Simple Agent\\\", name_key: \\\"simple_agent\\\" });\\n    const rag = makeFlow({\\n      name: \\\"Vector Store RAG\\\",\\n      name_key: \\\"vector_store_rag\\\",\\n    });\\n    const examples = [simple, rag];\\n\\n    expect(findStarterTemplate(examples, \\\"simple_agent\\\")).toBe(simple);\\n    expect(findStarterTemplate(examples, \\\"vector_store_rag\\\")).toBe(rag);\\n  });\\n\\n  it(\\\"should_return_null_when_no_example_has_the_requested_name_key\\\", () => {\\n    const examples = [makeFlow({ name_key: \\\"basic_prompting\\\" })];\\n    expect(findStarterTemplate(examples, \\\"simple_agent\\\")).toBeNull();\\n  });\\n\\n  it(\\\"should_return_null_when_examples_list_is_empty\\\", () => {\\n    expect(findStarterTemplate([], \\\"simple_agent\\\")).toBeNull();\\n  });\\n\\n  it(\\\"should_ignore_examples_with_null_name_key\\\", () => {\\n    // ``name_key`` is nullable; the helper must not throw on null entries \u2014\\n    // it should just skip them in the search.\\n    const examples = [\\n      makeFlow({ name: \\\"Generic\\\", name_key: null }),\\n      makeFlow({ name: \\\"Simple Agent\\\", name_key: \\\"simple_agent\\\" }),\\n    ];\\n    const found = findStarterTemplate(examples, \\\"simple_agent\\\");\\n    expect(found?.name).toBe(\\\"Simple Agent\\\");\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/helpers/find-starter-template.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1d52b1a914602419131176dd298d806db12bb2cc2a0c7d83c3a1faa07d04cfce\",\"content\":\"import type { FlowType } from \\\"@/types/flow\\\";\\n\\n/**\\n * The stable identifier the backend ships on each ``FlowType`` example \u2014\\n * ``name`` is user-facing and may be localized, ``name_key`` is the contract\\n * the frontend uses to address a specific starter template.\\n *\\n * Add new keys here as more quick-templates are wired into the welcome\\n * overlay so the call sites stay type-checked instead of stringly-typed.\\n */\\nexport type StarterTemplateNameKey = \\\"simple_agent\\\" | \\\"vector_store_rag\\\";\\n\\n/**\\n * Look up a starter-project example by its stable ``name_key``.\\n * Returns ``null`` when no example carries the requested key (or when the\\n * list is empty / still loading). The caller is responsible for handling\\n * the null case \u2014 usually by showing a placeholder or skipping the action.\\n */\\nexport function findStarterTemplate(\\n  examples: FlowType[],\\n  nameKey: StarterTemplateNameKey,\\n): FlowType | null {\\n  for (const example of examples) {\\n    if (example.name_key === nameKey) {\\n      return example;\\n    }\\n  }\\n  return null;\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/hooks/__tests__/use-apply-template-to-current-flow.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a11fe63e3b21dfbc70b3698f076550bcfa0d0b531b5a2599cd9f9c7e92e9e10\",\"content\":\"/**\\n * Tests for the hook that swaps the current empty flow's nodes/edges with a\\n * starter template's data. Used by the welcome overlay's quick-template\\n * buttons (Simple Agent / Vector Store RAG).\\n */\\n\\nimport { act, renderHook } from \\\"@testing-library/react\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport { useApplyTemplateToCurrentFlow } from \\\"../use-apply-template-to-current-flow\\\";\\n\\nconst setNodes = jest.fn();\\nconst setEdges = jest.fn();\\nconst setCurrentFlowInManager = jest.fn();\\nconst saveFlow = jest.fn().mockResolvedValue(undefined);\\nconst requestFitView = jest.fn();\\n\\nlet currentFlow: unknown;\\n\\njest.mock(\\\"@/stores/flowStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn((selector?: (state: unknown) => unknown) => {\\n    const state = { setNodes, setEdges, currentFlow, requestFitView };\\n    return selector ? selector(state) : state;\\n  }),\\n}));\\n\\njest.mock(\\\"@/hooks/flows/use-save-flow\\\", () => ({\\n  __esModule: true,\\n  default: () => saveFlow,\\n}));\\n\\nconst fullExamples = [\\n  {\\n    id: \\\"ex-1\\\",\\n    name: \\\"Simple Agent\\\",\\n    name_key: \\\"simple_agent\\\",\\n    description: \\\"\\\",\\n    tags: [],\\n    data: {\\n      nodes: [{ id: \\\"n1\\\" }],\\n      edges: [{ id: \\\"e1\\\" }],\\n      viewport: { x: 0, y: 0, zoom: 1 },\\n    },\\n  },\\n  {\\n    id: \\\"ex-2\\\",\\n    name: \\\"Vector Store RAG\\\",\\n    name_key: \\\"vector_store_rag\\\",\\n    description: \\\"\\\",\\n    tags: [],\\n    data: {\\n      nodes: [{ id: \\\"n2\\\" }, { id: \\\"n3\\\" }],\\n      edges: [{ id: \\\"e2\\\" }],\\n      viewport: { x: 0, y: 0, zoom: 1 },\\n    },\\n  },\\n];\\n\\nconst mockedFlowsManagerStore = useFlowsManagerStore as unknown as jest.Mock;\\n\\njest.mock(\\\"@/stores/flowsManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: jest.fn(),\\n}));\\n\\nfunction setStores(\\n  examples: typeof fullExamples,\\n  flows: Array<{ id: string; name: string; folder_id?: string }> = [],\\n) {\\n  mockedFlowsManagerStore.mockImplementation(\\n    (selector?: (state: unknown) => unknown) => {\\n      const state = {\\n        examples,\\n        flows,\\n        setCurrentFlow: setCurrentFlowInManager,\\n      };\\n      return selector ? selector(state) : state;\\n    },\\n  );\\n  (mockedFlowsManagerStore as unknown as { getState: () => unknown }).getState =\\n    () => ({ currentFlow });\\n}\\n\\ndescribe(\\\"useApplyTemplateToCurrentFlow\\\", () => {\\n  beforeEach(() => {\\n    setNodes.mockClear();\\n    setEdges.mockClear();\\n    setCurrentFlowInManager.mockClear();\\n    saveFlow.mockClear();\\n    requestFitView.mockClear();\\n    currentFlow = {\\n      id: \\\"flow-1\\\",\\n      name: \\\"New Flow\\\",\\n      folder_id: \\\"folder-A\\\",\\n      data: { nodes: [], edges: [], viewport: { x: 0, y: 0, zoom: 1 } },\\n    };\\n    setStores(fullExamples);\\n  });\\n\\n  it(\\\"should_apply_template_data_to_current_flow_when_template_is_applied\\\", () => {\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    let didApply = false;\\n    act(() => {\\n      didApply = result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(didApply).toBe(true);\\n    // setCurrentFlowInManager (which internally calls resetFlow \u2192 setNodes/setEdges)\\n    // is the path taken when currentFlow exists.\\n    expect(setCurrentFlowInManager).toHaveBeenCalledWith(\\n      expect.objectContaining({\\n        data: expect.objectContaining({\\n          nodes: [{ id: \\\"n1\\\" }],\\n          edges: [{ id: \\\"e1\\\" }],\\n        }),\\n      }),\\n    );\\n  });\\n\\n  it(\\\"should_pick_the_correct_template_when_a_different_name_key_is_passed\\\", () => {\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"vector_store_rag\\\");\\n    });\\n\\n    expect(setCurrentFlowInManager).toHaveBeenCalledWith(\\n      expect.objectContaining({\\n        data: expect.objectContaining({\\n          nodes: [{ id: \\\"n2\\\" }, { id: \\\"n3\\\" }],\\n          edges: [{ id: \\\"e2\\\" }],\\n        }),\\n      }),\\n    );\\n  });\\n\\n  it(\\\"should_return_false_and_not_mutate_when_no_example_matches_name_key\\\", () => {\\n    // ``examples`` may be empty (mid-load) or a key may not exist yet \u2014 the\\n    // hook must fail closed instead of clearing the canvas with nothing.\\n    setStores([]);\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    let didApply = true;\\n    act(() => {\\n      didApply = result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(didApply).toBe(false);\\n    expect(setNodes).not.toHaveBeenCalled();\\n    expect(setEdges).not.toHaveBeenCalled();\\n  });\\n\\n  it(\\\"should_rename_the_current_flow_to_the_template_name_and_persist_when_template_is_applied\\\", () => {\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\");\\n    });\\n\\n    // The generic \\\"New Flow\\\" placeholder adopts the template name...\\n    expect(setCurrentFlowInManager).toHaveBeenCalledWith(\\n      expect.objectContaining({ id: \\\"flow-1\\\", name: \\\"Simple Agent\\\" }),\\n    );\\n    // ...and the rename is persisted via saveFlow.\\n    expect(saveFlow).toHaveBeenCalledWith(\\n      expect.objectContaining({ id: \\\"flow-1\\\", name: \\\"Simple Agent\\\" }),\\n      expect.anything(),\\n    );\\n  });\\n\\n  it(\\\"should_dedupe_the_template_name_when_a_flow_with_that_name_already_exists_in_the_same_folder\\\", () => {\\n    // The \\\"Starter Project\\\" folder is seeded with real starter-project flows\\n    // (one literally named \\\"Simple Agent\\\"). Matching the rest of the app, the\\n    // rename version-dedupes against sibling flows \u2192 \\\"Simple Agent (1)\\\".\\n    setStores(fullExamples, [\\n      { id: \\\"seeded\\\", name: \\\"Simple Agent\\\", folder_id: \\\"folder-A\\\" },\\n    ]);\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(setCurrentFlowInManager).toHaveBeenCalledWith(\\n      expect.objectContaining({ name: \\\"Simple Agent (1)\\\" }),\\n    );\\n  });\\n\\n  it(\\\"should_dedupe_against_a_same_named_flow_in_a_different_folder\\\", () => {\\n    // Flow names are unique per USER in the database (``unique_flow_name`` on\\n    // (user_id, name)), not per folder. A folder-scoped rename lets the clash\\n    // through and the PATCH comes back 400 \\\"Name must be unique\\\" (LE-2232).\\n    setStores(fullExamples, [\\n      { id: \\\"other\\\", name: \\\"Simple Agent\\\", folder_id: \\\"folder-B\\\" },\\n    ]);\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(setCurrentFlowInManager).toHaveBeenCalledWith(\\n      expect.objectContaining({ name: \\\"Simple Agent (1)\\\" }),\\n    );\\n    expect(saveFlow).toHaveBeenCalledWith(\\n      expect.objectContaining({ name: \\\"Simple Agent (1)\\\" }),\\n      expect.anything(),\\n    );\\n  });\\n\\n  it(\\\"should_issue_the_save_before_the_optimistic_store_swap\\\", () => {\\n    // useSaveFlow skips the request when the payload already equals the\\n    // manager store's flow, so swapping first turns the save into a no-op and\\n    // leaves persistence to the debounced autosave \u2014 where nothing can react\\n    // to a rejected rename.\\n    let swapsWhenSaveWasCalled = -1;\\n    saveFlow.mockImplementationOnce(() => {\\n      swapsWhenSaveWasCalled = setCurrentFlowInManager.mock.calls.length;\\n      return Promise.resolve(undefined);\\n    });\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(swapsWhenSaveWasCalled).toBe(0);\\n    expect(setCurrentFlowInManager).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"should_not_dedupe_against_ownerless_example_flows\\\", () => {\\n    // Under AUTO_LOGIN the flows list also carries the ownerless starter\\n    // examples. They hold no user_id, so they never collide \u2014 suffixing\\n    // because of them would rename a flow whose name is actually free.\\n    setStores(fullExamples, [\\n      { id: \\\"ex-1\\\", name: \\\"Simple Agent\\\", folder_id: \\\"starter-folder\\\" },\\n    ]);\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(setCurrentFlowInManager).toHaveBeenCalledWith(\\n      expect.objectContaining({ name: \\\"Simple Agent\\\" }),\\n    );\\n  });\\n\\n  it(\\\"should_retry_with_the_next_version_when_the_save_hits_a_name_conflict\\\", async () => {\\n    // Safety net for what no client-side list can see: another tab/session\\n    // taking the name between the read and the PATCH. Retry with the next\\n    // free version instead of dropping the template on the floor.\\n    saveFlow.mockRejectedValueOnce({\\n      response: { status: 400, data: { detail: \\\"Name must be unique\\\" } },\\n    });\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    await act(async () => {\\n      result.current(\\\"simple_agent\\\");\\n      await Promise.resolve();\\n      await Promise.resolve();\\n    });\\n\\n    expect(saveFlow).toHaveBeenNthCalledWith(\\n      1,\\n      expect.objectContaining({ name: \\\"Simple Agent\\\" }),\\n      expect.anything(),\\n    );\\n    expect(saveFlow).toHaveBeenNthCalledWith(\\n      2,\\n      expect.objectContaining({ name: \\\"Simple Agent (1)\\\" }),\\n      expect.anything(),\\n    );\\n    expect(setCurrentFlowInManager).toHaveBeenLastCalledWith(\\n      expect.objectContaining({ name: \\\"Simple Agent (1)\\\" }),\\n    );\\n  });\\n\\n  it(\\\"should_stop_retrying_and_roll_back_when_every_version_conflicts\\\", async () => {\\n    saveFlow.mockRejectedValue({\\n      response: { status: 400, data: { detail: \\\"Name must be unique\\\" } },\\n    });\\n    const original = currentFlow;\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    await act(async () => {\\n      result.current(\\\"simple_agent\\\");\\n      for (let i = 0; i < 20; i++) await Promise.resolve();\\n    });\\n\\n    expect(saveFlow.mock.calls.length).toBeLessThanOrEqual(5);\\n    expect(setCurrentFlowInManager).toHaveBeenLastCalledWith(original);\\n  });\\n\\n  it(\\\"should_revert_the_optimistic_rename_when_the_persist_fails\\\", async () => {\\n    // The rename is applied optimistically to flowStore, then persisted. If the\\n    // save fails, the optimistic flowStore state must roll back so it does not\\n    // diverge from the flows list / backend (which still hold \\\"New Flow\\\").\\n    const original = currentFlow;\\n    saveFlow.mockRejectedValueOnce(new Error(\\\"persist failed\\\"));\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    await act(async () => {\\n      result.current(\\\"simple_agent\\\");\\n      await Promise.resolve();\\n    });\\n\\n    expect(setCurrentFlowInManager).toHaveBeenNthCalledWith(\\n      1,\\n      expect.objectContaining({ name: \\\"Simple Agent\\\" }),\\n    );\\n    expect(setCurrentFlowInManager).toHaveBeenLastCalledWith(original);\\n  });\\n\\n  // A template's nodes measure over several frames; fitting before they all\\n  // have dimensions frames the flow around a subset, which is what the welcome\\n  // overlay would then uncover.\\n  it(\\\"should_defer_the_fit_until_the_canvas_reports_the_graph_measured\\\", () => {\\n    const onFitted = jest.fn();\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\", onFitted);\\n    });\\n\\n    expect(requestFitView).toHaveBeenCalledTimes(1);\\n    expect(onFitted).not.toHaveBeenCalled();\\n\\n    act(() => {\\n      requestFitView.mock.calls[0][0]();\\n    });\\n\\n    expect(onFitted).toHaveBeenCalledTimes(1);\\n    // The canvas corrects the framing itself when uncovering narrows it, so\\n    // uncovering must not queue a second fit that races that resize.\\n    expect(requestFitView).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"should_not_rename_or_persist_when_there_is_no_current_flow\\\", () => {\\n    currentFlow = undefined;\\n    const { result } = renderHook(() => useApplyTemplateToCurrentFlow());\\n\\n    act(() => {\\n      result.current(\\\"simple_agent\\\");\\n    });\\n\\n    expect(setCurrentFlowInManager).not.toHaveBeenCalled();\\n    expect(saveFlow).not.toHaveBeenCalled();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/hooks/use-apply-template-to-current-flow.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6135380d15f76e07024a26e1b31bbebb23193bed4a7735a821be8221b62b019d\",\"content\":\"import { useCallback } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport useSaveFlow from \\\"@/hooks/flows/use-save-flow\\\";\\nimport useAlertStore from \\\"@/stores/alertStore\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport type { FlowType } from \\\"@/types/flow\\\";\\nimport { getUserScopedDuplicateName } from \\\"@/utils/flow-naming\\\";\\nimport {\\n  findStarterTemplate,\\n  type StarterTemplateNameKey,\\n} from \\\"../helpers/find-starter-template\\\";\\n\\nconst MAX_NAME_CONFLICT_RETRIES = 3;\\n\\ntype ApiErrorLike = {\\n  response?: { status?: number; data?: { detail?: unknown } };\\n  message?: string;\\n};\\n\\nfunction asApiError(error: unknown): ApiErrorLike {\\n  return (error ?? {}) as ApiErrorLike;\\n}\\n\\nfunction isFlowNameConflict(error: unknown): boolean {\\n  const { response } = asApiError(error);\\n  const detail = response?.data?.detail;\\n  return (\\n    response?.status === 400 &&\\n    typeof detail === \\\"string\\\" &&\\n    detail.toLowerCase() === \\\"name must be unique\\\"\\n  );\\n}\\n\\nfunction getErrorDetail(error: unknown): string {\\n  const { response, message } = asApiError(error);\\n  const detail = response?.data?.detail;\\n  return typeof detail === \\\"string\\\" ? detail : (message ?? \\\"Unknown error\\\");\\n}\\n\\n// Swaps the current (empty, welcome-created) flow's data with a starter\\n// template in place. Returns false when the template isn't loaded yet.\\nexport function useApplyTemplateToCurrentFlow() {\\n  const { t } = useTranslation();\\n  const setNodes = useFlowStore((state) => state.setNodes);\\n  const setEdges = useFlowStore((state) => state.setEdges);\\n  const currentFlow = useFlowStore((state) => state.currentFlow);\\n  const requestFitView = useFlowStore((state) => state.requestFitView);\\n  const examples = useFlowsManagerStore((state) => state.examples);\\n  const flows = useFlowsManagerStore((state) => state.flows);\\n  const setErrorData = useAlertStore((state) => state.setErrorData);\\n  // Use the manager store's setCurrentFlow so resetFlow (and syncNodeTranslations)\\n  // runs, ensuring component names are shown in the active language immediately.\\n  const setCurrentFlowInManager = useFlowsManagerStore(\\n    (state) => state.setCurrentFlow,\\n  );\\n  const saveFlow = useSaveFlow();\\n\\n  return useCallback(\\n    (nameKey: StarterTemplateNameKey, onFitted?: () => void): boolean => {\\n      const template = findStarterTemplate(examples, nameKey);\\n      const templateData = template?.data;\\n      if (!template || !templateData) return false;\\n\\n      if (currentFlow) {\\n        // Feeding backend-rejected names back as pseudo-flows lets the same\\n        // versioning logic hand out the next candidate.\\n        const rejectedNames: string[] = [];\\n        const nextCandidateName = () =>\\n          getUserScopedDuplicateName(\\n            { ...currentFlow, name: template.name },\\n            [\\n              ...(flows ?? []),\\n              ...rejectedNames.map((name, index) => ({\\n                id: `rejected-${index}`,\\n                name,\\n              })),\\n            ],\\n            examples ?? [],\\n          );\\n\\n        const buildFlow = (name: string): FlowType => ({\\n          ...currentFlow,\\n          name,\\n          data: {\\n            nodes: templateData.nodes ?? [],\\n            edges: templateData.edges ?? [],\\n            viewport: currentFlow.data?.viewport ?? { x: 0, y: 0, zoom: 1 },\\n          },\\n        });\\n\\n        // saveFlow bails out when the payload already matches the manager\\n        // store, so the request has to be issued before the optimistic swap.\\n        const persist = async (attempt: number): Promise<void> => {\\n          const candidate = buildFlow(nextCandidateName());\\n          const persisted = saveFlow(candidate, { suppressErrorToast: true });\\n          setCurrentFlowInManager(candidate);\\n          try {\\n            await persisted;\\n          } catch (error) {\\n            if (\\n              isFlowNameConflict(error) &&\\n              attempt < MAX_NAME_CONFLICT_RETRIES\\n            ) {\\n              rejectedNames.push(candidate.name);\\n              return persist(attempt + 1);\\n            }\\n            setErrorData({\\n              title: t(\\\"errors.failedToSaveFlow\\\"),\\n              list: [getErrorDetail(error)],\\n            });\\n            // Only roll back if the user hasn't switched to a different flow.\\n            const latest = useFlowsManagerStore.getState().currentFlow;\\n            if (latest?.id === candidate.id) {\\n              setCurrentFlowInManager(currentFlow);\\n            }\\n          }\\n        };\\n\\n        void persist(0);\\n      } else {\\n        // No flow context yet \u2014 update the canvas directly as a fallback.\\n        setNodes(templateData.nodes ?? []);\\n        setEdges(templateData.edges ?? []);\\n      }\\n\\n      // A template's nodes measure across several ResizeObserver batches, and a\\n      // fit that runs before they all have dimensions silently drops the ones\\n      // still pending \u2014 the flow would open framed around a subset. The canvas\\n      // fits once the graph is fully measured and then uncovers itself through\\n      // `onFitted`; uncovering returns the sidebar to the layout and narrows\\n      // the canvas, which `useFitViewWhenMeasured` corrects on its own.\\n      requestFitView(() => onFitted?.());\\n      return true;\\n    },\\n    [\\n      examples,\\n      flows,\\n      currentFlow,\\n      setNodes,\\n      setEdges,\\n      setCurrentFlowInManager,\\n      setErrorData,\\n      saveFlow,\\n      requestFitView,\\n      t,\\n    ],\\n  );\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowBuilderWelcome/hooks/use-start-new-flow.ts\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"849e60c96f7cdd28ce88860215b7783db4e3557bd5df2f4797cf6a81fe5f66e7\",\"content\":\"import { useCallback } from \\\"react\\\";\\nimport { useParams } from \\\"react-router-dom\\\";\\nimport { useCustomNavigate } from \\\"@/customization/hooks/use-custom-navigate\\\";\\nimport useAddFlow from \\\"@/hooks/flows/use-add-flow\\\";\\nimport useFlowBuilderWelcomeStore from \\\"@/stores/flowBuilderWelcomeStore\\\";\\n\\n/**\\n * Entry-point for the \\\"New Flow\\\" button on the home page: creates an empty\\n * flow on the backend, primes the FlowBuilderWelcome overlay store so the\\n * overlay surfaces on the freshly-loaded canvas, then routes the user to\\n * the new flow.\\n *\\n * Replaces the previous behavior of opening the full TemplatesModal as the\\n * primary path \u2014 the TemplatesModal is still reachable via the welcome's\\n * \\\"Browse more templates\\\" link.\\n */\\nexport function useStartNewFlow() {\\n  const addFlow = useAddFlow();\\n  const navigate = useCustomNavigate();\\n  const { folderId } = useParams();\\n  const openWelcome = useFlowBuilderWelcomeStore((state) => state.open);\\n\\n  return useCallback(async () => {\\n    const id = await addFlow();\\n    // Open BEFORE navigating so the canvas mounts with the welcome flag\\n    // already true \u2014 guarantees the overlay appears on the very first paint\\n    // instead of flashing the empty canvas then animating in.\\n    //\\n    // Tag the welcome with this flow's id so the mount can auto-close it if\\n    // the user navigates to a DIFFERENT flow (e.g. picks a template in the\\n    // TemplatesModal which spins up its own new flow).\\n    openWelcome(id);\\n    navigate(`/flow/${id}${folderId ? `/folder/${folderId}` : \\\"\\\"}`);\\n  }, [addFlow, navigate, folderId, openWelcome]);\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowSettingsComponent/__tests__/FlowSettingsComponent.spec.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cc93962622fbfa5ba25c4c143f7530884960d946715229cc30f678e329249869\",\"content\":\"import { fireEvent, render, screen, waitFor } from \\\"@testing-library/react\\\";\\nimport React from \\\"react\\\";\\nimport type { FlowType } from \\\"@/types/flow\\\";\\nimport FlowSettingsComponent from \\\"../index\\\";\\n\\njest.mock(\\\"@/components/ui/button\\\", () => ({\\n  Button: ({ children, loading, ...rest }) => (\\n    <button {...rest}>{children}</button>\\n  ),\\n}));\\n\\n// Simplify Radix Form to a native form that respects onSubmit\\ntype MockFormRootProps = {\\n  children: React.ReactNode;\\n  onSubmit?: React.FormEventHandler<HTMLFormElement>;\\n};\\n\\njest.mock(\\\"@radix-ui/react-form\\\", () => ({\\n  __esModule: true,\\n  Root: React.forwardRef<HTMLFormElement, MockFormRootProps>(\\n    ({ children, onSubmit }, ref) => (\\n      <form onSubmit={onSubmit} ref={ref}>\\n        {children}\\n      </form>\\n    ),\\n  ),\\n  Submit: ({ asChild, children }) => {\\n    if (asChild && React.isValidElement(children)) {\\n      return React.cloneElement(\\n        children as React.ReactElement<{ type?: \\\"submit\\\" }>,\\n        { type: \\\"submit\\\" },\\n      );\\n    }\\n    return <button type=\\\"submit\\\">Submit</button>;\\n  },\\n}));\\n\\nconst mockSave = jest.fn();\\njest.mock(\\\"@/hooks/flows/use-save-flow\\\", () => ({\\n  __esModule: true,\\n  default: () => mockSave,\\n}));\\n\\nlet mockSetSuccessData = jest.fn();\\njest.mock(\\\"@/stores/alertStore\\\", () => ({\\n  __esModule: true,\\n  default: (sel) => sel({ setSuccessData: mockSetSuccessData }),\\n}));\\n\\nlet mockSetCurrentFlow = jest.fn();\\nconst mockAutoSaveFlush = jest.fn();\\njest.mock(\\\"@/stores/flowStore\\\", () => {\\n  const useFlowStore = (sel) =>\\n    sel({\\n      currentFlow: {\\n        id: \\\"1\\\",\\n        name: \\\"Flow\\\",\\n        description: \\\"Desc\\\",\\n        locked: false,\\n      },\\n      setCurrentFlow: (...args) => mockSetCurrentFlow(...args),\\n      autoSaveFlow: { flush: (...args) => mockAutoSaveFlush(...args) },\\n    });\\n  return {\\n    __esModule: true,\\n    default: useFlowStore,\\n  };\\n});\\n\\nlet mockAutoSaving = false;\\nlet mockFlows: Array<{ name: string }> = [];\\njest.mock(\\\"@/stores/flowsManagerStore\\\", () => ({\\n  __esModule: true,\\n  default: (sel) => sel({ autoSaving: mockAutoSaving, flows: mockFlows }),\\n}));\\n\\n// Mock EditFlowSettings to expose simple controls that call the provided setters\\njest.mock(\\\"@/components/core/editFlowSettingsComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({\\n    setName,\\n    setDescription,\\n    setLocked,\\n  }: {\\n    setName?: (v: string) => void;\\n    setDescription?: (v: string) => void;\\n    setLocked?: (v: boolean) => void;\\n  }) => (\\n    <div>\\n      <button\\n        type=\\\"button\\\"\\n        data-testid=\\\"set-name-new\\\"\\n        onClick={() => setName?.(\\\"New Name\\\")}\\n      >\\n        set name\\n      </button>\\n      <button\\n        type=\\\"button\\\"\\n        data-testid=\\\"set-name-taken\\\"\\n        onClick={() => setName?.(\\\"Taken\\\")}\\n      >\\n        set taken\\n      </button>\\n      <button\\n        type=\\\"button\\\"\\n        data-testid=\\\"set-desc-new\\\"\\n        onClick={() => setDescription?.(\\\"New Desc\\\")}\\n      >\\n        set desc\\n      </button>\\n      <button\\n        type=\\\"button\\\"\\n        data-testid=\\\"toggle-lock\\\"\\n        onClick={() => setLocked?.(true)}\\n      >\\n        toggle lock\\n      </button>\\n    </div>\\n  ),\\n}));\\n\\ndescribe(\\\"FlowSettingsComponent\\\", () => {\\n  const baseFlow = {\\n    id: \\\"1\\\",\\n    name: \\\"Flow\\\",\\n    description: \\\"Desc\\\",\\n    locked: false,\\n  } as FlowType;\\n\\n  beforeEach(() => {\\n    jest.clearAllMocks();\\n    mockAutoSaving = false;\\n    mockFlows = [{ name: \\\"Flow\\\" }, { name: \\\"Other\\\" }];\\n    mockSetSuccessData = jest.fn();\\n    mockSetCurrentFlow = jest.fn();\\n    mockAutoSaveFlush.mockResolvedValue(undefined);\\n  });\\n\\n  it(\\\"renders and disables save when no changes\\\", () => {\\n    render(<FlowSettingsComponent flowData={baseFlow} open close={() => {}} />);\\n    const saveBtn = screen.getByTestId(\\\"save-flow-settings\\\");\\n    expect(saveBtn).toBeDisabled();\\n  });\\n\\n  it(\\\"enables save when name changes and autoSaving true triggers saveFlow and success\\\", async () => {\\n    mockAutoSaving = true;\\n    mockSave.mockResolvedValueOnce(undefined);\\n    const onClose = jest.fn();\\n\\n    render(<FlowSettingsComponent flowData={baseFlow} open close={onClose} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"set-name-new\\\"));\\n    const saveBtn = screen.getByTestId(\\\"save-flow-settings\\\");\\n    expect(saveBtn).not.toBeDisabled();\\n\\n    fireEvent.click(saveBtn);\\n\\n    await waitFor(() => {\\n      expect(mockAutoSaveFlush).toHaveBeenCalled();\\n      expect(mockSave).toHaveBeenCalledWith(\\n        expect.objectContaining({ name: \\\"New Name\\\" }),\\n      );\\n      expect(mockSetSuccessData).toHaveBeenCalledWith({\\n        title: \\\"Changes saved successfully\\\",\\n      });\\n      expect(onClose).toHaveBeenCalled();\\n    });\\n  });\\n\\n  it(\\\"flushes a pending canvas autosave before saving settings\\\", async () => {\\n    mockAutoSaving = true;\\n    mockAutoSaveFlush.mockReset();\\n    mockSave.mockReset();\\n    let releaseAutoSave: () => void = () => {};\\n    mockAutoSaveFlush.mockReturnValueOnce(\\n      new Promise<void>((resolve) => {\\n        releaseAutoSave = resolve;\\n      }),\\n    );\\n    mockSave.mockResolvedValueOnce(undefined);\\n\\n    render(<FlowSettingsComponent flowData={baseFlow} open close={() => {}} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"toggle-lock\\\"));\\n    fireEvent.click(screen.getByTestId(\\\"save-flow-settings\\\"));\\n\\n    await waitFor(() => expect(mockAutoSaveFlush).toHaveBeenCalled());\\n    expect(mockSave).not.toHaveBeenCalled();\\n\\n    releaseAutoSave();\\n\\n    await waitFor(() => {\\n      expect(mockSave).toHaveBeenCalledWith(\\n        expect.objectContaining({ locked: true }),\\n      );\\n    });\\n    expect(mockAutoSaveFlush.mock.invocationCallOrder[0]).toBeLessThan(\\n      mockSave.mock.invocationCallOrder[0],\\n    );\\n  });\\n\\n  it(\\\"non-autoSaving path sets current flow and closes\\\", () => {\\n    mockAutoSaving = false;\\n    const onClose = jest.fn();\\n\\n    render(<FlowSettingsComponent flowData={baseFlow} open close={onClose} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"set-desc-new\\\"));\\n    const saveBtn = screen.getByTestId(\\\"save-flow-settings\\\");\\n    expect(saveBtn).not.toBeDisabled();\\n    fireEvent.click(saveBtn);\\n\\n    expect(mockSetCurrentFlow).toHaveBeenCalledWith(\\n      expect.objectContaining({ description: \\\"New Desc\\\" }),\\n    );\\n    expect(onClose).toHaveBeenCalled();\\n  });\\n\\n  it(\\\"prevents saving when name is taken\\\", () => {\\n    mockFlows = [{ name: \\\"Taken\\\" }, { name: \\\"Flow\\\" }];\\n\\n    render(<FlowSettingsComponent flowData={baseFlow} open close={() => {}} />);\\n\\n    fireEvent.click(screen.getByTestId(\\\"set-name-taken\\\"));\\n    expect(screen.getByTestId(\\\"save-flow-settings\\\")).toBeDisabled();\\n  });\\n\\n  it(\\\"clicking cancel calls close\\\", () => {\\n    const onClose = jest.fn();\\n    render(<FlowSettingsComponent flowData={baseFlow} open close={onClose} />);\\n    fireEvent.click(screen.getByTestId(\\\"cancel-flow-settings\\\"));\\n    expect(onClose).toHaveBeenCalled();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowSettingsComponent/index.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a35ea906f724b7a06f211f1fb9516b87c438e809a571d245b726532d1cb52790\",\"content\":\"import * as Form from \\\"@radix-ui/react-form\\\";\\nimport { cloneDeep } from \\\"lodash\\\";\\nimport { useEffect, useRef, useState } from \\\"react\\\";\\nimport { useTranslation } from \\\"react-i18next\\\";\\nimport { Button } from \\\"@/components/ui/button\\\";\\nimport { useIsFlowReadOnly } from \\\"@/contexts/permissionsContext\\\";\\nimport useSaveFlow from \\\"@/hooks/flows/use-save-flow\\\";\\nimport useAlertStore from \\\"@/stores/alertStore\\\";\\nimport useFlowStore from \\\"@/stores/flowStore\\\";\\nimport useFlowsManagerStore from \\\"@/stores/flowsManagerStore\\\";\\nimport type { FlowType } from \\\"@/types/flow\\\";\\nimport EditFlowSettings from \\\"../editFlowSettingsComponent\\\";\\n\\ntype FlowSettingsComponentProps = {\\n  flowData?: FlowType;\\n  close: () => void;\\n  open: boolean;\\n};\\n\\nconst updateFlowWithFormValues = (\\n  baseFlow: FlowType,\\n  newName: string,\\n  newDescription: string,\\n  newLocked: boolean,\\n): FlowType => {\\n  const newFlow = cloneDeep(baseFlow);\\n  newFlow.name = newName;\\n  newFlow.description = newDescription;\\n  newFlow.locked = newLocked;\\n  return newFlow;\\n};\\n\\nconst buildInvalidNameList = (\\n  allFlows: FlowType[] | undefined,\\n  currentFlowName: string | undefined,\\n): string[] => {\\n  if (!allFlows) return [];\\n  const names = allFlows.map((f) => f?.name ?? \\\"\\\");\\n  return names.filter((n) => n !== (currentFlowName ?? \\\"\\\"));\\n};\\n\\nconst isSaveDisabled = (\\n  flow: FlowType | undefined,\\n  invalidNameList: string[],\\n  name: string,\\n  description: string,\\n  locked: boolean,\\n): boolean => {\\n  if (!flow) return true;\\n  const isNameChangedAndValid =\\n    !invalidNameList.includes(name) && flow.name !== name;\\n  const isDescriptionChanged = flow.description !== description;\\n  const isLockedChanged = flow.locked !== locked;\\n  return !(isNameChangedAndValid || isDescriptionChanged || isLockedChanged);\\n};\\n\\nconst FlowSettingsComponent = ({\\n  flowData,\\n  close,\\n  open,\\n}: FlowSettingsComponentProps): JSX.Element => {\\n  const { t } = useTranslation();\\n  const saveFlow = useSaveFlow();\\n  const currentFlow = useFlowStore((state) =>\\n    flowData ? undefined : state.currentFlow,\\n  );\\n  const setCurrentFlow = useFlowStore((state) => state.setCurrentFlow);\\n  const pendingAutoSave = useFlowStore((state) => state.autoSaveFlow);\\n  const setSuccessData = useAlertStore((state) => state.setSuccessData);\\n  const flows = useFlowsManagerStore((state) => state.flows);\\n  const flow = flowData ?? currentFlow;\\n  const isReadOnly = useIsFlowReadOnly(flow?.id);\\n  const [name, setName] = useState(flow?.name ?? \\\"\\\");\\n  const [description, setDescription] = useState(flow?.description ?? \\\"\\\");\\n  const [locked, setLocked] = useState<boolean>(flow?.locked ?? false);\\n  const [isSaving, setIsSaving] = useState(false);\\n  const [disableSave, setDisableSave] = useState(true);\\n  const autoSaving = useFlowsManagerStore((state) => state.autoSaving);\\n  const formRef = useRef<HTMLFormElement>(null);\\n\\n  useEffect(() => {\\n    setName(flow?.name ?? \\\"\\\");\\n    setDescription(flow?.description ?? \\\"\\\");\\n    setLocked(flow?.locked ?? false);\\n  }, [flow?.name, flow?.description, flow?.endpoint_name, open]);\\n\\n  function handleSubmit(event?: React.FormEvent<HTMLFormElement>): void {\\n    if (event) event.preventDefault();\\n    if (isReadOnly) return;\\n    setIsSaving(true);\\n    if (!flow) return;\\n    const newFlow = updateFlowWithFormValues(flow, name, description, locked);\\n\\n    if (autoSaving) {\\n      const persistSettings = async () => {\\n        try {\\n          // Canvas edits use a debounced save. Flush and await that exact save\\n          // before persisting settings so a stale canvas snapshot cannot land\\n          // after a lock-state update.\\n          await pendingAutoSave?.flush();\\n          await saveFlow(newFlow);\\n          setIsSaving(false);\\n          setSuccessData({ title: t(\\\"success.changesSaved\\\") });\\n          close();\\n        } catch {\\n          setIsSaving(false);\\n        }\\n      };\\n      void persistSettings();\\n    } else {\\n      setCurrentFlow(newFlow);\\n      setIsSaving(false);\\n      close();\\n    }\\n  }\\n\\n  const submitForm = () => {\\n    formRef.current?.requestSubmit();\\n  };\\n\\n  const [nameLists, setNameList] = useState<string[]>([]);\\n\\n  useEffect(() => {\\n    setNameList(buildInvalidNameList(flows, flow?.name));\\n  }, [flows]);\\n\\n  useEffect(() => {\\n    setDisableSave(isSaveDisabled(flow, nameLists, name, description, locked));\\n  }, [nameLists, flow, description, name, locked]);\\n  return (\\n    <Form.Root onSubmit={handleSubmit} ref={formRef}>\\n      <div className=\\\"flex flex-col gap-4\\\">\\n        <div className=\\\"flex flex-col gap-2\\\">\\n          <EditFlowSettings\\n            invalidNameList={nameLists}\\n            name={name}\\n            description={description}\\n            setName={setName}\\n            setDescription={setDescription}\\n            submitForm={submitForm}\\n            locked={locked}\\n            setLocked={setLocked}\\n            readOnly={isReadOnly}\\n          />\\n        </div>\\n        <div className=\\\"flex justify-end gap-2\\\">\\n          <Button\\n            variant=\\\"outline\\\"\\n            size=\\\"sm\\\"\\n            data-testid=\\\"cancel-flow-settings\\\"\\n            type=\\\"button\\\"\\n            onClick={() => close()}\\n          >\\n            {t(\\\"modal.cancelButton\\\")}\\n          </Button>\\n          <Form.Submit asChild>\\n            <Button\\n              variant=\\\"default\\\"\\n              size=\\\"sm\\\"\\n              data-testid=\\\"save-flow-settings\\\"\\n              loading={isSaving}\\n              disabled={disableSave || isReadOnly}\\n              title={isReadOnly ? t(\\\"version.readOnly\\\") : undefined}\\n            >\\n              {t(\\\"modal.saveButton\\\")}\\n            </Button>\\n          </Form.Submit>\\n        </div>\\n      </div>\\n    </Form.Root>\\n  );\\n};\\n\\nexport default FlowSettingsComponent;\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowToolbarComponent/components/__tests__/deploy-button.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bef4ebb5533651fb695987e8c94fa756467f4480571fbe040e33a6b646d6a59a\",\"content\":\"import { render, screen } from \\\"@testing-library/react\\\";\\nimport userEvent from \\\"@testing-library/user-event\\\";\\n\\n// ---------------------------------------------------------------------------\\n// Mocks\\n// ---------------------------------------------------------------------------\\n\\nlet mockCurrentFlowId: string | undefined = \\\"flow-1\\\";\\nlet mockIsPreparingDeploy = false;\\nlet mockChoiceDialogOpen = false;\\nlet mockDeployModalOpen = false;\\nconst mockHandleDeploy = jest.fn();\\nconst mockSetChoiceDialogOpen = jest.fn();\\nconst mockSetDeployModalOpen = jest.fn();\\n\\njest.mock(\\\"@/stores/utilityStore\\\", () => ({\\n  useUtilityStore: (\\n    selector: (s: { featureFlags: Record<string, unknown> }) => unknown,\\n  ) => selector({ featureFlags: { wxo_deployments: true } }),\\n}));\\n\\njest.mock(\\\"../deploy-choice-dialog/hooks/use-prepare-deploy\\\", () => ({\\n  usePrepareDeploy: () => ({\\n    currentFlowId: mockCurrentFlowId,\\n    isPreparingDeploy: mockIsPreparingDeploy,\\n    choiceDialogOpen: mockChoiceDialogOpen,\\n    setChoiceDialogOpen: mockSetChoiceDialogOpen,\\n    deployModalOpen: mockDeployModalOpen,\\n    setDeployModalOpen: mockSetDeployModalOpen,\\n    providers: [],\\n    pendingSnapshotVersionId: \\\"\\\",\\n    initialVersionByFlow: new Map(),\\n    stepperInitialProvider: undefined,\\n    stepperInitialInstance: undefined,\\n    handleDeploy: mockHandleDeploy,\\n    handleChooseNew: jest.fn(),\\n    handleUpdateComplete: jest.fn(),\\n    resetChoiceState: jest.fn(),\\n  }),\\n}));\\n\\njest.mock(\\n  \\\"@/pages/MainPage/pages/deploymentsPage/hooks/use-navigate-to-test\\\",\\n  () => ({\\n    useNavigateToTest: () => jest.fn(),\\n  }),\\n);\\n\\njest.mock(\\\"../deploy-choice-dialog\\\", () => ({\\n  __esModule: true,\\n  default: () => null,\\n}));\\n\\njest.mock(\\n  \\\"@/pages/MainPage/pages/deploymentsPage/components/deployment-stepper-modal\\\",\\n  () => ({\\n    __esModule: true,\\n    default: () => null,\\n  }),\\n);\\n\\n// Override global mock to forward className so animate-pulse can be tested\\njest.mock(\\\"@/components/common/genericIconComponent\\\", () => ({\\n  __esModule: true,\\n  default: ({ name, className }: { name: string; className?: string }) => (\\n    <span data-testid={`icon-${name}`} className={className ?? \\\"\\\"} />\\n  ),\\n}));\\n\\nimport DeployButton from \\\"../deploy-button\\\";\\n\\n// ---------------------------------------------------------------------------\\n// Setup\\n// ---------------------------------------------------------------------------\\n\\nbeforeEach(() => {\\n  jest.clearAllMocks();\\n  mockCurrentFlowId = \\\"flow-1\\\";\\n  mockIsPreparingDeploy = false;\\n  mockChoiceDialogOpen = false;\\n  mockDeployModalOpen = false;\\n});\\n\\n// ---------------------------------------------------------------------------\\n// Tests\\n// ---------------------------------------------------------------------------\\n\\ndescribe(\\\"DeployButton \u2014 rendering\\\", () => {\\n  it(\\\"renders the deploy button with data-testid\\\", () => {\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"deploy-btn-flow\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"renders Deploy text label\\\", () => {\\n    render(<DeployButton />);\\n\\n    expect(screen.getByText(\\\"Deploy\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"renders the Rocket icon\\\", () => {\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"icon-Rocket\\\")).toBeInTheDocument();\\n  });\\n});\\n\\ndescribe(\\\"DeployButton \u2014 disabled states\\\", () => {\\n  it(\\\"is enabled when currentFlowId is set and nothing is busy\\\", () => {\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"deploy-btn-flow\\\")).not.toBeDisabled();\\n  });\\n\\n  it(\\\"is disabled when currentFlowId is undefined\\\", () => {\\n    mockCurrentFlowId = undefined;\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"deploy-btn-flow\\\")).toBeDisabled();\\n  });\\n\\n  it(\\\"is disabled when isPreparingDeploy is true\\\", () => {\\n    mockIsPreparingDeploy = true;\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"deploy-btn-flow\\\")).toBeDisabled();\\n  });\\n\\n  it(\\\"is disabled when choiceDialogOpen is true\\\", () => {\\n    mockChoiceDialogOpen = true;\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"deploy-btn-flow\\\")).toBeDisabled();\\n  });\\n\\n  it(\\\"is disabled when deployModalOpen is true\\\", () => {\\n    mockDeployModalOpen = true;\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"deploy-btn-flow\\\")).toBeDisabled();\\n  });\\n});\\n\\ndescribe(\\\"DeployButton \u2014 click interaction\\\", () => {\\n  it(\\\"calls handleDeploy when button is clicked\\\", async () => {\\n    const user = userEvent.setup();\\n    render(<DeployButton />);\\n\\n    await user.click(screen.getByTestId(\\\"deploy-btn-flow\\\"));\\n\\n    expect(mockHandleDeploy).toHaveBeenCalledTimes(1);\\n  });\\n\\n  it(\\\"does not call handleDeploy when disabled with no currentFlowId\\\", async () => {\\n    const user = userEvent.setup();\\n    mockCurrentFlowId = undefined;\\n    render(<DeployButton />);\\n\\n    await user.click(screen.getByTestId(\\\"deploy-btn-flow\\\"));\\n\\n    expect(mockHandleDeploy).not.toHaveBeenCalled();\\n  });\\n\\n  it(\\\"does not call handleDeploy when disabled while preparing\\\", async () => {\\n    const user = userEvent.setup();\\n    mockIsPreparingDeploy = true;\\n    render(<DeployButton />);\\n\\n    await user.click(screen.getByTestId(\\\"deploy-btn-flow\\\"));\\n\\n    expect(mockHandleDeploy).not.toHaveBeenCalled();\\n  });\\n});\\n\\ndescribe(\\\"DeployButton \u2014 loading pulse\\\", () => {\\n  it(\\\"applies animate-pulse to Rocket icon when isPreparingDeploy is true\\\", () => {\\n    mockIsPreparingDeploy = true;\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"icon-Rocket\\\").className).toContain(\\n      \\\"animate-pulse\\\",\\n    );\\n  });\\n\\n  it(\\\"does not apply animate-pulse when isPreparingDeploy is false\\\", () => {\\n    mockIsPreparingDeploy = false;\\n    render(<DeployButton />);\\n\\n    expect(screen.getByTestId(\\\"icon-Rocket\\\").className).not.toContain(\\n      \\\"animate-pulse\\\",\\n    );\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowToolbarComponent/components/deploy-button.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d30dd3e4363c09b5081f35691ec19d4325d709ea07fe9767f3c21b17be58ceb6\",\"content\":\"import { useTranslation } from \\\"react-i18next\\\";\\nimport ForwardedIconComponent from \\\"@/components/common/genericIconComponent\\\";\\nimport { usePermissions } from \\\"@/contexts/permissionsContext\\\";\\nimport DeploymentStepperModal from \\\"@/pages/MainPage/pages/deploymentsPage/components/deployment-stepper-modal\\\";\\nimport { useNavigateToTest } from \\\"@/pages/MainPage/pages/deploymentsPage/hooks/use-navigate-to-test\\\";\\nimport { useUtilityStore } from \\\"@/stores/utilityStore\\\";\\nimport DeployChoiceDialog from \\\"./deploy-choice-dialog\\\";\\nimport { usePrepareDeploy } from \\\"./deploy-choice-dialog/hooks/use-prepare-deploy\\\";\\n\\nfunction DeployButtonInner() {\\n  const { t } = useTranslation();\\n  const {\\n    currentFlowId,\\n    isPreparingDeploy,\\n    choiceDialogOpen,\\n    setChoiceDialogOpen,\\n    deployModalOpen,\\n    setDeployModalOpen,\\n    providers,\\n    pendingSnapshotVersionId,\\n    initialVersionByFlow,\\n    stepperInitialProvider,\\n    stepperInitialInstance,\\n    handleDeploy,\\n    handleChooseNew,\\n    handleUpdateComplete,\\n    resetChoiceState,\\n  } = usePrepareDeploy();\\n\\n  const navigateToTest = useNavigateToTest();\\n\\n  const { can } = usePermissions();\\n  // Deploying provisions and runs the flow on an environment \u2192 gate on execute.\\n  const canDeploy = can(currentFlowId, \\\"execute\\\");\\n\\n  return (\\n    <>\\n      <button\\n        type=\\\"button\\\"\\n        onClick={handleDeploy}\\n        disabled={\\n          isPreparingDeploy ||\\n          choiceDialogOpen ||\\n          deployModalOpen ||\\n          !currentFlowId ||\\n          !canDeploy\\n        }\\n        className=\\\"relative inline-flex h-8 items-center justify-start gap-1.5 rounded bg-primary px-2 text-sm font-normal text-primary-foreground hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-50\\\"\\n        data-testid=\\\"deploy-btn-flow\\\"\\n      >\\n        <ForwardedIconComponent\\n          name=\\\"Rocket\\\"\\n          className={`h-4 w-4 ${isPreparingDeploy ? \\\"animate-pulse\\\" : \\\"\\\"}`}\\n        />\\n        <span className=\\\"font-normal text-mmd\\\">{t(\\\"misc.deploy\\\")}</span>\\n      </button>\\n      <DeployChoiceDialog\\n        open={choiceDialogOpen}\\n        setOpen={setChoiceDialogOpen}\\n        providers={providers}\\n        flowId={currentFlowId ?? \\\"\\\"}\\n        snapshotVersionId={pendingSnapshotVersionId}\\n        snapshotVersionTag={\\n          Array.from(initialVersionByFlow.values()).find(\\n            (entry) => entry.flowId === currentFlowId,\\n          )?.versionTag ?? \\\"\\\"\\n        }\\n        onChooseNew={handleChooseNew}\\n        onUpdateComplete={handleUpdateComplete}\\n        onTestDeployment={(deployment, providerId) => {\\n          resetChoiceState();\\n          navigateToTest(deployment, providerId);\\n        }}\\n      />\\n      <DeploymentStepperModal\\n        open={deployModalOpen}\\n        setOpen={setDeployModalOpen}\\n        initialFlowId={currentFlowId}\\n        initialVersionByFlow={initialVersionByFlow}\\n        initialProvider={stepperInitialProvider}\\n        initialInstance={stepperInitialInstance}\\n        onTestDeployment={(deployment, providerId) => {\\n          setDeployModalOpen(false);\\n          navigateToTest(deployment, providerId);\\n        }}\\n      />\\n    </>\\n  );\\n}\\n\\nexport default function DeployButton() {\\n  const deploymentsEnabled = useUtilityStore(\\n    (s) => s.featureFlags.wxo_deployments === true,\\n  );\\n  if (!deploymentsEnabled) return null;\\n  return <DeployButtonInner />;\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowToolbarComponent/components/deploy-choice-dialog/__tests__/deployment-phase.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"93acfa8c1daca528f424b02f5b806ea9b26256ecade4bf710f10d64075f514f9\",\"content\":\"import { render, screen } from \\\"@testing-library/react\\\";\\nimport userEvent from \\\"@testing-library/user-event\\\";\\nimport { Dialog } from \\\"@/components/ui/dialog\\\";\\nimport type {\\n  Deployment,\\n  ProviderAccount,\\n} from \\\"@/pages/MainPage/pages/deploymentsPage/types\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\nimport DeploymentPhaseContent from \\\"../deployment-phase\\\";\\n\\nconst makeProvider = (\\n  overrides: Partial<ProviderAccount> = {},\\n): ProviderAccount => ({\\n  id: \\\"p1\\\",\\n  name: \\\"WxO Prod\\\",\\n  provider_key: \\\"watsonx-orchestrate\\\",\\n  provider_data: { url: \\\"https://wxo.example.com\\\" },\\n  created_at: null,\\n  updated_at: null,\\n  ...overrides,\\n});\\n\\nconst makeDeployment = (\\n  id: string,\\n  name: string,\\n  overrides: Partial<Deployment> = {},\\n): Deployment => ({\\n  id,\\n  provider_id: \\\"prov-1\\\",\\n  description: null,\\n  type: \\\"agent\\\",\\n  created_at: \\\"2025-01-01\\\",\\n  updated_at: \\\"2025-01-01\\\",\\n  provider_data: { display_name: name, name: \\\"x\\\" },\\n  resource_key: \\\"x\\\",\\n  attached_count: 1,\\n  ...overrides,\\n});\\n\\nconst defaultProps = {\\n  selectedProvider: makeProvider(),\\n  deployments: [makeDeployment(\\\"d1\\\", \\\"My Bot\\\")],\\n  selectedDeployment: \\\"\\\",\\n  onSelectDeployment: jest.fn(),\\n  isLoading: false,\\n  isBusy: false,\\n  showBack: false,\\n  onBack: jest.fn(),\\n  onContinue: jest.fn(),\\n  onCancel: jest.fn(),\\n};\\n\\nfunction renderPhase(overrides: Partial<typeof defaultProps> = {}) {\\n  const props = { ...defaultProps, ...overrides };\\n  return render(\\n    <Dialog open>\\n      <DeploymentPhaseContent {...props} />\\n    </Dialog>,\\n  );\\n}\\n\\ndescribe(\\\"DeploymentPhaseContent\\\", () => {\\n  it(\\\"renders the dialog title and description\\\", () => {\\n    renderPhase();\\n\\n    expect(screen.getByText(\\\"Select Deployment\\\")).toBeInTheDocument();\\n    expect(\\n      screen.getByText(\\\"Deployments on WxO Prod for this flow.\\\"),\\n    ).toBeInTheDocument();\\n  });\\n\\n  it(\\\"renders each deployment plus the create-new option as radio items\\\", () => {\\n    renderPhase({\\n      deployments: [\\n        makeDeployment(\\\"d1\\\", \\\"My Bot\\\"),\\n        makeDeployment(\\\"d2\\\", \\\"Other Bot\\\"),\\n      ],\\n    });\\n\\n    expect(screen.getByRole(\\\"radio\\\", { name: /My Bot/ })).toBeInTheDocument();\\n    expect(\\n      screen.getByRole(\\\"radio\\\", { name: /Other Bot/ }),\\n    ).toBeInTheDocument();\\n    expect(\\n      screen.getByRole(\\\"radio\\\", { name: /Create new deployment/ }),\\n    ).toBeInTheDocument();\\n  });\\n\\n  it(\\\"translates the deployment type label instead of showing a raw literal\\\", () => {\\n    renderPhase({ deployments: [makeDeployment(\\\"d1\\\", \\\"My Bot\\\")] });\\n\\n    expect(screen.getByText(\\\"Agent\\\")).toBeInTheDocument();\\n    expect(screen.queryByText(/^agent$/)).not.toBeInTheDocument();\\n  });\\n\\n  it(\\\"falls back to the raw type value for an unrecognized deployment type\\\", () => {\\n    renderPhase({\\n      deployments: [\\n        makeDeployment(\\\"d1\\\", \\\"My Bot\\\", {\\n          type: \\\"custom-type\\\" as Deployment[\\\"type\\\"],\\n        }),\\n      ],\\n    });\\n\\n    expect(screen.getByText(\\\"custom-type\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"calls onSelectDeployment when a deployment is chosen\\\", async () => {\\n    const user = userEvent.setup();\\n    const onSelectDeployment = jest.fn();\\n    renderPhase({ onSelectDeployment });\\n\\n    await user.click(screen.getByRole(\\\"radio\\\", { name: /My Bot/ }));\\n\\n    expect(onSelectDeployment).toHaveBeenCalledWith(\\\"d1\\\");\\n  });\\n\\n  it(\\\"calls onContinue/onCancel/onBack\\\", async () => {\\n    const user = userEvent.setup();\\n    const onContinue = jest.fn();\\n    const onCancel = jest.fn();\\n    const onBack = jest.fn();\\n    renderPhase({ showBack: true, onContinue, onCancel, onBack });\\n\\n    await user.click(screen.getByRole(\\\"button\\\", { name: \\\"Continue\\\" }));\\n    await user.click(screen.getByRole(\\\"button\\\", { name: \\\"Cancel\\\" }));\\n    await user.click(screen.getByRole(\\\"button\\\", { name: \\\"Back\\\" }));\\n\\n    expect(onContinue).toHaveBeenCalled();\\n    expect(onCancel).toHaveBeenCalled();\\n    expect(onBack).toHaveBeenCalled();\\n  });\\n});\\n\\ndescribe(\\\"Accessibility\\\", () => {\\n  it(\\\"should_have_no_axe_violations in the loaded state\\\", async () => {\\n    const { container } = renderPhase();\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  it(\\\"should_have_no_axe_violations in the loading state\\\", async () => {\\n    const { container } = renderPhase({ isLoading: true, deployments: [] });\\n\\n    expect(await axe(container)).toHaveNoViolations();\\n  });\\n\\n  // Regression guard: the loading spinner previously gave zero indication\\n  // to screen reader users that anything was happening \u2014 no role=\\\"status\\\",\\n  // no aria-live, nothing. A sighted user sees a spinner; an AT user got\\n  // silence between the dialog title and the eventual radio list appearing.\\n  it(\\\"announces the loading state to assistive tech via role=status\\\", () => {\\n    renderPhase({ isLoading: true, deployments: [] });\\n\\n    expect(screen.getByRole(\\\"status\\\")).toHaveTextContent(\\n      \\\"Loading deployments...\\\",\\n    );\\n  });\\n\\n  it(\\\"does not render the loading status once deployments have loaded\\\", () => {\\n    renderPhase({ isLoading: false });\\n\\n    expect(screen.queryByRole(\\\"status\\\")).not.toBeInTheDocument();\\n  });\\n});\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/frontend/src/components/core/flowToolbarComponent/components/deploy-choice-dialog/__tests__/index.test.tsx\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0fdf527aaddda6d9c1f070e4eb310743cd63c96b4780d6365f4a2510d450a39\",\"content\":\"import { cleanup, render, screen, waitFor } from \\\"@testing-library/react\\\";\\nimport userEvent from \\\"@testing-library/user-event\\\";\\nimport { TooltipProvider } from \\\"@/components/ui/tooltip\\\";\\nimport type {\\n  Deployment,\\n  ProviderAccount,\\n} from \\\"@/pages/MainPage/pages/deploymentsPage/types\\\";\\nimport { axe } from \\\"@/utils/a11y-test\\\";\\n\\njest.mock(\\n  \\\"@/components/common/genericIconComponent\\\",\\n  () =>\\n    function MockIcon({ name }: { name: string }) {\\n      return <span data-testid={`icon-${name}`} />;\\n    },\\n);\\n\\n// ---------------------------------------------------------------------------\\n// Mocks\\n// ---------------------------------------------------------------------------\\n\\nlet mockDeploymentsData: { deployments: Deployment[] } | undefined = undefined;\\nlet mockIsLoadingDeployments = false;\\nconst mockPatchSnapshot = jest.fn();\\nconst mockShowError = jest.fn();\\n\\n// Simulate react-query caching: data is undefined until the first enabled\\n// fetch, then persists even when the query is later disabled.\\nlet _deploymentsCache: { deployments: Deployment[] } | undefined = undefined;\\n\\njest.mock(\\\"@/controllers/API/queries/deployments/use-get-deployments\\\", () => ({\\n  useGetDeployments: (_params: unknown, options?: { enabled?: boolean }) => {\\n    if (options?.enabled !== false && mockDeploymentsData !== undefined) {\\n      _deploymentsCache = mockDeploymentsData;\\n    }\\n    return {\\n      data:\\n        options?.enabled === false ? _deploymentsCache : mockDeploymentsData,\\n      isLoading: options?.enabled === false ? false : mockIsLoadingDeployments,\\n    };\\n  },\\n}));\\n\\njest.mock(\\\"@/controllers/API/queries/deployments\\\", () => ({\\n  usePatchSnapshot: () => ({\\n    mutateAsync: mockPatchSnapshot,\\n  }),\\n}));\\n\\njest.mock(\\n  \\\"@/pages/MainPage/pages/deploymentsPage/hooks/use-error-alert\\\",\\n  () => ({\\n    useErrorAlert: () => mockShowError,\\n  }),\\n);\\n\\n// biome-ignore lint/suspicious/noExplicitAny: test mock\\nlet mockAttachmentsData: Record<string, any> | undefined = undefined;\\nlet mockIsLoadingAttachments = false;\\nlet mockIsFetchingAttachments = false;\\n\\njest.mock(\\n  \\\"@/controllers/API/queries/deployments/use-get-deployment-attachments\\\",\\n  () => ({\\n    useGetDeploymentAttachments: (\\n      _params: unknown,\\n      options?: { enabled?: boolean },\\n    ) => ({\\n      data: options?.enabled === false ? undefined : mockAttachmentsData,\\n      isLoading: options?.enabled === false ? false : mockIsLoadingAttachments,\\n      isFetching:\\n        options?.enabled === false ? false : mockIsFetchingAttachments,\\n    }),\\n  }),\\n);\\n\\n// Stub StepDeployStatus to expose phase as text for assertions\\njest.mock(\\n  \\\"@/pages/MainPage/pages/deploymentsPage/components/step-deploy-status\\\",\\n  () => ({\\n    __esModule: true,\\n    default: ({ phase }: { phase: string }) => (\\n      <div data-testid=\\\"step-deploy-status\\\">{phase}</div>\\n    ),\\n  }),\\n);\\n\\nimport DeployChoiceDialog from \\\"../index\\\";\\n\\n// ---------------------------------------------------------------------------\\n// Factories\\n// ---------------------------------------------------------------------------\\n\\nconst makeProvider = (\\n  id = \\\"p1\\\",\\n  name = \\\"WxO Prod\\\",\\n  providerKey = \\\"watsonx-orchestrate\\\",\\n): ProviderAccount => ({\\n  id,\\n  name,\\n  provider_key: providerKey,\\n  provider_data: { url: \\\"https://wxo.example.com\\\" },\\n  created_at: null,\\n  updated_at: null,\\n});\\n\\nconst makeDeployment = (id = \\\"dep-1\\\", name = \\\"My Bot\\\"): Deployment => ({\\n  id,\\n  provider_id: \\\"prov-1\\\",\\n  description: null,\\n  type: \\\"agent\\\",\\n  created_at: \\\"2025-01-01\\\",\\n  updated_at: \\\"2025-01-01\\\",\\n  provider_data: { display_name: name, name: \\\"my_bot\\\" },\\n  resource_key: \\\"my_bot\\\",\\n  attached_count: 1,\\n});\\n\\n// ---------------------------------------------------------------------------\\n// Render helper\\n// ---------------------------------------------------------------------------\\n\\ninterface RenderOptions {\\n  open?: boolean;\\n  providers?: ProviderAccount[];\\n  flowId?: string;\\n  snapshotVersionId?: string;\\n  snapshotVersionTag?: string;\\n  onTestDeployment?: jest.Mock;\\n}\\n\\nfunction renderDialog(options: RenderOptions = {}) {\\n  const setOpen = jest.fn();\\n  const onChooseNew = jest.fn();\\n  const onUpdateComplete = jest.fn();\\n  const onTestDeployment = options.onTestDeployment ?? jest.fn();\\n\\n  render(\\n    <TooltipProvider>\\n      <DeployChoiceDialog\\n        open={options.open ?? true}\\n        setOpen={setOpen}\\n        providers={options.providers ?? [makeProvider()]}\\n        flowId={options.flowId ?? \\\"flow-1\\\"}\\n        snapshotVersionId={options.snapshotVersionId ?? \\\"snap-new\\\"}\\n        snapshotVersionTag={options.snapshotVersionTag ?? \\\"v2.0\\\"}\\n        onChooseNew={onChooseNew}\\n        onUpdateComplete={onUpdateComplete}\\n        onTestDeployment={onTestDeployment}\\n      />\\n    </TooltipProvider>,\\n  );\\n\\n  return { setOpen, onChooseNew, onUpdateComplete, onTestDeployment };\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Setup\\n// ---------------------------------------------------------------------------\\n\\nbeforeEach(() => {\\n  jest.clearAllMocks();\\n  mockDeploymentsData = undefined;\\n  mockIsLoadingDeployments = false;\\n  _deploymentsCache = undefined;\\n  mockAttachmentsData = undefined;\\n  mockIsLoadingAttachments = false;\\n  mockIsFetchingAttachments = false;\\n  mockPatchSnapshot.mockResolvedValue({\\n    flow_version_id: \\\"v-new\\\",\\n    provider_snapshot_id: \\\"snap-1\\\",\\n  });\\n});\\n\\n// ---------------------------------------------------------------------------\\n// Tests \u2014 closed state\\n// ---------------------------------------------------------------------------\\n\\ndescribe(\\\"DeployChoiceDialog \u2014 closed state\\\", () => {\\n  it(\\\"does not render dialog content when open is false\\\", () => {\\n    renderDialog({ open: false });\\n\\n    expect(screen.queryByText(\\\"Select Provider\\\")).not.toBeInTheDocument();\\n    expect(screen.queryByText(\\\"Select Deployment\\\")).not.toBeInTheDocument();\\n  });\\n});\\n\\n// ---------------------------------------------------------------------------\\n// Tests \u2014 provider phase\\n// ---------------------------------------------------------------------------\\n\\ndescribe(\\\"DeployChoiceDialog \u2014 provider phase\\\", () => {\\n  it(\\\"shows provider phase title when 2+ providers given\\\", () => {\\n    renderDialog({\\n      providers: [makeProvider(\\\"p1\\\"), makeProvider(\\\"p2\\\", \\\"WxO Dev\\\")],\\n    });\\n\\n    expect(screen.getByText(\\\"Select Provider\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"renders all provider names\\\", () => {\\n    renderDialog({\\n      providers: [\\n        makeProvider(\\\"p1\\\", \\\"WxO Prod\\\"),\\n        makeProvider(\\\"p2\\\", \\\"WxO Dev\\\"),\\n      ],\\n    });\\n\\n    expect(screen.getByText(\\\"WxO Prod\\\")).toBeInTheDocument();\\n    expect(screen.getByText(\\\"WxO Dev\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"Cancel button calls setOpen(false)\\\", async () => {\\n    const user = userEvent.setup();\\n    const { setOpen } = renderDialog({\\n      providers: [makeProvider(\\\"p1\\\"), makeProvider(\\\"p2\\\", \\\"WxO Dev\\\")],\\n    });\\n\\n    await user.click(screen.getByRole(\\\"button\\\", { name: \\\"Cancel\\\" }));\\n\\n    expect(setOpen).toHaveBeenCalledWith(false);\\n  });\\n\\n  it(\\\"Continue button advances to deployments phase\\\", async () => {\\n    const user = userEvent.setup();\\n    renderDialog({\\n      providers: [makeProvider(\\\"p1\\\"), makeProvider(\\\"p2\\\", \\\"WxO Dev\\\")],\\n    });\\n\\n    await user.click(screen.getByRole(\\\"button\\\", { name: \\\"Continue\\\" }));\\n\\n    expect(screen.getByText(\\\"Select Deployment\\\")).toBeInTheDocument();\\n  });\\n});\\n\\n// ---------------------------------------------------------------------------\\n// Tests \u2014 deployments phase\\n// ---------------------------------------------------------------------------\\n\\ndescribe(\\\"DeployChoiceDialog \u2014 deployments phase\\\", () => {\\n  it(\\\"skips provider phase when exactly 1 provider\\\", () => {\\n    renderDialog({ providers: [makeProvider()] });\\n\\n    expect(screen.getByText(\\\"Select Deployment\\\")).toBeInTheDocument();\\n    expect(screen.queryByText(\\\"Select Provider\\\")).not.toBeInTheDocument();\\n  });\\n\\n  it(\\\"always shows Create new deployment option\\\", () => {\\n    renderDialog({ providers: [makeProvider()] });\\n\\n    expect(screen.getByText(\\\"Create new deployment\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"shows existing deployment names from API data\\\", () => {\\n    mockDeploymentsData = { deployments: [makeDeployment(\\\"d1\\\", \\\"Sales Bot\\\")] };\\n    renderDialog({ providers: [makeProvider()] });\\n\\n    expect(screen.getByText(\\\"Sales Bot\\\")).toBeInTheDocument();\\n  });\\n\\n  it(\\\"shows loading spinner when isLoadingDeployments is true\\\", () => {\\n    mockIsLoadingDeployments = true;\\n    mockDeploymentsData = undefined;\\n    renderDialog({ providers: [makeProvider()] });\\n\\n    // RadioGroup hidden, spinner shown \u2014 no deployment labels\\n    expect(screen.queryByText(\\\"Create new deployment\\\")).not.toBeInTheDocument();\\n  });\\n\\n  it(\\\"hides Back button when only 1 provider\\\", () => {\\n    renderDialog({ providers: [makeProvider()] });\\n\\n    expect(\\n      screen.queryByRole(\\\"button\\\", { name: \\\"Back\\\" }),\\n    ).not.toBeInTheDocument();\\n  });\\n\\n  it(\\\"shows Back button in deployments phase when 2+ providers\\\", async () => {\\n    const user = userEvent.setup();\\n    renderDialog({\\n      providers: [makeProvider(\\\"p1\\\"), makeProvider(\\\"p2\\\", \\\"WxO Dev\\\")],\\n    });\\n\\n    await user.click(screen.getByRole(\\\"button\\\", { name: \\\"Continue\\\" }));\\n\\n    expect(screen.getByRole(\\\"button\\\", { name: \\\"Back\\\" })).toBeInTheDocument();\\n  });\\n\\n  it(\\\"Back from deployments returns to provider phase\\\", async () => {\\n    const user = userEvent.setup();\\n    renderDialog({\\n      providers: [makeProvider(\\\"p1\\\"), makeProvider(\\\"p2\\\", \\\"WxO ";
